// businessType is a free-text field the workspace can edit after onboarding, so
// the exact onboarding labels are matched first and the rest falls back to a
// keyword sweep that also covers the Turkish words a user is likely to type.
const REPAIR_INTAKE_PRESET_BY_BUSINESS_TYPE = {
  "jewellery studio": "jewellery",
  "tailor / alteration studio": "tailoring",
  "repair service": "general"
};

const REPAIR_INTAKE_PRESET_KEYWORDS = [
  { presetId: "jewellery", terms: ["jewel", "goldsmith", "silversmith", "kuyum", "mucevher", "mücevher", "altin", "altın"] },
  { presetId: "watch", terms: ["watch", "clock", "horolog", "saat"] },
  { presetId: "electronics", terms: ["electronic", "phone", "mobile", "computer", "laptop", "device", "elektronik", "telefon", "bilgisayar"] },
  { presetId: "tailoring", terms: ["tailor", "alteration", "garment", "seamstress", "terzi", "dikis", "dikiş"] },
  { presetId: "shoeLeather", terms: ["shoe", "cobbler", "leather", "ayakkabi", "ayakkabı", "deri", "saraciye", "saraciye"] },
  { presetId: "furniture", terms: ["furniture", "upholster", "carpent", "joinery", "mobilya", "doseme", "döşeme", "marangoz"] },
  { presetId: "bicycle", terms: ["bicycle", "bike", "cycle", "bisiklet"] },
  { presetId: "automotive", terms: ["automotive", "vehicle", "garage", "motor", "car ", "oto", "araba", "arac", "araç"] },
  { presetId: "instrument", terms: ["instrument", "guitar", "piano", "luthier", "muzik", "müzik", "enstruman", "enstrüman"] }
];

function repairIntakePresetById(presetId) {
  const wanted = String(presetId || "").trim();
  return REPAIR_INTAKE_PRESETS.find((preset) => preset.id === wanted) || null;
}

function repairIntakePresetIdForBusinessType(businessType) {
  const raw = String(businessType || "").trim().toLowerCase();
  if (!raw) return "general";
  const exact = REPAIR_INTAKE_PRESET_BY_BUSINESS_TYPE[raw];
  if (exact) return exact;
  for (const entry of REPAIR_INTAKE_PRESET_KEYWORDS) {
    if (entry.terms.some((term) => raw.includes(term))) return entry.presetId;
  }
  return "general";
}

function repairIntakeFieldsForBusinessType(businessType) {
  const preset = repairIntakePresetById(repairIntakePresetIdForBusinessType(businessType));
  return (preset ? preset.fields : REPAIR_INTAKE_PRESETS[0].fields).map((field) => ({ ...field }));
}

