// One calculation, two callers. The preview has to describe exactly what the
// apply will write, so both read the plan from here rather than each deriving
// its own idea of what would change.
function financialRecalculationPlanForOrder(orderData, financialSettings) {
  const paidAmount = roundMoneyValue(orderData.paidAmount);
  const remainingAmount = roundMoneyValue(orderData.remainingAmount);
  const watchPurchasePrice = roundMoneyValue(orderData.watchPurchasePrice);
  const deliveryCost = roundMoneyValue(orderData.deliveryCost);
  const paymentDate = dateFromFirestore(orderData.paymentDate, new Date());
  const customRemainingTotal = orderCustomRemainingTotal(orderData.customFields);
  const customExpenseTotal = orderCustomExpenseTotal(orderData.customFields);
  const orderValue = paidAmount + remainingAmount + customRemainingTotal;
  const paymentFee = roundMoneyValue((orderValue * cleanPercentageNumber(financialSettings.feePercentage, 3)) / 100);
  const taxType = financialTaxTypeForPaymentDate(financialSettings, paymentDate);

  // An order imported from a shop carries that shop's own tax figure. Keying
  // off the integration marker rather than off "has a tax amount" matters:
  // a zero-rated or exempt import has no amount either, and would otherwise
  // have our default rate invented onto it.
  const integrationSource = cleanOrderText(orderData.customFields && orderData.customFields.Source, "", 60);
  const taxCameFromIntegration = Boolean(integrationSource) && cleanTaxRate(orderData.taxRate) === 0;

  const taxRate = cleanTaxRate(orderData.taxRate) || cleanPercentageNumber(financialSettings.defaultTaxRate, 20);
  const taxAmount = webFinanceTaxAmount({
    paidAmount,
    remainingAmount,
    customRemainingTotal,
    customExpenseTotal,
    watchPurchasePrice,
    paymentFee,
    deliveryCost,
    taxRate,
    taxType
  });

  const changes = {};
  const feeBefore = roundMoneyValue(orderData.paymentFee);
  if (feeBefore !== paymentFee) changes.paymentFee = { from: feeBefore, to: paymentFee };

  const taxBefore = roundMoneyValue(orderData.taxAmount);
  let taxAfter = taxBefore;
  if (!taxCameFromIntegration) {
    if (cleanTaxType(orderData.taxType) !== taxType) {
      changes.taxType = { from: cleanTaxType(orderData.taxType) || "-", to: taxType };
    }
    if (cleanTaxRate(orderData.taxRate) !== taxRate) {
      changes.taxRate = { from: cleanTaxRate(orderData.taxRate), to: taxRate };
    }
    if (taxBefore !== taxAmount) changes.taxAmount = { from: taxBefore, to: taxAmount };
    taxAfter = taxAmount;
  }

  return {
    taxCameFromIntegration,
    integrationSource,
    inTrash: orderData.isDeleted === true,
    zeroRateForcedToDefault: !taxCameFromIntegration && cleanTaxRate(orderData.taxRate) === 0 && taxRate > 0,
    changes,
    feeBefore,
    feeAfter: paymentFee,
    taxBefore,
    taxAfter
  };
}

async function loadFinancialRecalculationContext(request) {
  const { uid, companyId, companyData } = await requireWorkspaceForBilling(request, false);
  if (!uidCanEditWorkspaceSettings(companyData, uid)) {
    throw new HttpsError("permission-denied", "Your workspace role cannot recalculate Financial Settings.");
  }
  requireWorkspaceAreaAccess(companyData, uid, "financialInfo", "Financial Info is not enabled for your workspace account.");
  if (billingEntitlementsForCompany(companyData).advancedFinanceEnabled !== true) {
    throw new HttpsError("failed-precondition", "Advanced Financial Settings are available on NivaDesk Pro and Team.");
  }
  const settingsSnapshot = await companySettingsDocRef(companyId).get();
  return {
    uid,
    companyId,
    email: String(request.auth?.token?.email || ""),
    financialSettings: financialSettingsFromData(settingsSnapshot.exists ? settingsSnapshot.data() || {} : {})
  };
}

const RECALCULATION_SAMPLE_LIMIT = 200;

// Says what pressing the button would do, and writes nothing. Every input is
// already on the order document, so this is a read of the same query the apply
// runs — no dry-run flag threaded through the write path.
exports.previewFinancialRecalculationForOrders = onCall(
  { region: "europe-west2", timeoutSeconds: 300, memory: "512MiB" },
  async (request) => {
    const { companyId, financialSettings } = await loadFinancialRecalculationContext(request);
    const snapshot = await admin.firestore().collection("siparisler").where("companyId", "==", companyId).get();

    let wouldUpdateCount = 0;
    let skippedIntegrationCount = 0;
    let trashedAffectedCount = 0;
    let zeroRateForcedToDefaultCount = 0;
    let taxBefore = 0;
    let taxAfter = 0;
    let feeBefore = 0;
    let feeAfter = 0;
    const sample = [];

    for (const orderDoc of snapshot.docs) {
      const orderData = orderDoc.data() || {};
      const plan = financialRecalculationPlanForOrder(orderData, financialSettings);
      taxBefore += plan.taxBefore;
      taxAfter += plan.taxAfter;
      feeBefore += plan.feeBefore;
      feeAfter += plan.feeAfter;
      if (plan.taxCameFromIntegration) skippedIntegrationCount += 1;
      if (Object.keys(plan.changes).length === 0) continue;
      wouldUpdateCount += 1;
      if (plan.inTrash) trashedAffectedCount += 1;
      if (plan.zeroRateForcedToDefault) zeroRateForcedToDefaultCount += 1;
      if (sample.length < RECALCULATION_SAMPLE_LIMIT) {
        sample.push({
          orderId: orderDoc.id,
          label: cleanOrderText(orderData.invoiceNumber, "", 60)
            || cleanOrderText(orderData.customerName, "Project", 60),
          inTrash: plan.inTrash,
          taxBefore: plan.taxBefore,
          taxAfter: plan.taxAfter,
          feeBefore: plan.feeBefore,
          feeAfter: plan.feeAfter
        });
      }
    }

    return {
      ok: true,
      companyId,
      orderCount: snapshot.size,
      wouldUpdateCount,
      skippedIntegrationCount,
      trashedAffectedCount,
      zeroRateForcedToDefaultCount,
      truncated: wouldUpdateCount > sample.length,
      totals: {
        taxBefore: roundMoneyValue(taxBefore),
        taxAfter: roundMoneyValue(taxAfter),
        taxDelta: Math.round((taxAfter - taxBefore) * 100) / 100,
        feeBefore: roundMoneyValue(feeBefore),
        feeAfter: roundMoneyValue(feeAfter),
        feeDelta: Math.round((feeAfter - feeBefore) * 100) / 100
      },
      sample
    };
  }
);

exports.recalculateFinancialSettingsForOrders = onCall(
  { region: "europe-west2", timeoutSeconds: 300, memory: "512MiB" },
  async (request) => {
  const { uid, companyId, email, financialSettings } = await loadFinancialRecalculationContext(request);

  const db = admin.firestore();
  const snapshot = await db.collection("siparisler").where("companyId", "==", companyId).get();
  let batch = db.batch();
  let batchCount = 0;
  let updatedCount = 0;

  async function commitBatchIfNeeded(force = false) {
    if (batchCount === 0) return;
    if (!force && batchCount < 400) return;
    await batch.commit();
    batch = db.batch();
    batchCount = 0;
  }

  for (const orderDoc of snapshot.docs) {
    const orderData = orderDoc.data() || {};
    const plan = financialRecalculationPlanForOrder(orderData, financialSettings);
    const changedFields = Object.keys(plan.changes);
    if (changedFields.length === 0) continue;

    const updates = {};
    for (const field of changedFields) updates[field] = plan.changes[field].to;

    // Per-order finance edits already record themselves in the history log; a
    // bulk run that did not was the one way a VAT figure could change with
    // nothing to say who changed it.
    if (plan.changes.taxAmount) {
      updates.historyLog = historyLogWithEntry(
        orderData,
        "VAT recalculated",
        amountHistoryValue(plan.changes.taxAmount.from),
        amountHistoryValue(plan.changes.taxAmount.to)
      );
    }

    batch.set(orderDoc.ref, {
      ...updates,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedByUid: uid,
      updatedByEmail: email,
      source: orderData.source || "web"
    }, { merge: true });
    batchCount += 1;
    updatedCount += 1;
    await commitBatchIfNeeded(false);
  }

  await commitBatchIfNeeded(true);

  return {
    ok: true,
    companyId,
    updatedCount,
    message: `Recalculated ${updatedCount} orders.`
  };
});

// Bulk-clear VAT/tax on every order in the workspace. For businesses where VAT
// does not apply (e.g. exports / not VAT-registered) so they don't have to zero
// each order by hand. Sets taxAmount/taxRate to 0 and clears taxType.
const CLEAR_TAX_UNDO_LIMIT = 4000;

function clearTaxRunRef(companyId, runId) {
  return admin.firestore().collection("companies").doc(companyId).collection("financeBulkRuns").doc(runId);
}

// Says what "Remove VAT from all orders" would touch. The button's own copy said
// it could not be undone, and that was true — there was no before-image anywhere.
exports.previewClearAllOrdersTax = onCall(
  { region: "europe-west2", timeoutSeconds: 300, memory: "512MiB" },
  async (request) => {
    const { uid, companyId, companyData } = await requireWorkspaceForBilling(request, false);
    if (!uidCanEditWorkspaceSettings(companyData, uid)) {
      throw new HttpsError("permission-denied", "Your workspace role cannot edit Financial Settings.");
    }
    requireWorkspaceAreaAccess(companyData, uid, "financialInfo", "Financial Info is not enabled for your workspace account.");

    const snapshot = await admin.firestore().collection("siparisler").where("companyId", "==", companyId).get();
    let wouldClearCount = 0;
    let trashedAffectedCount = 0;
    let taxBefore = 0;
    const sample = [];
    for (const orderDoc of snapshot.docs) {
      const orderData = orderDoc.data() || {};
      const tax = roundMoneyValue(orderData.taxAmount);
      if (tax === 0 && cleanTaxRate(orderData.taxRate) === 0) continue;
      wouldClearCount += 1;
      taxBefore += tax;
      if (orderData.isDeleted === true) trashedAffectedCount += 1;
      if (sample.length < 3) {
        sample.push({
          orderId: orderDoc.id,
          label: cleanOrderText(orderData.invoiceNumber, "", 60) || cleanOrderText(orderData.customerName, "Project", 60),
          inTrash: orderData.isDeleted === true,
          taxBefore: tax,
          taxAfter: 0
        });
      }
    }
    return {
      ok: true,
      companyId,
      orderCount: snapshot.size,
      wouldClearCount,
      trashedAffectedCount,
      undoAvailable: wouldClearCount <= CLEAR_TAX_UNDO_LIMIT,
      totals: { taxBefore: roundMoneyValue(taxBefore), taxAfter: 0, taxDelta: -roundMoneyValue(taxBefore) },
      sample
    };
  }
);

exports.clearAllOrdersTax = onCall(
  { region: "europe-west2", timeoutSeconds: 300, memory: "512MiB" },
  async (request) => {
  const { uid, companyId, companyData } = await requireWorkspaceForBilling(request, false);
  if (!uidCanEditWorkspaceSettings(companyData, uid)) {
    throw new HttpsError("permission-denied", "Your workspace role cannot edit Financial Settings.");
  }
  requireWorkspaceAreaAccess(companyData, uid, "financialInfo", "Financial Info is not enabled for your workspace account.");

  const db = admin.firestore();
  const email = String(request.auth?.token?.email || "");
  const snapshot = await db.collection("siparisler").where("companyId", "==", companyId).get();
  let batch = db.batch();
  let batchCount = 0;
  let clearedCount = 0;
  // The before-image is what makes this reversible. Kept small on purpose: three
  // numbers per order, and only for orders that actually change.
  const beforeImages = [];

  async function commitBatchIfNeeded(force = false) {
    if (batchCount === 0) return;
    if (!force && batchCount < 400) return;
    await batch.commit();
    batch = db.batch();
    batchCount = 0;
  }

  for (const orderDoc of snapshot.docs) {
    const orderData = orderDoc.data() || {};
    const previousTax = roundMoneyValue(orderData.taxAmount);
    const previousRate = cleanTaxRate(orderData.taxRate);
    const previousType = cleanTaxType(orderData.taxType);
    if (previousTax === 0 && previousRate === 0 && !previousType) continue;
    if (beforeImages.length < CLEAR_TAX_UNDO_LIMIT) {
      beforeImages.push({ orderId: orderDoc.id, taxAmount: previousTax, taxRate: previousRate, taxType: previousType });
    }
    batch.set(orderDoc.ref, {
      taxAmount: 0,
      taxRate: 0,
      taxType: "",
      historyLog: historyLogWithEntry(orderData, "VAT removed", amountHistoryValue(previousTax), amountHistoryValue(0)),
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedByUid: uid,
      updatedByEmail: email,
      source: orderData.source || "web"
    }, { merge: true });
    batchCount += 1;
    clearedCount += 1;
    await commitBatchIfNeeded(false);
  }
  await commitBatchIfNeeded(true);

  const runId = crypto.randomUUID();
  if (clearedCount > 0) {
    await clearTaxRunRef(companyId, runId).set({
      type: "clearTax",
      runAtMs: Date.now(),
      byUid: uid,
      byEmail: email,
      clearedCount,
      truncated: clearedCount > beforeImages.length,
      beforeImages
    });
  }

  return {
    ok: true,
    companyId,
    clearedCount,
    runId: clearedCount > 0 ? runId : "",
    undoAvailable: clearedCount > 0 && clearedCount <= CLEAR_TAX_UNDO_LIMIT,
    message: `Cleared VAT/tax on ${clearedCount} orders.`
  };
});

// Puts back exactly what the removal took away, order by order.
exports.undoClearAllOrdersTax = onCall(
  { region: "europe-west2", timeoutSeconds: 300, memory: "512MiB" },
  async (request) => {
    const { uid, companyId, companyData } = await requireWorkspaceForBilling(request, false);
    if (!uidCanEditWorkspaceSettings(companyData, uid)) {
      throw new HttpsError("permission-denied", "Your workspace role cannot edit Financial Settings.");
    }
    requireWorkspaceAreaAccess(companyData, uid, "financialInfo", "Financial Info is not enabled for your workspace account.");

    const runId = cleanOrderText(request.data && request.data.runId, "", 80);
    if (!runId) throw new HttpsError("invalid-argument", "runId is required.");
    const runSnap = await clearTaxRunRef(companyId, runId).get();
    if (!runSnap.exists) throw new HttpsError("not-found", "That run is no longer available to undo.");
    const run = runSnap.data() || {};
    if (run.undoneAtMs) throw new HttpsError("failed-precondition", "That run has already been undone.");

    const db = admin.firestore();
    const images = Array.isArray(run.beforeImages) ? run.beforeImages : [];
    let batch = db.batch();
    let batchCount = 0;
    let restoredCount = 0;

    for (const image of images) {
      const orderId = cleanOrderText(image && image.orderId, "", 200);
      if (!orderId) continue;
      batch.set(db.collection("siparisler").doc(orderId), {
        taxAmount: roundMoneyValue(image.taxAmount),
        taxRate: cleanTaxRate(image.taxRate),
        taxType: cleanTaxType(image.taxType),
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        updatedByUid: uid
      }, { merge: true });
      batchCount += 1;
      restoredCount += 1;
      if (batchCount >= 400) {
        await batch.commit();
        batch = db.batch();
        batchCount = 0;
      }
    }
    if (batchCount > 0) await batch.commit();
    await clearTaxRunRef(companyId, runId).set({ undoneAtMs: Date.now(), undoneByUid: uid }, { merge: true });

    return { ok: true, companyId, restoredCount, message: `Restored VAT on ${restoredCount} orders.` };
  }
);

// Manually fold one order's payment(s) into another (e.g. an installment that the
// auto-combine split off, or two orders that should be one). The source order's
// paidAmount + payment entries move onto the target, and the source is soft-deleted
// (moved to Trash, recoverable) so it isn't double-counted.
exports.mergeOrderIntoOrder = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyData } = await requireNotificationWorkspaceAccess(request);
  const access = workspaceMemberAccess(companyData, uid);
  if (access.orders === false) {
    throw new HttpsError("permission-denied", "Your workspace role cannot edit orders.");
  }
  const data = request.data || {};
  const sourceId = String(data.sourceOrderId || "").trim();
  const targetId = String(data.targetOrderId || "").trim();
  if (!sourceId || !targetId || sourceId === targetId) {
    throw new HttpsError("invalid-argument", "Choose a different target order to merge into.");
  }

  const db = admin.firestore();
  const sourceRef = orderDocRef(sourceId);
  const targetRef = orderDocRef(targetId);
  const [sourceSnap, targetSnap] = await Promise.all([sourceRef.get(), targetRef.get()]);
  if (!sourceSnap.exists || !targetSnap.exists) {
    throw new HttpsError("not-found", "One of the orders no longer exists.");
  }
  const source = sourceSnap.data() || {};
  const target = targetSnap.data() || {};
  if (source.companyId !== companyId || target.companyId !== companyId) {
    throw new HttpsError("permission-denied", "These orders are not in your workspace.");
  }

  const email = String(request.auth?.token?.email || "");
  const sourcePaid = roundMoneyValue(source.paidAmount);
  const sourcePayments = Array.isArray(source.payments) ? source.payments : [];
  const movedPayments = sourcePayments.length > 0
    ? sourcePayments
    : (sourcePaid > 0 ? [{
        id: crypto.randomUUID(),
        amount: sourcePaid,
        date: dateFromFirestore(source.paymentDate, new Date()),
        method: String(source.paymentMethod || ""),
        note: `Merged from order ${sourceId}`,
        createdByUid: "",
        createdByEmail: ""
      }] : []);
  const targetPayments = Array.isArray(target.payments) ? target.payments.slice() : [];
  const mergedPayments = targetPayments.concat(movedPayments);

  const sourceLabel = String(source.invoiceNumber || "").trim()
    || String(source.designName || "").trim()
    || `#${sourceId.slice(-6)}`;
  const batch = db.batch();
  batch.set(targetRef, {
    paidAmount: roundMoneyValue(target.paidAmount) + sourcePaid,
    remainingAmount: Math.max(0, roundMoneyValue(target.remainingAmount) - sourcePaid),
    payments: mergedPayments,
    historyLog: historyLogWithEntry(target, "Order merged", sourceLabel, amountHistoryValue(sourcePaid)),
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedByUid: uid,
    updatedByEmail: email
  }, { merge: true });
  batch.set(sourceRef, {
    isDeleted: true,
    deletedAt: admin.firestore.FieldValue.serverTimestamp(),
    mergedIntoOrderId: targetId,
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedByUid: uid,
    updatedByEmail: email
  }, { merge: true });
  await batch.commit();

  return {
    ok: true,
    targetOrderId: targetId,
    mergedAmount: sourcePaid,
    message: "Order merged. The source order moved to Trash."
  };
});

// Multi-select merge: combine several selected orders into one chosen primary.
// Same financial semantics as mergeOrderIntoOrder (move payments + paidAmount,
// reduce the primary's remaining, send each source to Trash with a
// mergedIntoOrderId pointer) but applied to N sources in a single atomic batch.
// Every platform (Mac/iPhone, Android, Web) calls this so the result is identical.
exports.mergeOrders = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyData } = await requireNotificationWorkspaceAccess(request);
  const access = workspaceMemberAccess(companyData, uid);
  if (access.orders === false) {
    throw new HttpsError("permission-denied", "Your workspace role cannot edit orders.");
  }
  const data = request.data || {};
  const primaryId = String(data.primaryOrderId || "").trim();
  const rawSources = Array.isArray(data.sourceOrderIds) ? data.sourceOrderIds : [];
  const sourceIds = Array.from(new Set(rawSources.map((id) => String(id || "").trim()).filter(Boolean)))
    .filter((id) => id !== primaryId);
  if (!primaryId || sourceIds.length === 0) {
    throw new HttpsError("invalid-argument", "Select a primary order and at least one other order to merge.");
  }
  if (sourceIds.length > 50) {
    throw new HttpsError("invalid-argument", "Too many orders selected to merge at once.");
  }

  const db = admin.firestore();
  const primaryRef = orderDocRef(primaryId);
  const sourceRefs = sourceIds.map((id) => orderDocRef(id));
  const snaps = await Promise.all([primaryRef.get(), ...sourceRefs.map((ref) => ref.get())]);

  const primarySnap = snaps[0];
  if (!primarySnap.exists) {
    throw new HttpsError("not-found", "The primary order no longer exists.");
  }
  const primary = primarySnap.data() || {};
  if (primary.companyId !== companyId) {
    throw new HttpsError("permission-denied", "These orders are not in your workspace.");
  }

  const email = String(request.auth?.token?.email || "");
  let mergedPaid = roundMoneyValue(primary.paidAmount);
  let mergedPayments = Array.isArray(primary.payments) ? primary.payments.slice() : [];
  let mergedAmount = 0;
  let mergedCount = 0;

  const batch = db.batch();
  for (let i = 0; i < sourceIds.length; i += 1) {
    const sourceSnap = snaps[i + 1];
    const sourceRef = sourceRefs[i];
    const sourceId = sourceIds[i];
    if (!sourceSnap.exists) continue;
    const source = sourceSnap.data() || {};
    if (source.companyId !== companyId) {
      throw new HttpsError("permission-denied", "These orders are not in your workspace.");
    }
    if (source.isDeleted === true) continue;

    const sourcePaid = roundMoneyValue(source.paidAmount);
    const sourcePayments = Array.isArray(source.payments) ? source.payments : [];
    const movedPayments = sourcePayments.length > 0
      ? sourcePayments
      : (sourcePaid > 0 ? [{
          id: crypto.randomUUID(),
          amount: sourcePaid,
          date: dateFromFirestore(source.paymentDate, new Date()),
          method: String(source.paymentMethod || ""),
          note: `Merged from order ${sourceId}`,
          createdByUid: "",
          createdByEmail: ""
        }] : []);
    mergedPayments = mergedPayments.concat(movedPayments);
    mergedPaid += sourcePaid;
    mergedAmount += sourcePaid;
    mergedCount += 1;

    batch.set(sourceRef, {
      isDeleted: true,
      deletedAt: admin.firestore.FieldValue.serverTimestamp(),
      mergedIntoOrderId: primaryId,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedByUid: uid,
      updatedByEmail: email
    }, { merge: true });
  }

  if (mergedCount === 0) {
    throw new HttpsError("failed-precondition", "None of the selected orders could be merged.");
  }

  batch.set(primaryRef, {
    paidAmount: mergedPaid,
    remainingAmount: Math.max(0, roundMoneyValue(primary.remainingAmount) - mergedAmount),
    payments: mergedPayments,
    historyLog: historyLogWithEntry(
      primary,
      "Orders merged",
      mergedCount === 1 ? "1 order" : `${mergedCount} orders`,
      amountHistoryValue(mergedAmount)
    ),
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedByUid: uid,
    updatedByEmail: email
  }, { merge: true });

  await batch.commit();

  return {
    ok: true,
    primaryOrderId: primaryId,
    mergedCount,
    mergedAmount,
    message: `${mergedCount} order${mergedCount === 1 ? "" : "s"} merged. The merged orders moved to Trash.`
  };
});

// ---------------------------------------------------------------------------
// Orders CSV export (callable) — one server-side generator shared by web, Mac
// and Android so every platform produces an identical, date-range-filtered
// file. Templates: orders (1 row/order), lineItems (1 row/line), payments
// (1 row/payment), finance (1 row/order, dashboard-parity money columns).
// Finance visibility mirrors the dashboard: roles without financialInfo cannot
// export money columns or the inherently-financial payments / finance sheets.
// ---------------------------------------------------------------------------
const EXPORT_TEMPLATE_IDS = new Set(["orders", "lineItems", "payments", "finance"]);

function exportNumberValue(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

function exportMoneyValue(value) {
  return roundMoneyValue(exportNumberValue(value)).toFixed(2);
}

function exportIsoDate(date) {
  return date instanceof Date && !Number.isNaN(date.getTime()) ? date.toISOString().slice(0, 10) : "";
}

// Parse an ISO date (YYYY-MM-DD) into a UTC millisecond boundary. v1 uses UTC
// calendar days for predictable, timezone-independent ranges.
function exportRangeMs(value, endOfDay = false) {
  const t = Date.parse(String(value || ""));
  if (!Number.isFinite(t)) return null;
  return endOfDay ? t + 24 * 60 * 60 * 1000 - 1 : t;
}

function exportCsvCell(value, delimiter) {
  const text = value === null || value === undefined ? "" : String(value);
  if (text.includes('"') || text.includes("\n") || text.includes("\r") || text.includes(delimiter)) {
    return '"' + text.replace(/"/g, '""') + '"';
  }
  return text;
}

function buildExportCsv(headerCols, dataRows, options = {}) {
  const delimiter = options.delimiter === ";" ? ";" : ",";
  const bom = options.bom !== false;
  const lines = [headerCols, ...dataRows].map((cols) => cols.map((cell) => exportCsvCell(cell, delimiter)).join(delimiter));
  return (bom ? "\uFEFF" : "") + lines.join("\r\n");
}

// Custom expense values are stored as display strings ("1,250.00" or "£1250").
// Strip the thousands separators + currency symbol before summing.
function exportFinancialAmount(raw, currency) {
  let cleaned = String(raw || "").split(",").join("");
  if (currency) cleaned = cleaned.split(currency).join("");
  const value = Number(cleaned.trim());
  return Number.isFinite(value) ? value : 0;
}

function exportFilenameSlug(name) {
  const slug = String(name || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);
  return slug || "nivadesk";
}

exports.exportOrders = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyData } = await requireNotificationWorkspaceAccess(request);
  requireWorkspaceAreaAccess(companyData, uid, "exportData", "Data export is not enabled for your workspace account.");

  const data = request.data || {};
  const template = EXPORT_TEMPLATE_IDS.has(String(data.template || "")) ? String(data.template) : "orders";
  const delimiter = data.delimiter === ";" ? ";" : ",";
  const bom = data.bom !== false;
  const includeTrash = data.includeTrash === true;

  // Finance gate — same rule the dashboard uses to hide money from a role.
  const access = workspaceMemberAccess(companyData, uid);
  const canSeeFinance = access.financialInfo !== false;
  if ((template === "finance" || template === "payments") && !canSeeFinance) {
    throw new HttpsError("permission-denied", "Your workspace role cannot export financial data.");
  }

  const fromMs = exportRangeMs(data.from, false);
  const toMs = exportRangeMs(data.to, true);

  const db = admin.firestore();
  const settingsSnap = await companySettingsDocRef(companyId).get();
  const settingsData = settingsSnap.exists ? settingsSnap.data() || {} : {};
  const currency = String(settingsData.selectedCurrency || "");
  const showBaseCost = settingsData.financialShowBaseCost !== false;
  const expenseItems = parseHeadingItemsJSON(settingsData.financialExpenseItemsJSON, []);

  const snapshot = await db.collection("siparisler").where("companyId", "==", companyId).get();
  const orders = [];
  for (const orderDoc of snapshot.docs) {
    const orderData = orderDoc.data() || {};
    if (!includeTrash && orderData.isDeleted === true) continue;
    const paymentDate = dateFromFirestore(orderData.paymentDate, null);
    const ms = paymentDate ? paymentDate.getTime() : null;
    if (fromMs !== null && (ms === null || ms < fromMs)) continue;
    if (toMs !== null && (ms === null || ms > toMs)) continue;
    orders.push({ id: orderDoc.id, data: orderData, paymentDate });
  }
  orders.sort((a, b) => (a.paymentDate ? a.paymentDate.getTime() : 0) - (b.paymentDate ? b.paymentDate.getTime() : 0));

  let header = [];
  const rows = [];

  if (template === "lineItems") {
    header = ["Invoice No", "Payment Date", "Customer", "Item", "Quantity", "Unit Price", "Line Total", "Currency"];
    if (!canSeeFinance) header = header.filter((h) => !["Unit Price", "Line Total", "Currency"].includes(h));
    for (const order of orders) {
      const o = order.data;
      const lineItems = Array.isArray(o.lineItems) ? o.lineItems : [];
      const base = [o.invoiceNumber || "", exportIsoDate(order.paymentDate), o.customerName || ""];
      if (lineItems.length > 0) {
        for (const li of lineItems) {
          const row = [...base, li && li.name ? String(li.name) : "", exportNumberValue(li && li.quantity)];
          if (canSeeFinance) row.push(exportMoneyValue(li && li.unitPrice), exportMoneyValue(li && li.lineTotal), currency);
          rows.push(row);
        }
      } else {
        // Orders without line items still appear as a single line using the
        // design name + order total, so the sheet covers every order.
        const total = exportNumberValue(o.paidAmount) + exportNumberValue(o.remainingAmount);
        const row = [...base, o.designName || "(order)", 1];
        if (canSeeFinance) row.push(exportMoneyValue(total), exportMoneyValue(total), currency);
        rows.push(row);
      }
    }
  } else if (template === "payments") {
    header = ["Invoice No", "Customer", "Payment Date", "Amount", "Method", "Note", "Recorded By", "Currency"];
    for (const order of orders) {
      const o = order.data;
      const payments = Array.isArray(o.payments) ? o.payments : [];
      if (payments.length > 0) {
        for (const p of payments) {
          rows.push([
            o.invoiceNumber || "",
            o.customerName || "",
            exportIsoDate(dateFromFirestore(p && p.date, order.paymentDate)),
            exportMoneyValue(p && p.amount),
            (p && p.method) || "",
            (p && p.note) || "",
            (p && p.createdByEmail) || "",
            currency
          ]);
        }
      } else if (exportNumberValue(o.paidAmount) > 0) {
        // Legacy orders aggregated their instalments into paidAmount — emit one
        // synthetic row so reconciliation totals still balance.
        rows.push([
          o.invoiceNumber || "",
          o.customerName || "",
          exportIsoDate(order.paymentDate),
          exportMoneyValue(o.paidAmount),
          o.paymentMethod || "",
          "(aggregated)",
          "",
          currency
        ]);
      }
    }
  } else if (template === "finance") {
    header = ["Invoice No", "Payment Date", "Customer", "Sales Total", "Paid", "Outstanding", "Base Cost", "Custom Expenses", "Payment Fee", "Delivery Cost", "VAT Rule", "VAT Rate %", "VAT Amount", "Net Profit", "Currency"];
    for (const order of orders) {
      const o = order.data;
      const paid = exportNumberValue(o.paidAmount);
      // Outstanding = classic remaining + the order's custom "Remaining"
      // receivables, so Sales Total and Net Profit include them like the app.
      const outstanding = exportNumberValue(o.remainingAmount) + orderCustomRemainingTotal(o.customFields);
      const salesTotal = paid + outstanding;
      const baseCost = showBaseCost ? exportNumberValue(o.watchPurchasePrice) : 0;
      const customFields = o.customFields && typeof o.customFields === "object" ? o.customFields : {};
      let customExpenses = 0;
      // Prefer this order's own per-order spending headings; fall back to the
      // workspace template for orders that were never customised.
      const orderExpenseTitles = orderHeadingTitleList(customFields.orderExpenseItemsJSON);
      const expenseTitlesForOrder = orderExpenseTitles.length > 0
        ? orderExpenseTitles
        : expenseItems.map((item) => item.title);
      for (const expenseTitle of expenseTitlesForOrder) {
        customExpenses += exportFinancialAmount(customFields[`financialExpense::${expenseTitle}`], currency);
      }
      const paymentFee = exportNumberValue(o.paymentFee);
      const deliveryCost = exportNumberValue(o.deliveryCost);
      const taxAmount = exportNumberValue(o.taxAmount);
      // Same formula as the dashboard's adjustedDashboardNetProfit.
      const netProfit = salesTotal - baseCost - customExpenses - paymentFee - deliveryCost - taxAmount;
      rows.push([
        o.invoiceNumber || "",
        exportIsoDate(order.paymentDate),
        o.customerName || "",
        exportMoneyValue(salesTotal),
        exportMoneyValue(paid),
        exportMoneyValue(outstanding),
        exportMoneyValue(baseCost),
        exportMoneyValue(customExpenses),
        exportMoneyValue(paymentFee),
        exportMoneyValue(deliveryCost),
        o.taxType || "",
        exportNumberValue(o.taxRate),
        exportMoneyValue(taxAmount),
        exportMoneyValue(netProfit),
        currency
      ]);
    }
  } else {
    const moneyCols = new Set(["Paid", "Outstanding", "Order Total", "Currency"]);
    header = ["Invoice No", "Order ID", "Payment Date", "Customer", "Email", "Phone", "Instagram", "Design", "Status", "Design Status", "Priority", "Risk", "Dispatched", "Delivered", "Courier", "Tracking No", "Delivery Days", "Assigned To", "Paid", "Outstanding", "Order Total", "Currency", "Notes"];
    if (!canSeeFinance) header = header.filter((h) => !moneyCols.has(h));
    for (const order of orders) {
      const o = order.data;
      const row = [
        o.invoiceNumber || "",
        order.id,
        exportIsoDate(order.paymentDate),
        o.customerName || "",
        o.emailAddress || "",
        o.whatsappNumber || "",
        o.instagramUsername || "",
        o.designName || "",
        o.status || "",
        o.designStatus || "",
        o.priority || "",
        o.risk || "",
        o.isDispatched ? "Yes" : "No",
        o.isDelivered ? "Yes" : "No",
        o.courier || "",
        o.trackingNumber || "",
        exportNumberValue(o.deliveryTime),
        o.assignedToEmail || ""
      ];
      if (canSeeFinance) {
        row.push(
          exportMoneyValue(o.paidAmount),
          exportMoneyValue(o.remainingAmount),
          exportMoneyValue(exportNumberValue(o.paidAmount) + exportNumberValue(o.remainingAmount)),
          currency
        );
      }
      row.push(o.notes || "");
      rows.push(row);
    }
  }

  const csv = buildExportCsv(header, rows, { delimiter, bom });
  const base64 = Buffer.from(csv, "utf8").toString("base64");
  // v1 returns the file inline. Guard against the callable 10MB response limit;
  // v2 will switch large exports to Cloud Storage + a signed download URL.
  if (base64.length > 8 * 1024 * 1024) {
    throw new HttpsError("resource-exhausted", "This export is too large to download at once. Please choose a narrower date range.");
  }
  const rangeLabel = `${data.from ? String(data.from) : "all"}_${data.to ? String(data.to) : "all"}`;
  const filename = `${exportFilenameSlug(companyData.name)}-${template}-${rangeLabel}.csv`;
  return {
    ok: true,
    companyId,
    template,
    rowCount: rows.length,
    filename,
    mimeType: "text/csv;charset=utf-8",
    base64
  };
});

exports.saveUploadSafetySettings = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyData } = await requireWorkspaceForBilling(request, false);
  if (!uidCanEditWorkspaceSettings(companyData, uid)) {
    throw new HttpsError("permission-denied", "Your workspace role cannot edit Upload Safety settings.");
  }
  requireWorkspaceAreaAccess(companyData, uid, "settingsSafetyUploads", "Safety & Uploads settings are not enabled for your role.");

  const incoming = request.data?.settings && typeof request.data.settings === "object" ? request.data.settings : {};
  const requirePolicy = typeof incoming.uploadSafetyRequirePolicyAcceptance === "boolean"
    ? incoming.uploadSafetyRequirePolicyAcceptance
    : true;
  const maxFileSizeMB = cleanUploadSafetyMaxFileSizeMB(incoming.uploadSafetyMaxFileSizeMB, 10);
  const policyText = String(incoming.uploadSafetyPolicyText || "").trim().slice(0, 2000);

  const settingsRef = companySettingsDocRef(companyId);
  await settingsRef.set({
    uploadSafetyRequirePolicyAcceptanceV1: requirePolicy,
    uploadSafetyRequirePolicyAcceptance: requirePolicy,
    uploadSafetyMaxFileSizeMBV1: maxFileSizeMB,
    uploadSafetyMaxFileSizeMB: maxFileSizeMB,
    uploadSafetyPolicyText: policyText,
    uploadSafetySettingsUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
    lastSettingsWriteByUid: uid, lastSettingsWriteAtMs: Date.now()
  }, { merge: true });

  const settingsSnapshot = await settingsRef.get();
  return {
    ok: true,
    companyId,
    settings: uploadSafetySettingsFromData(settingsSnapshot.exists ? settingsSnapshot.data() || {} : {}),
    message: "Upload Safety settings saved."
  };
});

// Who wins when a store order updates an existing customer's contact details.
exports.saveIntegrationSyncSettings = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyData } = await requireWorkspaceForBilling(request, false);
  if (!uidCanEditWorkspaceSettings(companyData, uid)) {
    throw new HttpsError("permission-denied", "Your workspace role cannot edit Integration settings.");
  }
  const policy = String(request.data?.policy) === "nivadesk" ? "nivadesk" : "store";
  await companySettingsDocRef(companyId).set({
    integrationCustomerSync: policy,
    integrationSyncSettingsUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
    lastSettingsWriteByUid: uid, lastSettingsWriteAtMs: Date.now()
  }, { merge: true });
  return { ok: true, companyId, policy, message: "Integration sync policy saved." };
});

function cleanWorkspaceLogoUrl(value) {
  const cleaned = String(value || "").trim();
  if (!cleaned) return "";
  if (cleaned.length > 3000) {
    throw new HttpsError("invalid-argument", "Workspace logo URL is too long.");
  }
  let parsed;
  try {
    parsed = new URL(cleaned);
  } catch {
    throw new HttpsError("invalid-argument", "Workspace logo URL is invalid.");
  }
  const allowedStorageHosts = new Set([
    "firebasestorage.googleapis.com",
    "storage.googleapis.com",
    "storage.cloud.google.com"
  ]);
  if (parsed.protocol !== "https:" || !allowedStorageHosts.has(parsed.hostname)) {
    throw new HttpsError("invalid-argument", "Workspace logo must be an uploaded Firebase Storage file.");
  }
  return cleaned;
}

exports.saveWorkspaceLogo = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyData } = await requireWorkspaceForBilling(request, false);
  if (!uidCanEditWorkspaceSettings(companyData, uid)) {
    throw new HttpsError("permission-denied", "Your workspace role cannot edit Workspace Logo.");
  }

  const appLogoUrl = cleanWorkspaceLogoUrl(request.data?.appLogoUrl);
  if (appLogoUrl) {
    const entitlements = billingEntitlementsForCompany(companyData);
    if (entitlements.workspaceLogoUploadEnabled !== true) {
      throw new HttpsError("failed-precondition", "Workspace logo upload is available on Monthly Pro and Team plans.", {
        requiredPlan: "pro_monthly",
        plan: entitlements.plan,
        planName: entitlements.displayName
      });
    }
  }

  const settingsRef = companySettingsDocRef(companyId);
  await settingsRef.set({
    appLogoUrl,
    brandingUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
    brandingUpdatedByUid: uid,
    brandingUpdatedByEmail: String(request.auth?.token?.email || ""),
    lastSettingsWriteByUid: uid, lastSettingsWriteAtMs: Date.now()
  }, { merge: true });

  return {
    ok: true,
    companyId,
    settings: { appLogoUrl },
    message: appLogoUrl ? "Workspace logo saved." : "Workspace logo removed."
  };
});

function cleanAccountName(value, fallback = "") {
  return cleanQuickReplyText(value, 80) || fallback;
}

function cleanAccountPhotoURL(value) {
  const cleaned = cleanQuickReplyText(value, 2000);
  if (!cleaned) return "";
  let parsed;
  try {
    parsed = new URL(cleaned);
  } catch (error) {
    throw new HttpsError("invalid-argument", "Profile photo URL must be a valid URL.");
  }
  if (parsed.protocol !== "https:") {
    throw new HttpsError("invalid-argument", "Profile photo URL must use HTTPS.");
  }
  return cleaned;
}

async function accountProfileAuthUser(uid) {
  try {
    return await admin.auth().getUser(uid);
  } catch (error) {
    console.warn("Account Auth profile lookup failed; using callable token and Firestore profile.", { uid, error: error?.message || error });
    return null;
  }
}


const ACCOUNT_EMAIL_CHANGE_COOLDOWN_MS = 10 * 24 * 60 * 60 * 1000;

function cleanAccountEmail(value) {
  const cleaned = String(value || "").trim().toLowerCase();
  if (!cleaned) return "";
  if (cleaned.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleaned)) {
    throw new HttpsError("invalid-argument", "Enter a valid email address.");
  }
  return cleaned;
}

function timestampMillis(value) {
  if (!value) return 0;
  if (typeof value.toMillis === "function") return value.toMillis();
  if (value instanceof Date) return value.getTime();
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

function accountEmailCooldownError(nextAllowedMs) {
  const nextDate = new Date(nextAllowedMs);
  const displayDate = nextDate.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
  return new HttpsError("failed-precondition", "You can change your email again on " + displayDate + ".");
}

exports.changeAccountEmail = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyRef, companyData } = await requireWorkspaceForBilling(request, false);
  const email = cleanAccountEmail(request.data?.email);
  if (!email) {
    throw new HttpsError("invalid-argument", "Enter a valid email address.");
  }

  const authUser = await accountProfileAuthUser(uid);

  // OAuth-only accounts (Google / Apple, no password provider) cannot change
  // their sign-in email here — the address is owned by the provider. Blocking
  // it avoids a misleading "verify your inbox" flow and an Auth/Firestore email
  // mismatch when Firebase re-syncs the provider email on the next sign-in.
  // Only block when we positively know the providers (authUser present).
  const hasPasswordProvider = (authUser?.providerData || []).some((p) => p.providerId === "password");
  if (authUser && !hasPasswordProvider) {
    throw new HttpsError(
      "failed-precondition",
      "Your sign-in email is managed by Google or Apple and can't be changed here."
    );
  }

  const existingMember = companyMembersMap(companyData)[uid] || {};
  const token = request.auth?.token || {};
  const currentEmail = String(authUser?.email || token.email || existingMember.email || "").trim().toLowerCase();
  const userRef = admin.firestore().collection("users").doc(uid);
  const userSnap = await userRef.get();
  const userData = userSnap.data() || {};
  const lastChangedMs = Math.max(
    timestampMillis(userData.accountEmailLastChangedAt),
    timestampMillis(existingMember.accountEmailLastChangedAt)
  );
  const nowMs = Date.now();
  const nextAllowedMs = lastChangedMs ? lastChangedMs + ACCOUNT_EMAIL_CHANGE_COOLDOWN_MS : 0;

  if (email === currentEmail) {
    return {
      ok: true,
      companyId,
      profile: {
        email,
        displayName: cleanAccountName(existingMember.displayName || authUser?.displayName || token.name || ""),
        companyName: cleanAccountName(companyData.name || companyData.companyName, "My Studio"),
        photoURL: cleanQuickReplyText(existingMember.photoURL || authUser?.photoURL || "", 2000),
        emailNextChangeAt: nextAllowedMs || null
      },
      message: "This is already your sign-in email."
    };
  }

  if (nextAllowedMs && nowMs < nextAllowedMs) {
    throw accountEmailCooldownError(nextAllowedMs);
  }

  try {
    const existingUser = await admin.auth().getUserByEmail(email);
    if (existingUser.uid !== uid) {
      throw new HttpsError("already-exists", "This email address is already used by another account.");
    }
  } catch (error) {
    if (error instanceof HttpsError) throw error;
    if (error?.code !== "auth/user-not-found") {
      console.warn("Account email availability check failed:", { uid, email, error: error?.message || error });
      throw new HttpsError("internal", "Email availability could not be checked right now.");
    }
  }

  const timestamp = admin.firestore.FieldValue.serverTimestamp();
  const displayName = cleanAccountName(existingMember.displayName || authUser?.displayName || token.name || "");
  const photoURL = cleanQuickReplyText(existingMember.photoURL || authUser?.photoURL || "", 2000);
  const companyName = cleanAccountName(companyData.name || companyData.companyName, "My Studio");
  const previousEmail = currentEmail || String(existingMember.email || userData.email || "").trim().toLowerCase();

  await admin.auth().updateUser(uid, { email, emailVerified: false });

  const batch = admin.firestore().batch();
  batch.set(userRef, {
    uid,
    email,
    displayName,
    photoURL,
    activeCompanyId: companyId,
    accountEmailPrevious: previousEmail,
    accountEmailLastChangedAt: timestamp,
    updatedAt: timestamp
  }, { merge: true });

  const memberProfile = {
    uid,
    email,
    displayName,
    photoURL,
    accountEmailLastChangedAt: timestamp,
    updatedAt: timestamp
  };
  const companyUpdate = {
    members: { [uid]: memberProfile },
    updatedAt: timestamp
  };
  if (uidIsCompanyOwner(companyData, uid)) {
    companyUpdate.ownerEmail = email;
  }
  batch.set(companyRef, companyUpdate, { merge: true });
  await batch.commit();

  return {
    ok: true,
    companyId,
    profile: {
      email,
      displayName,
      companyName,
      photoURL,
      emailNextChangeAt: nowMs + ACCOUNT_EMAIL_CHANGE_COOLDOWN_MS
    },
    message: "Email updated. Check your new inbox to verify it. You can change it again after 10 days."
  };
});

exports.initializeFreeDemoWorkspace = onCall({ region: "europe-west2" }, async (request) => {
  const uid = String(request.auth?.uid || "").trim();
  if (!uid) {
    throw new HttpsError("unauthenticated", "Sign in is required before creating a workspace.");
  }

  const fullName = cleanQuickReplyText(request.data?.fullName || request.auth?.token?.name || "", 80);
  const workspaceName = cleanQuickReplyText(request.data?.workspaceName || "", 100);
  if (fullName.length < 2 || workspaceName.length < 2) {
    throw new HttpsError("invalid-argument", "Full name and workspace name are required.");
  }

  const email = String(request.auth?.token?.email || "").trim();
  const timestamp = admin.firestore.FieldValue.serverTimestamp();
  const db = admin.firestore();
  const userRef = db.collection("users").doc(uid);
  const companyRef = db.collection("companies").doc(uid);
  const companySnapshot = await companyRef.get();
  const existing = companySnapshot.exists ? (companySnapshot.data() || {}) : {};

  if (companySnapshot.exists) {
    const existingOwner = String(existing.ownerUid || uid).trim();
    const existingSource = String(existing.billingPlanSource || "").trim();
    const existingPlan = String(existing.billingPlan || "demo").trim();
    const existingName = String(existing.name || existing.companyName || "").trim();
    const isAutomaticBootstrap = existingOwner === uid && existingPlan === "demo" && (
      !existingSource ||
      existingSource === "new_workspace_default" ||
      existingSource === "signup_free_demo" ||
      existingSource === "signup_free" ||
      existingName === "My Studio"
    );

    if (!isAutomaticBootstrap) {
      throw new HttpsError("failed-precondition", "This account already has an active workspace. Open the portal instead.");
    }
  }

  const ownerMember = {
    uid,
    email,
    displayName: fullName,
    role: "owner",
    updatedAt: timestamp
  };

  const batch = db.batch();
  batch.set(userRef, {
    uid,
    email,
    displayName: fullName,
    activeCompanyId: uid,
    updatedAt: timestamp
  }, { merge: true });

  batch.set(companyRef, {
    companyId: uid,
    ownerUid: uid,
    ownerEmail: email,
    ownerDisplayName: fullName,
    appName: "NivaDesk",
    name: workspaceName,
    companyName: workspaceName,
    memberUids: admin.firestore.FieldValue.arrayUnion(uid),
    memberRoles: { [uid]: "owner" },
    members: { [uid]: ownerMember },
    billingPlan: "demo",
    billingPlanName: "Free",
    billingPlanSource: "signup_free",
    billingStatus: "free",
    billingProviderRawStatus: "free",
    billingStorageLimitMB: 50,
    billingTeamMemberLimit: 1,
    signupCompletedAt: timestamp,
    updatedAt: timestamp,
    createdAt: companySnapshot.exists ? (existing.createdAt || timestamp) : timestamp
  }, { merge: true });

  await batch.commit();
  return { ok: true, companyId: uid, plan: "demo", message: "Free Demo workspace created." };
});

exports.saveAccountProfile = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyRef, companyData } = await requireWorkspaceForBilling(request, false);
  const profile = request.data?.profile && typeof request.data.profile === "object" ? request.data.profile : {};
  const authUser = await accountProfileAuthUser(uid);
  const existingMember = companyMembersMap(companyData)[uid] || {};
  const token = request.auth?.token || {};
  const hasDisplayNameInput = Object.prototype.hasOwnProperty.call(profile, "displayName");
  const displayName = hasDisplayNameInput
    ? cleanQuickReplyText(profile.displayName, 80)
    : cleanAccountName(existingMember.displayName || authUser?.displayName || token.name || "");
  const incomingCompanyName = cleanAccountName(profile.companyName, "My Studio");
  const isOwner = uidIsCompanyOwner(companyData, uid);
  const currentCompanyName = cleanAccountName(companyData.name || companyData.companyName, "My Studio");
  const companyName = isOwner ? incomingCompanyName : currentCompanyName;
  const email = String(authUser?.email || token.email || existingMember.email || "");
  const photoURL = String(existingMember.photoURL || "");
  const timestamp = admin.firestore.FieldValue.serverTimestamp();

  const batch = admin.firestore().batch();
  batch.set(admin.firestore().collection("users").doc(uid), {
    uid,
    email,
    displayName,
    activeCompanyId: companyId,
    updatedAt: timestamp
  }, { merge: true });

  const companyUpdate = {
    updatedAt: timestamp,
    members: {
      [uid]: {
        uid,
        email,
        displayName,
        updatedAt: timestamp
      }
    }
  };

  if (isOwner) {
    companyUpdate.name = companyName;
    companyUpdate.companyName = companyName;
    companyUpdate.ownerDisplayName = displayName;
    companyUpdate.ownerEmail = email;
    companyUpdate.memberUids = admin.firestore.FieldValue.arrayUnion(uid);
  }

  batch.set(companyRef, companyUpdate, { merge: true });
  await batch.commit();

  return {
    ok: true,
    companyId,
    profile: {
      displayName,
      companyName,
      photoURL,
      companyNameEditable: isOwner
    },
    message: isOwner ? "Profile updated." : "Profile updated. Company details can only be changed by the workspace owner."
  };
});

