exports.removeWorkspaceTeamMember = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyRef, companyData } = await requireWorkspaceForBilling(request, true);
  const memberUid = String(request.data?.memberUid || "").trim();

  if (!memberUid) {
    throw new HttpsError("invalid-argument", "memberUid is required.");
  }
  if (memberUid === uid || memberUid === String(companyData.ownerUid || "")) {
    throw new HttpsError("failed-precondition", "The workspace owner cannot be removed here.");
  }

  const members = companyMembersMap(companyData);
  if (!members[memberUid]) {
    // Still make sure the user's access document and accepted join request do not re-create access later.
  }

  const db = admin.firestore();
  const deterministicRequestRef = db.collection("workspaceJoinRequests").doc(`${companyId}_${memberUid}`);
  const accessRef = db.collection("users").doc(memberUid).collection("workspaceAccess").doc(companyId);
  const relatedRequestSnap = await db.collection("workspaceJoinRequests")
    .where("targetCompanyId", "==", companyId)
    .where("requesterUid", "==", memberUid)
    .get();

  const batch = db.batch();
  batch.update(companyRef, {
    [`members.${memberUid}`]: admin.firestore.FieldValue.delete(),
    [`memberRoles.${memberUid}`]: admin.firestore.FieldValue.delete(),
    [`memberCustomRoles.${memberUid}`]: admin.firestore.FieldValue.delete(),
    [`memberAccess.${memberUid}`]: admin.firestore.FieldValue.delete(),
    memberUids: admin.firestore.FieldValue.arrayRemove(memberUid),
    removedMemberUids: admin.firestore.FieldValue.arrayUnion(memberUid),
    updatedAt: admin.firestore.FieldValue.serverTimestamp()
  });
  batch.delete(accessRef);

  const removalPayload = {
    targetCompanyId: companyId,
    requesterUid: memberUid,
    status: "removed",
    removedBy: uid,
    removedAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedAt: admin.firestore.FieldValue.serverTimestamp()
  };

  if (relatedRequestSnap.empty) {
    batch.set(deterministicRequestRef, removalPayload, { merge: true });
  } else {
    relatedRequestSnap.forEach((docSnap) => {
      batch.set(docSnap.ref, removalPayload, { merge: true });
    });
    if (!relatedRequestSnap.docs.some((docSnap) => docSnap.id === deterministicRequestRef.id)) {
      batch.set(deterministicRequestRef, removalPayload, { merge: true });
    }
  }

  await batch.commit();

  const updatedCompanySnap = await companyRef.get();
  const updatedCompanyData = updatedCompanySnap.data() || companyData;
  const entitlements = billingEntitlementsForCompany(updatedCompanyData);
  const limits = planLimitsFromEntitlements(entitlements, companyData);
  const usage = await workspaceBillingUsage(companyId, updatedCompanyData);
  await saveWorkspaceBillingUsage(companyRef, usage, entitlements, limits, "team_member_removed");

  return {
    ok: true,
    companyId,
    memberUid,
    message: "Team member removed."
  };
});

exports.syncWorkspaceAcceptedJoinRequests = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyRef, companyData } = await requireWorkspaceForBilling(request, true);
  const result = await reconcileAcceptedJoinRequestsForWorkspace(companyId, uid, companyRef, companyData);

  if (result.repairedCount > 0) {
    const updatedCompanySnap = await companyRef.get();
    const entitlements = billingEntitlementsForCompany(updatedCompanySnap.data() || companyData);
    const limits = planLimitsFromEntitlements(entitlements, companyData);
    const usage = await workspaceBillingUsage(companyId, updatedCompanySnap.data() || companyData);
    await saveWorkspaceBillingUsage(companyRef, usage, entitlements, limits, "accepted_join_request_sync");
  }

  return {
    ok: true,
    companyId,
    ...result,
    message: result.repairedCount > 0 ? "Team access repaired." : "Team access already up to date."
  };
});

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    const stringValue = String(value).trim();
    if (stringValue) return stringValue;
  }
  return "";
}

function firstArrayValue(...values) {
  for (const value of values) {
    if (Array.isArray(value) && value.length > 0) return value[0];
  }
  return undefined;
}

function acceptedArray(response) {
  const accepted = response?.data?.accepted;
  return Array.isArray(accepted) ? accepted : [];
}

function rejectedArray(response) {
  const rejected = response?.data?.rejected;
  return Array.isArray(rejected) ? rejected : [];
}

function errorsArray(response) {
  const errors = response?.data?.errors;
  return Array.isArray(errors) ? errors : [];
}

function firstAccepted(response) {
  const accepted = acceptedArray(response);
  return accepted.length > 0 ? accepted[0] : null;
}

function firstApiError(response) {
  const firstRejected = rejectedArray(response)[0];
  const firstError = errorsArray(response)[0];
  const err = firstRejected?.error || firstRejected || firstError || null;

  if (!err) return null;

  return {
    code: Number(err.code || firstRejected?.code || firstError?.code || 0),
    message: firstNonEmpty(
      err.message,
      firstRejected?.message,
      firstError?.message,
      typeof err === "string" ? err : "",
      JSON.stringify(err)
    )
  };
}

function isAlreadyRegistered(error) {
  return error?.code === -18019901 || String(error?.message || "").toLowerCase().includes("already registered");
}

// Pattern-based carrier guesses for numbers 17TRACK cannot auto-detect.
// Order matters: the first registration 17TRACK accepts wins.
function carrierCandidatesFromNumber(trackingNumber) {
  const value = cleanTrackingNumber(trackingNumber).toUpperCase();
  const candidates = [];
  if (/^1Z[0-9A-Z]{16}$/.test(value)) candidates.push(100002);            // UPS
  if (/^[A-Z]{2}\d{9}GB$/.test(value)) candidates.push(11031);            // Royal Mail
  if (/^\d{10}$/.test(value)) candidates.push(100001);                    // DHL Express waybill
  if (/^\d{12}$/.test(value) || /^\d{15}$/.test(value)) candidates.push(100003); // FedEx
  return candidates;
}

function isCarrierCannotBeDetected(error) {
  const message = String(error?.message || "").toLowerCase();
  return error?.code === -18019903 || message.includes("carrier can not be detected") || message.includes("carrier cannot be detected");
}

function isNoTrackingInfoYet(error) {
  return error?.code === -18019909 || String(error?.message || "").toLowerCase().includes("no tracking info");
}

function isRealtimeNotAvailable(errorOrMessage) {
  const message = String(errorOrMessage?.message || errorOrMessage || "").toLowerCase();
  const code = Number(errorOrMessage?.code || 0);

  return code === -18019818 ||
    code === -18019912 ||
    code === -18019815 ||
    code === -18019816 ||
    message.includes("track_info") ||
    message.includes("real-time") ||
    message.includes("realtime") ||
    message.includes("not support");
}

function buildTrack17Body(trackingNumber, carrierCode = null, options = {}) {
  const item = { number: trackingNumber };

  if (carrierCode) {
    item.carrier = Number(carrierCode);
  } else if (options.autoDetection === true) {
    item.auto_detection = true;
  }

  if (options.lang) item.lang = String(options.lang);
  if (options.param) item.param = String(options.param);
  if (options.tag) item.tag = String(options.tag);
  if (options.remark) item.remark = String(options.remark);

  return [item];
}

function packageStatusFromCode(value) {
  const code = Number(value);
  if (code === 0) return "NotFound";
  if (code === 10) return "InTransit";
  if (code === 20) return "Delivered";
  if (code === 30) return "Exception";
  if (code === 40) return "Expired";
  if (code === 50) return "AvailableForPickup";
  return Number.isFinite(code) && code > 0 ? `Status ${code}` : "Registered";
}

function extractCarrierName(track, item, fallback = {}) {
  const provider = firstArrayValue(
    track?.tracking?.providers,
    track?.providers,
    item?.track_info?.tracking?.providers,
    item?.track?.tracking?.providers
  );

  return firstNonEmpty(
    provider?.provider?.name,
    provider?.provider_name,
    provider?.name,
    track?.shipping_info?.shipping_provider,
    track?.shipping_info?.courier_name,
    track?.shipping_info?.carrier_name,
    carrierNameFromCode(item?.carrier),
    carrierNameFromCode(track?.w1),
    carrierNameFromCode(track?.carrier),
    carrierNameFromCode(fallback.carrierCode),
    isAutoDetectCourier(fallback.carrier) ? "" : fallback.carrier
  );
}

function normalize17TrackPayload(raw, fallback = {}) {
  // raw can be an empty array (e.g. building a "waiting" result before 17TRACK has
  // any data) — raw[0] would be undefined, so guard the whole expression.
  const item = (Array.isArray(raw) ? raw[0] : raw) || {};
  const track = item.track_info || item.track || item.info || item || {};

  const provider = firstArrayValue(track?.tracking?.providers, track?.providers);
  const providerEvents = Array.isArray(provider?.events) ? provider.events : [];
  const compactEvents = Array.isArray(track?.z1) ? track.z1 : [];

  const latestEvent =
    track?.latest_event ||
    track?.latestEvent ||
    providerEvents[0] ||
    track?.events?.[0] ||
    track?.z0 ||
    compactEvents[0] ||
    {};

  const latestStatus = track?.latest_status || track?.latestStatus || {};

  const rawStatus = firstNonEmpty(
    latestStatus?.status,
    latestStatus?.status_code,
    latestEvent?.stage,
    latestEvent?.sub_status,
    track?.package_state,
    track?.package_status,
    track?.status,
    item?.status,
    track?.e ? packageStatusFromCode(track.e) : "",
    fallback.status,
    "Registered"
  );

  const statusText = firstNonEmpty(
    latestStatus?.status_text,
    latestStatus?.sub_status_text,
    latestStatus?.sub_status_descr,
    latestStatus?.status,
    latestEvent?.stage,
    latestEvent?.sub_status,
    track?.status_text,
    rawStatus,
    fallback.statusText,
    "Registered"
  );

  const carrierCode = firstNonEmpty(item?.carrier, track?.w1, track?.carrier, fallback.carrierCode);
  const carrier = extractCarrierName(track, item, { ...fallback, carrierCode });

  const checkpoint = firstNonEmpty(
    latestEvent?.description,
    latestEvent?.event,
    latestEvent?.text,
    latestEvent?.content,
    latestEvent?.z,
    latestEvent?.stage
  );

  const trackingNumber = cleanTrackingNumber(
    item?.number || item?.tracking_number || track?.tracking_number || fallback.trackingNumber
  );

  const result = {
    ok: true,
    provider: "17TRACK",
    trackingNumber,
    status: String(rawStatus || "Registered"),
    statusText: String(statusText || rawStatus || "Registered"),
    subStatus: firstNonEmpty(latestStatus?.sub_status, latestStatus?.sub_status_text, latestStatus?.sub_status_descr, latestEvent?.sub_status),
    carrier: String(carrier || ""),
    carrierCode: String(carrierCode || ""),
    checkpoint: String(checkpoint || ""),
    location: firstNonEmpty(latestEvent?.location, latestEvent?.place, latestEvent?.c, latestEvent?.d),
    eta: firstNonEmpty(
      track?.time_metrics?.estimated_delivery_date?.from,
      track?.time_metrics?.estimated_delivery_date?.to,
      track?.estimated_delivery_date
    ),
    lastUpdate: firstNonEmpty(latestEvent?.time_iso, latestEvent?.time_utc, latestEvent?.time_raw, latestEvent?.time, latestEvent?.a),
    lastCheckedAt: admin.firestore.FieldValue.serverTimestamp(),
    trackingUrl: trackingNumber ? `https://www.17track.net/en/track-details?nums=${encodeURIComponent(trackingNumber)}` : "",
    trackingSupportStatus: "active",
    supportMessage: "",
    supportMessageKey: "",
    error: ""
  };

  if (!hasUsefulTrackingData(result)) {
    result.trackingSupportStatus = "waiting";
    result.supportMessageKey = "registered_waiting";
  }

  return result;
}

function hasUsefulTrackingData(result) {
  return Boolean(
    firstNonEmpty(result?.checkpoint, result?.lastUpdate, result?.eta) ||
    ["delivered", "intransit", "in transit", "exception", "availableforpickup", "available for pickup", "out for delivery"].some((word) =>
      String(result?.status || result?.statusText || "").toLowerCase().includes(word)
    )
  );
}

function isDeliveredResult(result) {
  const text = `${result?.status || ""} ${result?.statusText || ""} ${result?.checkpoint || ""}`.toLowerCase();
  return text.includes("delivered") || text.includes("teslim edildi");
}

// A parcel the carrier reports as moving (in transit, out for delivery,
// available for pickup) or already delivered has necessarily left the studio,
// so live tracking auto-flips the order's Dispatched toggle to Yes. Only ever
// sets it true — a manual "No" stays untouched until the carrier sees movement.
function isMovingResult(result) {
  if (isDeliveredResult(result)) return true;
  const text = `${result?.status || ""} ${result?.statusText || ""}`.toLowerCase();
  return ["intransit", "in transit", "out for delivery", "availableforpickup", "available for pickup"]
    .some((word) => text.includes(word));
}

function limitedSupportForCarrier(carrierCode, language) {
  const code = Number(carrierCode);
  if (code === 11031) {
    return {
      trackingSupportStatus: "limited",
      supportMessageKey: "royal_mail_limited",
      supportMessage: localizedMessage("royal_mail_limited", language)
    };
  }
  if (code === 100003) {
    return {
      trackingSupportStatus: "limited",
      supportMessageKey: "fedex_limited",
      supportMessage: localizedMessage("fedex_limited", language)
    };
  }
  return {};
}

async function call17Track(url, token, body) {
  const response = await fetch(url, {
    method: "POST",
    headers: {
      "17token": token,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(body)
  });

  const text = await response.text();
  let json = null;

  try {
    json = text ? JSON.parse(text) : {};
  } catch (error) {
    throw new Error(`17TRACK returned non-JSON response: ${text.slice(0, 500)}`);
  }

  if (!response.ok) {
    throw new Error(`17TRACK HTTP ${response.status}: ${JSON.stringify(json).slice(0, 800)}`);
  }

  return json;
}

function asArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function firstObject(...values) {
  for (const value of values) {
    if (!value) continue;
    if (Array.isArray(value) && value.length > 0 && typeof value[0] === "object") return value[0];
    if (typeof value === "object" && !Array.isArray(value)) return value;
  }
  return {};
}

async function callRoyalMailEvents(trackingNumber, clientId, clientSecret) {
  const url = `${ROYALMAIL_BASE_URL}/${encodeURIComponent(trackingNumber)}/events`;
  const response = await fetch(url, {
    method: "GET",
    headers: {
      "Accept": "application/json",
      "X-Accept-RMG-Terms": "yes",
      "X-IBM-Client-Id": clientId,
      "X-IBM-Client-Secret": clientSecret
    }
  });

  const text = await response.text();
  let json = null;

  try {
    json = text ? JSON.parse(text) : {};
  } catch (error) {
    throw new Error(`Royal Mail returned non-JSON response: ${text.slice(0, 500)}`);
  }

  if (!response.ok) {
    const message = firstNonEmpty(
      json?.message,
      json?.Message,
      json?.error,
      json?.Error,
      json?.errors?.[0]?.message,
      json?.Errors?.[0]?.Message,
      JSON.stringify(json).slice(0, 700)
    );
    throw new Error(`Royal Mail HTTP ${response.status}: ${message}`);
  }

  return json;
}

function normalizeRoyalMailPayload(raw, fallback = {}) {
  const mailPiecesRoot = firstObject(raw?.mailPieces, raw?.MailPieces, raw?.mailpieces, raw);
  const piece = firstObject(
    mailPiecesRoot?.mailPiece,
    mailPiecesRoot?.MailPiece,
    mailPiecesRoot?.mailPieces,
    mailPiecesRoot?.MailPieces,
    raw?.mailPiece,
    raw?.MailPiece,
    raw
  );

  const summary = firstObject(piece?.summary, piece?.Summary, raw?.summary, raw?.Summary, piece);
  const eventsContainer = firstObject(piece?.events, piece?.Events, raw?.events, raw?.Events);
  const events = asArray(
    eventsContainer?.event ||
    eventsContainer?.Event ||
    piece?.event ||
    piece?.Event ||
    raw?.event ||
    raw?.Event
  );
  const latestEvent = firstObject(events[0], summary);

  const trackingNumber = cleanTrackingNumber(firstNonEmpty(
    summary?.oneDBarcode,
    summary?.OneDBarcode,
    summary?.mailPieceId,
    summary?.MailPieceId,
    piece?.mailPieceId,
    piece?.MailPieceId,
    raw?.mailPieceId,
    raw?.MailPieceId,
    fallback.trackingNumber
  ));

  const carrier = firstNonEmpty(
    piece?.carrierFullName,
    piece?.CarrierFullName,
    summary?.internationalPostalProvider?.title,
    summary?.InternationalPostalProvider?.Title,
    "Royal Mail"
  );

  const statusCategory = firstNonEmpty(
    summary?.statusCategory,
    summary?.StatusCategory,
    summary?.statusDescription,
    summary?.StatusDescription,
    latestEvent?.eventName,
    latestEvent?.EventName,
    fallback.status,
    "Registered"
  );

  const statusText = firstNonEmpty(
    summary?.statusDescription,
    summary?.StatusDescription,
    summary?.lastEventName,
    summary?.LastEventName,
    latestEvent?.eventName,
    latestEvent?.EventName,
    statusCategory
  );

  const location = firstNonEmpty(
    summary?.lastEventLocationName,
    summary?.LastEventLocationName,
    latestEvent?.locationName,
    latestEvent?.LocationName,
    latestEvent?.location,
    latestEvent?.Location
  );

  const checkpoint = firstNonEmpty(
    summary?.summaryLine,
    summary?.SummaryLine,
    [statusText, location].filter(Boolean).join(" · "),
    statusText
  );

  const lastUpdate = firstNonEmpty(
    summary?.lastEventDateTime,
    summary?.LastEventDateTime,
    latestEvent?.eventDateTime,
    latestEvent?.EventDateTime,
    latestEvent?.dateTime,
    latestEvent?.DateTime
  );

  const eta = firstNonEmpty(
    summary?.estimatedDeliveryDate,
    summary?.EstimatedDeliveryDate,
    summary?.estimatedDeliveryWindow?.end,
    summary?.EstimatedDeliveryWindow?.End
  );

  const result = {
    ok: true,
    provider: "Royal Mail",
    trackingNumber,
    status: String(statusCategory || "Registered"),
    statusText: String(statusText || statusCategory || "Registered"),
    subStatus: "",
    carrier: String(carrier || "Royal Mail"),
    carrierCode: "11031",
    checkpoint: String(checkpoint || ""),
    location: String(location || ""),
    eta: String(eta || ""),
    lastUpdate: String(lastUpdate || ""),
    lastCheckedAt: admin.firestore.FieldValue.serverTimestamp(),
    trackingUrl: trackingNumber ? `https://www.royalmail.com/track-your-item#/tracking-results/${encodeURIComponent(trackingNumber)}` : "https://www.royalmail.com/track-your-item",
    trackingSupportStatus: "active",
    supportMessage: "",
    supportMessageKey: "",
    error: ""
  };

  if (!hasUsefulTrackingData(result)) {
    result.trackingSupportStatus = "waiting";
    result.supportMessageKey = "royal_mail_waiting";
  }

  return result;
}

async function tryRoyalMailOfficialTracking(trackingNumber, language = "English") {
  const clientId = ROYALMAIL_CLIENT_ID.value();
  const clientSecret = ROYALMAIL_CLIENT_SECRET.value();

  const base = {
    ok: false,
    provider: "Royal Mail",
    trackingNumber,
    carrier: "Royal Mail",
    carrierCode: "11031",
    status: "Waiting",
    statusText: "Waiting",
    checkpoint: "",
    location: "",
    eta: "",
    lastUpdate: "",
    lastCheckedAt: admin.firestore.FieldValue.serverTimestamp(),
    trackingUrl: trackingNumber ? `https://www.royalmail.com/track-your-item#/tracking-results/${encodeURIComponent(trackingNumber)}` : "https://www.royalmail.com/track-your-item",
    error: ""
  };

  if (!secretLooksConfigured(clientId) || !secretLooksConfigured(clientSecret)) {
    return {
      ...base,
      trackingSupportStatus: "credentials_missing",
      supportMessageKey: "royal_mail_credentials_missing",
      supportMessage: localizedMessage("royal_mail_credentials_missing", language)
    };
  }

  try {
    const response = await callRoyalMailEvents(trackingNumber, clientId, clientSecret);
    const normalized = normalizeRoyalMailPayload(response, { trackingNumber });
    if (!normalized.supportMessage && normalized.supportMessageKey) {
      normalized.supportMessage = localizedMessage(normalized.supportMessageKey, language);
    }
    return normalized;
  } catch (error) {
    console.error("Royal Mail official tracking warning:", error?.message || error);
    return {
      ...base,
      trackingSupportStatus: "limited",
      supportMessageKey: "royal_mail_error",
      supportMessage: localizedMessage("royal_mail_error", language),
      error: error?.message || String(error)
    };
  }
}

async function tryPushUpdate(token, trackingNumber, carrierCode) {
  try {
    await call17Track(TRACK17_PUSH_URL, token, buildTrack17Body(trackingNumber, carrierCode));
  } catch (error) {
    console.error("17TRACK push warning:", error?.message || error);
  }
}

async function tryChangeCarrier(token, trackingNumber, carrierCode) {
  if (!carrierCode) return { changed: false, error: null };

  try {
    const response = await call17Track(TRACK17_CHANGE_CARRIER_URL, token, [
      {
        number: trackingNumber,
        carrier_new: Number(carrierCode)
      }
    ]);

    const apiError = firstApiError(response);
    if (apiError && apiError.code !== -18019803 && apiError.code !== -18019809) {
      return { changed: false, error: apiError };
    }

    return { changed: true, error: null };
  } catch (error) {
    console.error("17TRACK change carrier warning:", error?.message || error);
    return { changed: false, error };
  }
}

async function getTrackingDetails(token, trackingNumber, carrierCode, fallback, language = "English") {
  const body = buildTrack17Body(trackingNumber, carrierCode);

  try {
    const infoResponse = await call17Track(TRACK17_GET_INFO_URL, token, body);
    const accepted = acceptedArray(infoResponse);
    const apiError = firstApiError(infoResponse);

    if (accepted.length > 0) {
      const normalized = normalize17TrackPayload(accepted, fallback);
      if (hasUsefulTrackingData(normalized)) {
        return normalized;
      }

      return {
        ...normalized,
        status: normalized.status || "Registered",
        statusText: normalized.statusText || "Registered - waiting for 17TRACK update",
        trackingSupportStatus: "waiting",
        supportMessageKey: "registered_waiting",
        supportMessage: localizedMessage("registered_waiting", language)
      };
    }

    if (apiError && !isNoTrackingInfoYet(apiError)) {
      // The number is already registered at this point; a query-side API error
      // usually just means 17TRACK has no data yet. Surface the message as a
      // support note and keep the card in "waiting" instead of a red error.
      console.warn("17TRACK gettrackinfo api error:", apiError.code, apiError.message);
      return {
        ...normalize17TrackPayload([], fallback),
        status: "Registered",
        statusText: "Registered - waiting for 17TRACK update",
        trackingSupportStatus: "waiting",
        supportMessageKey: "registered_waiting",
        supportMessage: localizedMessage("registered_waiting", language),
        ...limitedSupportForCarrier(carrierCode, language),
        error: ""
      };
    }
  } catch (error) {
    console.error("17TRACK gettrackinfo warning:", error?.message || error);
  }

  await tryPushUpdate(token, trackingNumber, carrierCode);

  if (carrierCode && !REALTIME_UNSUPPORTED_CODES.has(Number(carrierCode))) {
    try {
      const realtimeResponse = await call17Track(TRACK17_REALTIME_URL, token, body);
      const accepted = acceptedArray(realtimeResponse);
      const apiError = firstApiError(realtimeResponse);

      if (accepted.length > 0) {
        const normalized = normalize17TrackPayload(accepted, fallback);
        if (hasUsefulTrackingData(normalized)) {
          return normalized;
        }
      }

      if (apiError && !isRealtimeNotAvailable(apiError) && !isNoTrackingInfoYet(apiError)) {
        // Same as gettrackinfo: realtime quota/support errors after a successful
        // registration should not paint the card red — keep waiting.
        console.warn("17TRACK realtime api error:", apiError.code, apiError.message);
      }
    } catch (error) {
      if (!isRealtimeNotAvailable(error)) {
        console.error("17TRACK realtime warning:", error?.message || error);
      }
    }
  }

  return {
    ...normalize17TrackPayload([], fallback),
    status: "Registered",
    statusText: "Registered - waiting for 17TRACK update",
    trackingSupportStatus: firstNonEmpty(limitedSupportForCarrier(carrierCode, language).trackingSupportStatus, "waiting"),
    supportMessageKey: firstNonEmpty(limitedSupportForCarrier(carrierCode, language).supportMessageKey, "registered_waiting"),
    supportMessage: firstNonEmpty(limitedSupportForCarrier(carrierCode, language).supportMessage, localizedMessage("registered_waiting", language)),
    error: ""
  };
}

function buildTrackingCustomFields(result) {
  const customFields = {};
  const keys = [
    "trackingNumber", "status", "statusText", "subStatus", "carrier", "carrierCode",
    "checkpoint", "location", "eta", "lastUpdate", "trackingUrl", "provider", "error",
    "trackingSupportStatus", "supportMessage", "supportMessageKey", "lastCheckedAt"
  ];

  for (const key of keys) {
    const value = result?.[key];
    if (value !== undefined && value !== null) {
      customFields[`tracking::${key}`] = String(value);
    }
  }

  return customFields;
}

async function writeDeliveryNotification(companyId, orderId, result, language = "English") {
  const notificationId = `delivery_${orderId}`;
  const ref = notificationCollectionRef(companyId).doc(notificationId);
  const snap = await ref.get();

  if (snap.exists && snap.data()?.pushSent === true) {
    return;
  }

  const order = await loadOrderNamesForNotification(orderId);
  const title = deliveryPushTitle(language, order);
  const message = deliveryPushMessage(result, language, order);
  const data = {
    companyId,
    orderId,
    type: "delivery",
    title,
    message,
    customerName: order.customerName,
    designName: order.designName,
    createdAt: admin.firestore.FieldValue.serverTimestamp(),
    read: false,
    actioned: false,
    source: "scheduledTrackingRefresh",
    trackingNumber: result.trackingNumber || "",
    carrier: result.carrier || "",
    checkpoint: result.checkpoint || "",
    location: result.location || "",
    language
  };

  await ref.set(data, { merge: true });

  const pushResult = await sendPushNotificationToCompany(companyId, {
    ...data,
    notificationId,
    createdAt: new Date().toISOString()
  });

  await ref.set({
    pushSent: pushResult.sent > 0,
    pushResult,
    pushSentAt: admin.firestore.FieldValue.serverTimestamp()
  }, { merge: true });
}

async function refreshTrackingCore({ companyId, orderId, trackingNumber, courier, carrierCode, language = "English" }) {
  const token = TRACK17_TOKEN.value();
  const manualCarrier = isAutoDetectCourier(courier) ? "" : courier;
  const manualCarrierCode = carrierCode ? Number(carrierCode) : carrierCodeFromName(manualCarrier);
  const shouldUseRoyalMailOfficial = isRoyalMailCourier(manualCarrier, manualCarrierCode);

  function publicErrorResult(messageKey, messageOverride = "", extra = {}) {
    const message = messageOverride || localizedMessage(messageKey, language);

    return {
      ok: false,
      provider: "17TRACK",
      trackingNumber,
      carrier: manualCarrier,
      carrierCode: manualCarrierCode ? String(manualCarrierCode) : "",
      status: extra.status || "Error",
      statusText: extra.statusText || "Error",
      trackingSupportStatus: extra.trackingSupportStatus || "error",
      supportMessageKey: extra.supportMessageKey || "",
      supportMessage: extra.supportMessage || "",
      error: message,
      lastCheckedAt: admin.firestore.FieldValue.serverTimestamp(),
      trackingUrl: trackingNumber ? `https://www.17track.net/en/track-details?nums=${encodeURIComponent(trackingNumber)}` : "",
      ...extra
    };
  }

  if (!companyId || !orderId || !trackingNumber) {
    return publicErrorResult("missing_parameters");
  }

  if (shouldUseRoyalMailOfficial) {
    const royalMailResult = await tryRoyalMailOfficialTracking(trackingNumber, language);
    if (royalMailResult.ok && hasUsefulTrackingData(royalMailResult)) {
      return royalMailResult;
    }

    // If the official Royal Mail API is configured but only says "waiting", keep the clean
    // Royal Mail result instead of falling back to the noisier 17TRACK Royal Mail registration error.
    if (royalMailResult.trackingSupportStatus === "waiting") {
      return royalMailResult;
    }

    // If 17TRACK is not configured, show the Royal Mail setup/status message.
    if (!token || token.length < 10) {
      return royalMailResult;
    }
  }

  if (!token || token.length < 10) {
    return publicErrorResult("token_missing");
  }

  if (manualCarrier && !manualCarrierCode) {
    return publicErrorResult("courier_not_mapped", "", {
      trackingSupportStatus: "unsupported",
      supportMessageKey: "courier_not_mapped",
      supportMessage: localizedMessage("courier_not_mapped", language)
    });
  }

  const registerBody = buildTrack17Body(trackingNumber, manualCarrierCode, { autoDetection: !manualCarrierCode });
  const registerResponse = await call17Track(TRACK17_REGISTER_URL, token, registerBody);
  let registerAccepted = firstAccepted(registerResponse);
  let registerError = firstApiError(registerResponse);
  let alreadyRegistered = isAlreadyRegistered(registerError);
  let candidateCarrierCode = null;

  // Auto Detect fallback: when 17TRACK cannot detect the carrier from the bare
  // number (common for 10-digit DHL Express waybills), retry registration with
  // pattern-based candidates before asking the user to pick a courier manually.
  if (!registerAccepted && registerError && !alreadyRegistered && isCarrierCannotBeDetected(registerError) && !manualCarrierCode) {
    for (const candidate of carrierCandidatesFromNumber(trackingNumber)) {
      const retryResponse = await call17Track(TRACK17_REGISTER_URL, token, buildTrack17Body(trackingNumber, candidate));
      const retryAccepted = firstAccepted(retryResponse);
      const retryError = firstApiError(retryResponse);
      if (retryAccepted || isAlreadyRegistered(retryError)) {
        registerAccepted = retryAccepted;
        registerError = retryError;
        alreadyRegistered = isAlreadyRegistered(retryError);
        candidateCarrierCode = candidate;
        break;
      }
    }
  }

  if (!registerAccepted && registerError && !alreadyRegistered) {
    const cannotDetect = isCarrierCannotBeDetected(registerError);
    const temporarilyUnsupported = registerError.code === -18019911;

    if (cannotDetect) {
      return publicErrorResult("carrier_required_message", "", {
        status: "Carrier Required",
        statusText: "Carrier Required",
        trackingSupportStatus: "carrier_required",
        supportMessageKey: "carrier_required_message",
        supportMessage: localizedMessage("carrier_required_message", language),
        error: ""
      });
    }

    if (temporarilyUnsupported) {
      const limited = limitedSupportForCarrier(manualCarrierCode, language);
      return publicErrorResult(limited.supportMessageKey || "registered_waiting", "", {
        status: "Limited Support",
        statusText: "Limited Support",
        trackingSupportStatus: limited.trackingSupportStatus || "limited",
        supportMessageKey: limited.supportMessageKey || "registered_waiting",
        supportMessage: limited.supportMessage || localizedMessage("registered_waiting", language),
        error: registerError.message || ""
      });
    }

    return publicErrorResult("", registerError.message || "17TRACK error");
  }

  if (alreadyRegistered && manualCarrierCode) {
    await tryChangeCarrier(token, trackingNumber, manualCarrierCode);
  }

  const detectedCarrierCode = firstNonEmpty(registerAccepted?.carrier, candidateCarrierCode, manualCarrierCode);
  const detectedCarrierName = firstNonEmpty(manualCarrier, carrierNameFromCode(detectedCarrierCode));

  const details = await getTrackingDetails(token, trackingNumber, detectedCarrierCode ? Number(detectedCarrierCode) : null, {
    trackingNumber,
    carrier: detectedCarrierName,
    carrierCode: detectedCarrierCode,
    status: "Registered",
    statusText: "Registered"
  }, language);

  return {
    ok: true,
    provider: "17TRACK",
    trackingNumber,
    carrier: firstNonEmpty(details.carrier, detectedCarrierName),
    carrierCode: firstNonEmpty(details.carrierCode, detectedCarrierCode),
    status: details.status || "Registered",
    statusText: details.statusText || "Registered",
    subStatus: details.subStatus || "",
    checkpoint: details.checkpoint || "",
    location: details.location || "",
    eta: details.eta || "",
    lastUpdate: details.lastUpdate || "",
    trackingUrl: details.trackingUrl || `https://www.17track.net/en/track-details?nums=${encodeURIComponent(trackingNumber)}`,
    trackingSupportStatus: details.trackingSupportStatus || "active",
    language,
    supportMessage: details.supportMessage || "",
    supportMessageKey: details.supportMessageKey || "",
    error: details.error || "",
    lastCheckedAt: admin.firestore.FieldValue.serverTimestamp()
  };
}

exports.registerTracking = onCall({ secrets: [TRACK17_TOKEN, ROYALMAIL_CLIENT_ID, ROYALMAIL_CLIENT_SECRET], region: "europe-west2" }, async (request) => {
  const companyId = String(request.data?.companyId || "").trim();
  const orderId = String(request.data?.orderId || "").trim();
  const trackingNumber = cleanTrackingNumber(request.data?.trackingNumber);
  const courier = String(request.data?.courier || "").trim();
  const language = String(request.data?.language || "English").trim() || "English";
  const ref = providerDocRef(companyId || "missing_company", orderId || "missing_order");

  try {
    const startState = {
      provider: "17TRACK",
      trackingNumber,
      carrier: isAutoDetectCourier(courier) ? "" : courier,
      status: "Registering",
      statusText: "Registering",
      trackingSupportStatus: "waiting",
      language,
      supportMessageKey: "checking_support",
      supportMessage: localizedMessage("checking_support", language),
      lastCheckedAt: admin.firestore.FieldValue.serverTimestamp(),
      trackingUrl: trackingNumber ? `https://www.17track.net/en/track-details?nums=${encodeURIComponent(trackingNumber)}` : "",
      error: ""
    };

    if (companyId && orderId) {
      await ref.set(startState, { merge: true });
    }

    if (trackingNumber) {
      await lookupDocRef(trackingNumber).set({ companyId, orderId, trackingNumber }, { merge: true });
    }

    const result = await refreshTrackingCore({ companyId, orderId, trackingNumber, courier, language });

    const clientResult = {
      ...result,
      lastCheckedAt: new Date().toISOString()
    };

    if (companyId && orderId) {
      await ref.set(result, { merge: true });

      const orderTrackingUpdate = {
        customFields: buildTrackingCustomFields(clientResult)
      };

      if (isDeliveredResult(result)) {
        orderTrackingUpdate.isDelivered = true;
        orderTrackingUpdate.isDispatched = true;
      } else if (isMovingResult(result)) {
        orderTrackingUpdate.isDispatched = true;
      }

      await orderDocRef(orderId).set(orderTrackingUpdate, { merge: true });

      if (isDeliveredResult(result)) {
        await writeDeliveryNotification(companyId, orderId, result, language);
      }
    }

    return clientResult;
  } catch (error) {
    console.error("registerTracking error:", error);

    const result = {
      ok: false,
      provider: "17TRACK",
      trackingNumber,
      carrier: isAutoDetectCourier(courier) ? "" : courier,
      status: "Error",
      statusText: "Error",
      trackingSupportStatus: "error",
      supportMessage: "",
      supportMessageKey: "",
      error: error?.message || String(error) || "Unknown tracking error",
      lastCheckedAt: admin.firestore.FieldValue.serverTimestamp(),
      trackingUrl: trackingNumber ? `https://www.17track.net/en/track-details?nums=${encodeURIComponent(trackingNumber)}` : ""
    };

    const clientResult = {
      ...result,
      lastCheckedAt: new Date().toISOString()
    };

    if (companyId && orderId) {
      try {
        await ref.set(result, { merge: true });
        await orderDocRef(orderId).set({
          customFields: buildTrackingCustomFields(clientResult)
        }, { merge: true });
      } catch (writeError) {
        console.error("registerTracking Firestore error write failed:", writeError);
      }
    }

    return clientResult;
  }
});

exports.scheduledTrackingRefresh = onSchedule({
  schedule: "every 60 minutes",
  timeZone: "Europe/London",
  region: "europe-west2",
  secrets: [TRACK17_TOKEN, ROYALMAIL_CLIENT_ID, ROYALMAIL_CLIENT_SECRET]
}, async () => {
  const snap = await admin.firestore()
    .collectionGroup("trackingResults")
    .where("provider", "==", "17TRACK")
    .limit(80)
    .get();

  let checked = 0;
  let updated = 0;
  let delivered = 0;

  for (const doc of snap.docs) {
    const data = doc.data() || {};
    const orderId = doc.id;
    const companyId = doc.ref.parent.parent?.id || "";
    const trackingNumber = cleanTrackingNumber(data.trackingNumber);
    const statusText = `${data.status || ""} ${data.statusText || ""}`.toLowerCase();

    if (!companyId || !orderId || !trackingNumber) continue;
    if (statusText.includes("delivered")) continue;

    checked += 1;

    try {
      const result = await refreshTrackingCore({
        companyId,
        orderId,
        trackingNumber,
        courier: data.carrier || "",
        carrierCode: data.carrierCode || null,
        language: data.language || "English"
      });

      await doc.ref.set(result, { merge: true });
      await orderDocRef(orderId).set({
        ...(isMovingResult(result) ? { isDispatched: true } : {}),
        customFields: buildTrackingCustomFields({
          ...result,
          lastCheckedAt: new Date().toISOString()
        })
      }, { merge: true });
      updated += 1;

      if (isDeliveredResult(result)) {
        await orderDocRef(orderId).set({
          isDelivered: true,
          isDispatched: true,
          customFields: buildTrackingCustomFields({
            ...result,
            lastCheckedAt: new Date().toISOString()
          })
        }, { merge: true });
        await writeDeliveryNotification(companyId, orderId, result, data.language || "English");
        await doc.ref.set({ deliveredNotificationSent: true }, { merge: true });
        delivered += 1;
      }
    } catch (error) {
      console.error("scheduledTrackingRefresh item failed:", orderId, error?.message || error);
      await doc.ref.set({
        trackingSupportStatus: "error",
        error: error?.message || String(error),
        lastCheckedAt: admin.firestore.FieldValue.serverTimestamp()
      }, { merge: true });
    }
  }

  console.log("scheduledTrackingRefresh complete", { checked, updated, delivered });
});

function parseSwiftDate(value) {
  if (value === null || value === undefined) return null;
  if (value instanceof Date) return value;

  if (typeof value === "number") {
    // Swift JSONEncoder Date default is seconds since 2001-01-01.
    const unixSeconds = value > 2000000000 ? value / 1000 : value + 978307200;
    return new Date(unixSeconds * 1000);
  }

  if (typeof value === "string") {
    const parsed = new Date(value);
    if (!Number.isNaN(parsed.getTime())) return parsed;

    const numeric = Number(value);
    if (Number.isFinite(numeric)) return parseSwiftDate(numeric);
  }

  return null;
}

exports.scheduledReminderCheck = onSchedule({
  schedule: "every 15 minutes",
  timeZone: "Europe/London",
  region: "europe-west2"
}, async () => {
  const now = new Date();
  const snap = await admin.firestore()
    .collection("siparisler")
    .where("companyId", "==", "test_studio_123")
    .limit(200)
    .get();

  let dueCount = 0;
  const batch = admin.firestore().batch();
  const notificationsToPush = [];

  for (const doc of snap.docs) {
    const order = doc.data() || {};
    const rawJSON = order.customFields?.__scheduleAlertItemsV1;
    if (!rawJSON) continue;

    let items = [];
    try {
      items = JSON.parse(rawJSON);
    } catch (error) {
      console.error("scheduledReminderCheck JSON parse failed:", doc.id, error?.message || error);
      continue;
    }

    let changed = false;
    const language = order.language || order.customFields?.language || order.customFields?.selectedLanguage || "English";

    for (const item of items) {
      const dueAt = parseSwiftDate(item.dueAt);
      if (!dueAt) continue;

      const isPending = String(item.status || "Pending") !== "Done";
      const shouldNotify = item.notify !== false;
      const alreadySent = item.notificationSent === true;

      if (isPending && shouldNotify && !alreadySent && dueAt <= now) {
        const companyId = order.companyId || "test_studio_123";
        const notificationId = `schedule_${doc.id}_${item.id}`;
        const notificationRef = notificationCollectionRef(companyId).doc(notificationId);
        const fallbackTitle = pushText("reminderTitle", language);
        const title = item.title || fallbackTitle;
        const message = order.customerName ? `${order.customerName}: ${title}` : title;

        const data = {
          companyId,
          orderId: doc.id,
          type: "schedule",
          title,
          message,
          note: item.note || "",
          priority: item.priority || "Normal",
          createdAt: admin.firestore.FieldValue.serverTimestamp(),
          dueAt,
          read: false,
          actioned: false,
          source: "scheduledReminderCheck",
          language
        };

        batch.set(notificationRef, data, { merge: true });
        notificationsToPush.push({
          companyId,
          notificationRef,
          notificationId,
          data: { ...data, createdAt: now.toISOString(), dueAt: dueAt.toISOString() }
        });

        item.notificationSent = true;
        changed = true;
        dueCount += 1;
      }
    }

    if (changed) {
      const customFields = {
        ...(order.customFields || {}),
        __scheduleAlertItemsV1: JSON.stringify(items)
      };
      batch.set(doc.ref, { customFields }, { merge: true });
    }
  }

  if (dueCount > 0) {
    await batch.commit();
  }

  for (const pending of notificationsToPush) {
    try {
      const pushResult = await sendPushNotificationToCompany(pending.companyId, {
        ...pending.data,
        notificationId: pending.notificationId
      });
      await pending.notificationRef.set({
        pushSent: pushResult.sent > 0,
        pushResult,
        pushSentAt: admin.firestore.FieldValue.serverTimestamp()
      }, { merge: true });
    } catch (error) {
      console.error("scheduledReminderCheck push failed:", pending.notificationId, error?.message || error);
      await pending.notificationRef.set({
        pushSent: false,
        pushError: error?.message || String(error),
        pushTriedAt: admin.firestore.FieldValue.serverTimestamp()
      }, { merge: true });
    }
  }

  console.log("scheduledReminderCheck complete", { dueCount, pushCount: notificationsToPush.length });
});


function cleanWooText(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function wooNumber(value, fallback = 0) {
  const num = Number(value);
  return Number.isFinite(num) ? num : fallback;
}

// Zapier, Make and hand-rolled senders post money the way a human writes it:
// "£1,234.56", "1.234,56", "120,50". Number() turns every one of those into NaN,
// and the caller's fallback quietly made it a £0 order that answered HTTP 200.
// Returns null when it genuinely cannot read the value, so the caller can say so
// instead of inventing a zero. Woo and Shopify keep wooNumber — they send
// machine-formatted numbers and a tolerant parser would only add guesswork.
const INBOUND_SCHEMA_VERSION = 1;

// Statuses that mean "this order is not happening". Module scope so the payload
// validator and the handler agree on the list — they used to be one local Set.
const REJECT_STATUSES = new Set(["cancelled", "canceled", "refunded", "voided", "failed", "deleted"]);

// Names the ways a payload can be misread. Every one of these was silent: the
// order was created, HTTP 200 came back, and the number on screen was wrong.
function inboundPayloadWarnings(payload) {
  const warnings = [];
  if (!payload || typeof payload !== "object") return ["The body was not a JSON object."];

  const rawTotal = inboundValue(payload, ["total", "amount", "total_price", "totalPrice", "grandTotal"]);
  if (rawTotal !== "" && rawTotal !== null && rawTotal !== undefined && inboundMoneyNumber(rawTotal) === null) {
    warnings.push(`The total "${String(rawTotal).slice(0, 40)}" could not be read as a number, so this order would be saved as 0.`);
  } else if (rawTotal === "" || rawTotal === null || rawTotal === undefined) {
    warnings.push("No total was sent, so this order would be saved as 0.");
  }

  const products = inboundValue(payload, ["products", "items", "lineItems", "line_items"]);
  if (products && !Array.isArray(products)) {
    warnings.push("products was sent as text, so the invoice gets a single line. Send an array of { name, quantity, unitPrice } for an itemised invoice.");
  } else if (Array.isArray(products) && products.length > 0 && !products.some(item => item && typeof item === "object")) {
    warnings.push("products is a list of names with no prices, so the invoice gets a single line.");
  }

  if (payload.currency) {
    warnings.push("currency is recorded for reference only — the order is shown in your workspace currency.");
  }

  const status = String(inboundValue(payload, ["status", "financial_status", "paymentStatus"]) || "").toLowerCase();
  if (status && REJECT_STATUSES.has(status)) {
    warnings.push(`status "${status}" means this order would be dropped without being created.`);
  }

  if (!inboundValue(payload, ["orderId", "id", "order_id", "orderNumber", "number"])) {
    warnings.push("No orderId, so no order can be created. It is also what stops a redelivery creating a second copy.");
  }

  // Anything outside every alias list vanishes silently, which is how a
  // misconfigured Zap ends up producing "Website Customer" and a £0 total.
  const known = new Set([
    "companyId", "company_id", "studioflow_company_id", "test", "nivadeskTest", "schemaVersion",
    "orderId", "id", "order_id", "orderNumber", "number", "order_number",
    "total", "amount", "total_price", "totalPrice", "grandTotal",
    "createdAt", "created_at", "date", "orderDate",
    "products", "items", "lineItems", "line_items", "productNames",
    "designName", "design_name", "title",
    "customerName", "customer_name", "name", "fullName", "buyerName",
    "source", "platform", "store", "paymentMethod", "payment_method", "gateway",
    "email", "customerEmail", "buyerEmail", "phone", "telephone", "whatsapp", "mobile",
    "note", "notes", "customerNote", "message",
    "status", "financial_status", "paymentStatus",
    "billing", "billingAddress", "billing_address", "address",
    "shipping", "shippingAddress", "shipping_address",
    "currency", "sku", "ref", "watchRef", "deliveryTime", "delivery_days",
    "orderUrl", "url", "link", "permalink", "instagram", "instagramUsername",
    "shippingCost", "shipping_total", "deliveryCost", "tax", "total_tax", "taxAmount"
  ]);
  const ignored = Object.keys(payload).filter(key => !known.has(key));
  if (ignored.length > 0) {
    warnings.push(`These fields were not recognised and would be ignored: ${ignored.slice(0, 10).join(", ")}.`);
  }
  return warnings;
}

function inboundMoneyNumber(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value !== "string") return null;
  const cleaned = value.replace(/[^\d.,-]/g, "").trim();
  if (!cleaned) return null;
  const lastComma = cleaned.lastIndexOf(",");
  const lastDot = cleaned.lastIndexOf(".");
  let normalized;
  if (lastComma >= 0 && lastDot >= 0) {
    // Whichever separator comes last is the decimal point.
    normalized = lastComma > lastDot
      ? cleaned.replace(/\./g, "").replace(",", ".")
      : cleaned.replace(/,/g, "");
  } else if (lastComma >= 0) {
    // "1,234" is ambiguous; three trailing digits means thousands, else decimal.
    normalized = /,\d{3}$/.test(cleaned) ? cleaned.replace(/,/g, "") : cleaned.replace(",", ".");
  } else {
    normalized = cleaned;
  }
  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : null;
}

function wooDate(value, fallback = new Date()) {
  if (!value) return fallback;
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? fallback : parsed;
}

function wooMetaValue(order, keys = []) {
  const meta = Array.isArray(order?.meta_data) ? order.meta_data : [];
  for (const key of keys) {
    const found = meta.find((item) => cleanWooText(item?.key).toLowerCase() === cleanWooText(key).toLowerCase());
    const value = cleanWooText(found?.value);
    if (value) return value;
  }
  return "";
}

function wooSafeDocPart(value) {
  return cleanWooText(value).replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 80) || "workspace";
}

function wooLineItems(order) {
  return Array.isArray(order?.line_items) ? order.line_items : [];
}

function wooLineItemsSummary(order) {
  return wooLineItems(order)
    .map((item) => {
      const quantity = item?.quantity ? ` x${item.quantity}` : "";
      return `${cleanWooText(item?.name) || "Product"}${quantity}`;
    })
    .filter(Boolean)
    .join(", ");
}

// Money rounding that preserves sign (unlike roundMoneyValue which clamps negatives to 0),
// so a discount reconciling line can be negative.
function roundLineMoney(value) {
  const n = Number(value);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : 0;
}

// When the product lines don't sum to the order's grand total (shipping, fees, discounts),
// append a single reconciling line so the itemized invoice always foots to the real total
// the customer paid. Mutates and returns the array. Schema matches every client's LineItem.
function reconcileLineItems(items, total) {
  if (!Array.isArray(items) || items.length === 0) return items || [];
  const sum = roundLineMoney(items.reduce((acc, i) => acc + (Number(i.lineTotal) || 0), 0));
  const diff = roundLineMoney(Number(total) - sum);
  if (Math.abs(diff) > 0.01) {
    items.push({
      id: crypto.randomUUID(),
      name: diff > 0 ? "Shipping & other" : "Discount",
      quantity: 1,
      unitPrice: diff,
      lineTotal: diff
    });
  }
  return items;
}

// Structured invoice line items from WooCommerce line_items, using gross (VAT-inclusive)
// amounts so they sum toward the same VAT-inclusive order total the rest of the app uses.
// Schema must match every client's LineItem: { id, name, quantity, unitPrice, lineTotal }.
function wooStructuredLineItems(order) {
  return wooLineItems(order)
    .map((item) => {
      const quantity = Math.max(1, wooNumber(item?.quantity, 1));
      const lineTotal = roundLineMoney(wooNumber(item?.total, 0) + wooNumber(item?.total_tax, 0));
      return {
        id: crypto.randomUUID(),
        name: cleanWooText(item?.name) || "Product",
        quantity,
        unitPrice: roundLineMoney(lineTotal / quantity),
        lineTotal
      };
    })
    .filter((i) => i.name);
}

function wooBillingFullName(order) {
  const billing = order?.billing || {};
  const name = [billing.first_name, billing.last_name].map(cleanWooText).filter(Boolean).join(" ");
  return name || cleanWooText(billing.company) || cleanWooText(order?.customer_name) || "WooCommerce Customer";
}

// A real phone number never contains "@". Some checkouts mis-enter the email into the
// phone field; treat an email-looking value as no phone so it never lands in a phone field.
function sanitizePhone(value) {
  const v = cleanWooText(value);
  return v.includes("@") ? "" : v;
}

function wooPhone(order) {
  return sanitizePhone(order?.billing?.phone || order?.shipping?.phone || wooMetaValue(order, ["phone", "telephone", "whatsapp", "WhatsApp"]));
}

// Extract a structured address from a WooCommerce billing/shipping object.
function wooAddressParts(addr) {
  const a = addr || {};
  const street = [cleanWooText(a.address_1), cleanWooText(a.address_2)].filter(Boolean).join(", ");
  const name = [cleanWooText(a.first_name), cleanWooText(a.last_name)].filter(Boolean).join(" ");
  return {
    name: name || cleanWooText(a.company),
    street,
    city: cleanWooText(a.city),
    state: cleanWooText(a.state),
    postalCode: cleanWooText(a.postcode),
    country: cleanWooText(a.country),
    phone: sanitizePhone(a.phone)
  };
}

// Single-line readable address (for the customer's combined `address` field).
// Operates on the normalized parts shape from wooAddressParts / shopifyAddressParts.
function formatAddressParts(p) {
  const cityLine = [p.city, p.state].filter(Boolean).join(", ");
  return [p.street, cityLine, p.postalCode, p.country].filter(Boolean).join(", ");
}

// Seed the payment ledger with the order's initial paid amount, so the "Payments"
// section shows it just like the manually-entered flow (which records a PaymentEntry).
// Mirrors the Swift seedInitialPaymentFromPaidIfNeeded: a single entry, only when the
// paid amount is positive. Returns [] otherwise. Schema must match every client's
// PaymentEntry: { id, amount, date, method, note, createdByUid, createdByEmail }.
function seedInitialPayment(amount, date, method) {
  const rounded = Math.round((Number(amount) || 0) * 100) / 100;
  if (rounded <= 0.005) return [];
  return [{
    id: crypto.randomUUID(),
    amount: rounded,
    date,
    method: cleanWooText(method),
    note: "",
    createdByUid: "",
    createdByEmail: ""
  }];
}

function wooCompanyId(req, order) {
  return cleanWooText(
    req.query?.companyId ||
    req.query?.company_id ||
    req.headers?.["x-studioflow-company-id"] ||
    wooMetaValue(order, ["companyId", "company_id", "studioflow_company_id", "_studioflow_company_id"])
  );
}

function wooOrderDocId(companyId, wooOrderId) {
  return `woo_${wooSafeDocPart(companyId)}_${wooSafeDocPart(wooOrderId)}`;
}

// Resolves the workspace-configured default delivery time (days) for incoming
// integration orders. Defaults to 30 (the studio's average turnaround) and is
// clamped to a sane 1..730 range.
function resolveDefaultDeliveryTime(settingsData) {
  const raw = Number(settingsData && settingsData.defaultDeliveryTime);
  if (!Number.isFinite(raw) || raw <= 0) return 30;
  return Math.min(Math.max(Math.round(raw), 1), 730);
}

// A redelivery of the same order used to write the whole mapped object back with
// merge:true. Every field the mapper produces is unconditionally present, so a
// shop that resends an order — Woo retries, a Shopify update, a Zapier replay —
// silently reset the studio's own work: designStatus and status back to
// "Not Yet", the tracking number and courier blanked, the delivery time reset.
// The shop owns the money and the customer; the studio owns the workflow.
const INTEGRATION_SHOP_OWNED_FIELDS = new Set([
  "customerName",
  "designName",
  "designLink",
  "emailAddress",
  "whatsappNumber",
  "instagramUsername",
  "notes",
  "paidAmount",
  "remainingAmount",
  "orderValue",
  "lineItems",
  "payments",
  "deliveryCost",
  "taxAmount",
  "taxRate",
  "shippingName",
  "shippingStreetAddress",
  "shippingCity",
  "shippingPostalCode",
  "shippingCountry",
  "shippingPhone",
  "customFields",
  "companyId",
  "updatedAt",
  "source"
]);

function integrationOrderUpdate(mappedOrder, isNew) {
  if (isNew) return mappedOrder;
  const patch = {};
  for (const [key, value] of Object.entries(mappedOrder)) {
    if (INTEGRATION_SHOP_OWNED_FIELDS.has(key)) patch[key] = value;
  }
  return patch;
}

function mapWooCommerceOrderToSiparis(order, companyId, isNew = true, defaultDeliveryTime = 30) {
  const now = new Date();
  const wooId = cleanWooText(order?.id || order?.number || crypto.randomUUID());
  const orderNumber = cleanWooText(order?.number || order?.id || wooId);
  const status = cleanWooText(order?.status || "new");
  const total = wooNumber(order?.total, 0);
  const createdAt = wooDate(order?.date_paid || order?.date_created || order?.date_created_gmt, now);
  // Default delivery time comes from the workspace setting (the studio's average
  // turnaround). An explicit per-order `studioflow_delivery_days` meta still wins
  // if the store sets one, but generic WooCommerce delivery/shipping metas are
  // ignored. NOTE: wooMetaValue returns "" (not undefined) for a missing meta, and
  // wooNumber("") is 0 (a finite number, so it never falls back) — that 0 was the
  // real reason every incoming order looked far too short. So fall back explicitly.
  const deliveryMeta = wooMetaValue(order, ["studioflow_delivery_days"]);
  const deliveryTime = deliveryMeta
    ? Math.min(Math.max(Math.round(wooNumber(deliveryMeta, defaultDeliveryTime)), 1), 730)
    : defaultDeliveryTime;
  const lineSummary = wooLineItemsSummary(order);
  const firstItem = wooLineItems(order)[0] || {};
  // Structured invoice line items (real per-product prices), reconciled to the order total.
  const lineItems = reconcileLineItems(wooStructuredLineItems(order), total);
  const designName = cleanWooText(wooMetaValue(order, ["designName", "design_name", "Design Name"]) || lineSummary || firstItem?.name || `WooCommerce #${orderNumber}`);
  const watchRef = cleanWooText(wooMetaValue(order, ["watchRef", "watch_ref", "Watch Ref", "watch model"]) || firstItem?.sku || "");
  // The customer's actual payment method (PayPal, card, bank transfer…). Left empty when
  // the order carries none (e.g. a manually-created order) — we don't substitute "WooCommerce".
  // The order's source/channel is recorded separately in `communication`.
  const paymentMethod = cleanWooText(order?.payment_method_title || order?.payment_method || "");
  const customerNote = cleanWooText(order?.customer_note || "");
  const email = cleanWooText(order?.billing?.email || order?.shipping?.email || "");
  const phone = wooPhone(order);

  // Billing goes to the customer record; shipping is per-order (can differ).
  // WooCommerce sends an empty shipping object when "ship to billing" is used,
  // so fall back to the billing address in that case.
  const billingParts = wooAddressParts(order?.billing);
  const rawShipping = wooAddressParts(order?.shipping);
  const shippingHasAddress = Boolean(rawShipping.street || rawShipping.city || rawShipping.postalCode);
  const shippingParts = shippingHasAddress ? rawShipping : billingParts;

  const customFields = {
    Source: "WooCommerce",
    "WooCommerce Order ID": wooId,
    "WooCommerce Order Number": orderNumber,
    "WooCommerce Status": status,
    "WooCommerce Payment Method": paymentMethod,
    "WooCommerce Currency": cleanWooText(order?.currency || ""),
    "WooCommerce Total": cleanWooText(order?.total || ""),
    "WooCommerce Created At": cleanWooText(order?.date_created || order?.date_created_gmt || ""),
    "WooCommerce Products": lineSummary,
    // Billing address on the order so the invoice's Billing Address block is populated.
    communicationAddress: formatAddressParts(billingParts)
  };

  const mapped = {
    companyId,
    paymentMethod,
    customerName: wooBillingFullName(order),
    paymentDate: createdAt,
    paidAmount: total,
    remainingAmount: 0,
    watchPurchasePrice: 0,
    watchRef,
    deliveryTime,
    designName,
    lineItems,
    designLink: cleanWooText(order?.permalink || order?.url || ""),
    communication: ["WooCommerce"],
    emailAddress: email,
    instagramUsername: "",
    whatsappNumber: phone,
    notes: customerNote,
    shippingName: shippingParts.name || wooBillingFullName(order),
    shippingStreetAddress: shippingParts.street,
    shippingCity: shippingParts.city,
    shippingPostalCode: shippingParts.postalCode,
    shippingCountry: shippingParts.country,
    shippingPhone: shippingParts.phone || phone,
    designStatus: "Not Yet",
    status: "Not Yet",
    isDispatched: false,
    trackingNumber: "",
    courier: "Auto Detect",
    isDelivered: false,
    paymentFee: 0,
    deliveryCost: wooNumber(order?.shipping_total, 0),
    taxType: "",
    extraStatuses: {},
    taxRate: 0,
    invBool1: false,
    invBool2: false,
    invBool3: false,
    invBool4: false,
    invNotes: "",
    taxAmount: wooNumber(order?.total_tax, 0),
    priority: "Normal",
    risk: "None",
    riskReason: "-",
    customFields,
    customToggles: {},
    clientFiles: [],
    todoItems: [],
    workSessions: [],
    assignedToUid: "",
    assignedToEmail: ""
  };

  if (isNew) {
    mapped.historyLog = [{
      id: crypto.randomUUID(),
      createdAt: now,
      title: "Order created",
      oldValue: "WooCommerce",
      newValue: `#${orderNumber}`
    }];
    const seededPayments = seedInitialPayment(total, createdAt, paymentMethod);
    if (seededPayments.length) mapped.payments = seededPayments;
  }

  return mapped;
}

// Create or update a customer (musteriler) from a WooCommerce order's billing
// details. Matches by name within the workspace. Only writes non-empty values so
// a later order never wipes an address the studio already has. Non-transactional
// (webhook context); failures are swallowed by the caller.
// Shared by the WooCommerce and Shopify webhooks: mirror an order's billing contact
// into the workspace customer list. `source` tags the origin ("woocommerce"/"shopify").
async function upsertIntegrationCustomer(companyId, info, source = "woocommerce") {
  const name = cleanWooText(info.name);
  if (!name || name === "WooCommerce Customer" || name === "Shopify Customer" || name === "Website Customer") return;

  const db = admin.firestore();
  // Identity beats spelling: the store's own customer id first, then the
  // email, then the display name. A Shopify customer who fixes a typo in
  // their name stops minting a duplicate record the moment their id or email
  // already lives here.
  const externalCustomerId = cleanWooText(String(info.externalCustomerId ?? "")).slice(0, 80);
  let snap = { empty: true, docs: [] };
  if (externalCustomerId) {
    snap = await db.collection("musteriler")
      .where("companyId", "==", companyId)
      .where("source", "==", source)
      .where("externalCustomerId", "==", externalCustomerId)
      .limit(1)
      .get();
  }
  const email = cleanWooText(info.email);
  if (snap.empty && email) {
    snap = await db.collection("musteriler")
      .where("companyId", "==", companyId)
      .where("email", "==", email)
      .limit(1)
      .get();
  }
  if (snap.empty) {
    snap = await db.collection("musteriler")
      .where("companyId", "==", companyId)
      .where("name", "==", name)
      .limit(1)
      .get();
  }

  const fields = {
    email: cleanWooText(info.email),
    phone: cleanWooText(info.phone),
    address: cleanWooText(info.address),
    streetAddress: cleanWooText(info.streetAddress),
    city: cleanWooText(info.city),
    postalCode: cleanWooText(info.postalCode),
    country: cleanWooText(info.country),
    // Latest known per-order shipping destination, structured + combined line, so the
    // customer screen can show (and edit) where this customer's orders actually ship to.
    shippingAddress: cleanWooText(info.shippingAddress),
    shippingStreetAddress: cleanWooText(info.shippingStreetAddress),
    shippingCity: cleanWooText(info.shippingCity),
    shippingPostalCode: cleanWooText(info.shippingPostalCode),
    shippingCountry: cleanWooText(info.shippingCountry),
    shippingPhone: cleanWooText(info.shippingPhone)
  };

  if (!snap.empty) {
    // Field-level conflict policy: by default the store's latest details win;
    // with integrationCustomerSync = "nivadesk" the studio's own edits win and
    // the store may only fill fields that are still blank.
    const existingData = snap.docs[0].data() || {};
    const settingsSnap = await db.collection("companySettings").doc(companyId).get();
    const storeWins = !(settingsSnap.exists && settingsSnap.data()?.integrationCustomerSync === "nivadesk");
    const update = { updatedAt: admin.firestore.FieldValue.serverTimestamp(), source };
    if (externalCustomerId) update.externalCustomerId = externalCustomerId;
    for (const [key, value] of Object.entries(fields)) {
      if (!value) continue;
      if (!storeWins && cleanWooText(existingData[key])) continue;
      update[key] = value;
    }
    // Integration panel data: when the store last spoke, and exactly what it
    // said (normalized payload, so Resync can re-apply it and the profile can
    // show the raw values without another webhook).
    update.integrationSyncedAt = admin.firestore.FieldValue.serverTimestamp();
    update.integrationLastPayload = JSON.stringify({ name, externalCustomerId, ...fields }).slice(0, 6000);
    await snap.docs[0].ref.set(update, { merge: true });
    return;
  }

  await db.collection("musteriler").doc().set({
    companyId,
    name,
    instagram: "",
    notes: "",
    profileImageUrl: "",
    ...fields,
    externalCustomerId,
    integrationSyncedAt: admin.firestore.FieldValue.serverTimestamp(),
    integrationLastPayload: JSON.stringify({ name, externalCustomerId, ...fields }).slice(0, 6000),
    lastContactDate: admin.firestore.FieldValue.serverTimestamp(),
    createdAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    source
  });
}

// Constant-time string comparison to avoid timing side channels on secret checks.
function nvTimingSafeEqual(a, b) {
  const ba = Buffer.from(String(a || ""));
  const bb = Buffer.from(String(b || ""));
  return ba.length === bb.length && crypto.timingSafeEqual(ba, bb);
}

function woocommerceDeliveryUrl(companyId, token) {
  return "https://europe-west2-eggcraft-studio.cloudfunctions.net/woocommerceOrderWebhook"
    + `?companyId=${encodeURIComponent(companyId)}&token=${encodeURIComponent(token)}`;
}

// Owner-only: returns this workspace's WooCommerce webhook token + full Delivery URL,
// minting a per-workspace token on first use. The token is what the webhook checks, so each
// workspace gets an isolated, unguessable credential shown in the app's integration screen.
// Webhook tokens used to live as fields on companies/{companyId}. That document
// is readable by every member — owner, admin, member, viewer, workflow — so any
// of them could lift a URL that creates orders in the workspace. They live in a
// server-only subcollection now. Whatever is still on the company document is
// moved across the first time it is read and the old field is cleared, so a
// workspace migrates itself on its next webhook delivery or settings visit.
const INTEGRATION_KINDS = {
  woocommerce: { tokenField: "woocommerceWebhookToken", createdAtField: "woocommerceWebhookTokenCreatedAt" },
  shopify: { tokenField: "shopifyWebhookToken", createdAtField: "shopifyWebhookTokenCreatedAt" },
  inbound: { tokenField: "inboundWebhookToken", createdAtField: "inboundWebhookTokenCreatedAt" }
};

function integrationSecretRef(companyId, kind) {
  return admin.firestore().collection("companies").doc(companyId).collection("integrationSecrets").doc(kind);
}

function integrationMillis(value) {
  if (!value) return 0;
  if (typeof value.toMillis === "function") return value.toMillis();
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

async function readIntegrationSecret(companyId, kind) {
  const config = INTEGRATION_KINDS[kind];
  if (!config) throw new HttpsError("invalid-argument", "Unknown integration.");
  const ref = integrationSecretRef(companyId, kind);
  const snap = await ref.get();
  if (snap.exists) {
    const data = snap.data() || {};
    const token = String(data.token || "").trim();
    if (token) return { token, data };
  }

  const companyRef = admin.firestore().collection("companies").doc(companyId);
  const companySnap = await companyRef.get();
  const legacyToken = String((companySnap.data() || {})[config.tokenField] || "").trim();
  if (!legacyToken) return { token: "", data: snap.exists ? snap.data() || {} : {} };

  const createdAt = (companySnap.data() || {})[config.createdAtField] || null;
  await ref.set({ token: legacyToken, createdAt: createdAt || admin.firestore.FieldValue.serverTimestamp() }, { merge: true });
  await companyRef.set({
    [config.tokenField]: admin.firestore.FieldValue.delete(),
    [config.createdAtField]: admin.firestore.FieldValue.delete()
  }, { merge: true });
  return { token: legacyToken, data: { token: legacyToken, createdAt } };
}

async function mintIntegrationToken(companyId, kind) {
  if (!INTEGRATION_KINDS[kind]) throw new HttpsError("invalid-argument", "Unknown integration.");
  const token = crypto.randomBytes(24).toString("hex");
  await integrationSecretRef(companyId, kind).set({
    token,
    createdAt: admin.firestore.FieldValue.serverTimestamp()
  }, { merge: true });
  return token;
}

// What the Settings page needs to say whether the integration is actually
// working: nobody could tell before, because nothing was recorded.
async function recordIntegrationDelivery(companyId, kind, outcome) {
  if (!INTEGRATION_KINDS[kind] || !companyId) return;
  try {
    const ref = integrationSecretRef(companyId, kind);
    // A short delivery log, newest first, capped at nine — enough to answer
    // "did last night's orders arrive" without building a logging system. The
    // read-modify-write is fine at webhook volume; two racing deliveries can at
    // worst cost one line of history, never a stored order.
    const entry = {
      atMs: Date.now(),
      ok: outcome.ok === true,
      test: outcome.test === true,
      error: outcome.ok === true ? "" : String(outcome.error || "unauthorized").slice(0, 200),
      orderId: String(outcome.orderId || "").slice(0, 120),
      source: String(outcome.source || "").slice(0, 80)
    };
    let recent = [entry];
    try {
      const snap = await ref.get();
      const prior = snap.exists && Array.isArray((snap.data() || {}).recentDeliveries) ? snap.data().recentDeliveries : [];
      recent = [entry, ...prior].slice(0, 9);
    } catch {
      /* keep the single fresh entry */
    }
    await ref.set({
      lastDeliveryAt: admin.firestore.FieldValue.serverTimestamp(),
      lastDeliveryOk: outcome.ok === true,
      // Without this a pressed test button paints the same green a real order
      // does, and a broken Zap looks connected forever.
      lastDeliveryWasTest: outcome.test === true,
      lastDeliveryError: outcome.ok === true ? "" : String(outcome.error || "unauthorized").slice(0, 300),
      recentDeliveries: recent
    }, { merge: true });
  } catch (error) {
    console.warn("recordIntegrationDelivery failed", { companyId, kind, error: String(error) });
  }
}

function integrationStatusPayload(data = {}) {
  return {
    tokenCreatedAtMs: integrationMillis(data.createdAt),
    lastDeliveryAtMs: integrationMillis(data.lastDeliveryAt),
    lastDeliveryOk: data.lastDeliveryOk === true,
    lastDeliveryWasTest: data.lastDeliveryWasTest === true,
    lastDeliveryError: String(data.lastDeliveryError || ""),
    recentDeliveries: (Array.isArray(data.recentDeliveries) ? data.recentDeliveries : []).map((d) => ({
      atMs: Number(d && d.atMs) || 0,
      ok: Boolean(d && d.ok),
      test: Boolean(d && d.test),
      error: String((d && d.error) || ""),
      orderId: String((d && d.orderId) || ""),
      source: String((d && d.source) || "")
    }))
  };
}

// The requester's address, for the delivery log. Behind Google's front end the
// first x-forwarded-for hop is the client.
function integrationRequestSource(req) {
  const fwd = String(req.headers["x-forwarded-for"] || "").split(",")[0].trim();
  return fwd || String(req.ip || req.socket?.remoteAddress || req.connection?.remoteAddress || "");
}

// Rotating invalidates the old URL immediately. That is the point: a token that
// has been shared in a screenshot or a support thread cannot be taken back any
// other way.
// Presses the workspace's own delivery URL with a test payload and hands back
// whatever the handler said. Be plain about what this proves: the endpoint, the
// companyId, the token and the round trip. It cannot prove the URL was pasted
// into Zapier correctly, because the server posts to a URL it minted itself.
exports.sendTestInboundWebhook = onCall({ region: "europe-west2", timeoutSeconds: 60 }, async (request) => {
  const { companyId } = await requireWorkspaceForBilling(request, true);
  const { token } = await readIntegrationSecret(companyId, "inbound");
  if (!token) {
    throw new HttpsError("failed-precondition", "Open this page once so a delivery URL is created, then try again.");
  }

  const url = inboundDeliveryUrl(companyId, token);
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 20000);
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ nivadeskTest: true, schemaVersion: INBOUND_SCHEMA_VERSION }),
      signal: controller.signal
    });
    clearTimeout(timer);
    const body = await response.json().catch(() => ({}));
    return {
      ok: response.ok && body?.ok === true,
      status: response.status,
      orderCreated: body?.orderCreated === true,
      warnings: Array.isArray(body?.warnings) ? body.warnings : [],
      message: response.ok
        ? "The delivery URL answered. No order was created."
        : `The delivery URL answered ${response.status}.`
    };
  } catch (error) {
    return {
      ok: false,
      status: 0,
      orderCreated: false,
      warnings: [],
      message: String(error?.name === "AbortError" ? "The delivery URL did not answer in time." : error?.message || error)
    };
  }
});

// The same round-trip proof for the shop webhooks. The handlers answer a
// nivadeskTest payload with test:true and create nothing; the delivery log
// marks the line as a test so the green it paints is honest.
exports.sendTestIntegrationWebhook = onCall({ region: "europe-west2", timeoutSeconds: 60 }, async (request) => {
  const { companyId } = await requireWorkspaceForBilling(request, true);
  const kind = String(request.data?.kind || "");
  if (kind !== "woocommerce" && kind !== "shopify") {
    throw new HttpsError("invalid-argument", "kind must be woocommerce or shopify.");
  }
  const { token } = await readIntegrationSecret(companyId, kind);
  if (!token) {
    throw new HttpsError("failed-precondition", "Open this page once so a delivery URL is created, then try again.");
  }
  const url = kind === "woocommerce" ? woocommerceDeliveryUrl(companyId, token) : shopifyDeliveryUrl(companyId, token);
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 20000);
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ nivadeskTest: true }),
      signal: controller.signal
    });
    clearTimeout(timer);
    const body = await response.json().catch(() => ({}));
    return {
      ok: response.ok && body?.ok === true,
      status: response.status,
      orderCreated: body?.orderCreated === true,
      message: response.ok
        ? "The delivery URL answered. No order was created."
        : `The delivery URL answered ${response.status}.`
    };
  } catch (error) {
    return {
      ok: false,
      status: 0,
      orderCreated: false,
      message: String(error?.name === "AbortError" ? "The delivery URL did not answer in time." : error?.message || error)
    };
  }
});

// Checks a payload without sending it anywhere: same mapper the webhook runs, no
// network, no writes. This is the one that catches a £0 order before it happens.
exports.validateInboundOrderPayload = onCall({ region: "europe-west2" }, async (request) => {
  const { companyId } = await requireWorkspaceForBilling(request, true);
  let payload = request.data && request.data.payload;
  if (typeof payload === "string") {
    try {
      payload = JSON.parse(payload);
    } catch (error) {
      return { ok: false, parseError: "That is not valid JSON.", warnings: [], reads: null };
    }
  }
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return { ok: false, parseError: "Send a JSON object.", warnings: [], reads: null };
  }

  const preview = mapGenericInboundOrderToSiparis(payload, companyId, true);
  const warnings = inboundPayloadWarnings(payload);
  return {
    ok: warnings.length === 0,
    parseError: "",
    schemaVersion: INBOUND_SCHEMA_VERSION,
    warnings,
    reads: {
      orderNumber: preview.watchRef || "",
      customerName: preview.customerName,
      designName: preview.designName,
      total: preview.paidAmount,
      deliveryCost: preview.deliveryCost,
      taxAmount: preview.taxAmount,
      lineItemCount: Array.isArray(preview.lineItems) ? preview.lineItems.length : 0
    }
  };
});

exports.rotateIntegrationWebhookToken = onCall({ region: "europe-west2" }, async (request) => {
  const { companyId } = await requireWorkspaceForBilling(request, true);
  const kind = String(request.data && request.data.integration || "").trim();
  if (!INTEGRATION_KINDS[kind]) throw new HttpsError("invalid-argument", "Unknown integration.");
  const token = await mintIntegrationToken(companyId, kind);
  await integrationSecretRef(companyId, kind).set({
    lastDeliveryAt: admin.firestore.FieldValue.delete(),
    lastDeliveryOk: admin.firestore.FieldValue.delete(),
    lastDeliveryWasTest: admin.firestore.FieldValue.delete(),
    lastDeliveryError: admin.firestore.FieldValue.delete(),
    // A new token starts a new story; deliveries made against the old one
    // would only confuse the picture.
    recentDeliveries: admin.firestore.FieldValue.delete()
  }, { merge: true });
  const deliveryUrl = kind === "woocommerce"
    ? woocommerceDeliveryUrl(companyId, token)
    : kind === "shopify"
      ? shopifyDeliveryUrl(companyId, token)
      : inboundDeliveryUrl(companyId, token);
  return {
    ok: true,
    companyId,
    deliveryUrl,
    ...integrationStatusPayload({ createdAt: admin.firestore.Timestamp.now() }),
    message: "Webhook URL replaced. Paste the new one into your shop."
  };
});

exports.getWooCommerceWebhookToken = onCall({ region: "europe-west2" }, async (request) => {
  const { companyId } = await requireWorkspaceForBilling(request, true);
  // The raw token is deliberately not returned any more: the delivery URL is the
  // only thing a client needs, and nothing ever read the bare token.
  let { token, data } = await readIntegrationSecret(companyId, "woocommerce");
  if (!token) {
    token = await mintIntegrationToken(companyId, "woocommerce");
    data = { createdAt: admin.firestore.Timestamp.now() };
  }
  return {
    ok: true,
    companyId,
    deliveryUrl: woocommerceDeliveryUrl(companyId, token),
    ...integrationStatusPayload(data)
  };
});

// Installment combine: find the single open WooCommerce-sourced order for this
// customer (same email, not deleted, not delivered, within the window). Returns
// the doc only when EXACTLY one matches — ambiguous cases fall back to a new order.
async function findWooMergeCandidate(db, companyId, emailLower, windowMs, now, currentDocId) {
  if (!emailLower) return null;
  const snapshot = await db.collection("siparisler").where("companyId", "==", companyId).get();
  const matches = [];
  for (const doc of snapshot.docs) {
    if (doc.id === currentDocId) continue;
    const o = doc.data() || {};
    if (o.isDeleted === true || o.isDelivered === true) continue;
    if (String(o.emailAddress || "").trim().toLowerCase() !== emailLower) continue;
    const source = (o.customFields && o.customFields.Source) || "";
    if (String(source) !== "WooCommerce") continue;
    const paymentDate = dateFromFirestore(o.paymentDate, null);
    if (!paymentDate || (now.getTime() - paymentDate.getTime()) > windowMs) continue;
    matches.push(doc);
  }
  return matches.length === 1 ? matches[0] : null;
}

// One decision, testable on its own: how a WooCommerce delivery proves
// itself. A stored signing secret plus a PRESENT signature header makes the
// signature authoritative — a wrong signature fails even with a valid URL
// token, because wrong means forgery or misconfiguration and both must be
// loud. Without a header, the workspace token decides as before.
function wooWebhookAuthDecision({ signatureSecret, signatureHeader, rawBody, providedToken, workspaceToken }) {
  let signatureValid = false;
  if (signatureSecret && signatureHeader && rawBody) {
    const expected = crypto.createHmac("sha256", signatureSecret).update(rawBody).digest("base64");
    signatureValid = nvTimingSafeEqual(signatureHeader, expected);
  }
  if (signatureSecret && signatureHeader) {
    return signatureValid
      ? { authed: true, method: "signature", reason: "" }
      : { authed: false, method: "", reason: "invalid WooCommerce signature" };
  }
  if (workspaceToken && nvTimingSafeEqual(providedToken, workspaceToken)) {
    return { authed: true, method: "token", reason: "" };
  }
  return { authed: false, method: "", reason: workspaceToken ? "invalid token" : "no token in the delivery URL" };
}
exports._wooWebhookAuthDecision = wooWebhookAuthDecision;

// Settings report: store WooCommerce's own webhook signing secret so
// deliveries can be verified by X-WC-Webhook-Signature, not just the URL
// token. Owner-only; the secret lives in the server-only integrationSecrets
// store and is never echoed back in full.
exports.saveWooSignatureSecret = onCall({ region: "europe-west2" }, async (request) => {
  const uid = request.auth?.uid;
  if (!uid) throw new HttpsError("unauthenticated", "You must be signed in.");
  const companyId = String(request.data?.companyId || "").trim();
  if (!companyId) throw new HttpsError("invalid-argument", "companyId is required.");
  const companySnap = await admin.firestore().collection("companies").doc(companyId).get();
  if (!companySnap.exists) throw new HttpsError("not-found", "Workspace not found.");
  if (!uidIsCompanyOwner(companySnap.data() || {}, uid)) {
    throw new HttpsError("permission-denied", "Only the workspace owner can change webhook security.");
  }
  const secret = String(request.data?.secret || "").trim();
  if (secret && (secret.length < 8 || secret.length > 128)) {
    throw new HttpsError("invalid-argument", "The signing secret must be 8-128 characters, or empty to turn signature checks off.");
  }
  await integrationSecretRef(companyId, "woocommerce").set({
    signatureSecret: secret,
    signatureSecretUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
    signatureSecretUpdatedByUid: uid
  }, { merge: true });
  return { ok: true, enabled: Boolean(secret), last4: secret ? secret.slice(-4) : "" };
});

exports.woocommerceOrderWebhook = onRequest({ region: "europe-west2" }, async (req, res) => {
  try {
    if (req.method !== "POST") {
      res.status(200).json({
        ok: true,
        message: "WooCommerce webhook endpoint is alive. Use POST from WooCommerce.",
        requiredQuery: "companyId"
      });
      return;
    }

    const order = req.body || {};
    const companyId = wooCompanyId(req, order);
    if (!companyId) {
      res.status(400).json({
        ok: false,
        error: "Missing companyId. Add ?companyId=YOUR_COMPANY_ID to the webhook Delivery URL."
      });
      return;
    }

    // Authentication. Primary: a per-workspace token (woocommerceWebhookToken on the company
    // doc, shown in the app's WooCommerce integration screen). Fallback (transition):
    // a global WOOCOMMERCE_WEBHOOK_SECRET via token or WooCommerce HMAC signature. Each
    // workspace's token is isolated, so knowing one workspace's URL cannot forge orders into
    // another. Backward compatible: if neither a workspace token nor a global secret exists,
    // the request is allowed with a warning.
    const providedToken = String(req.query?.token || req.headers["x-studioflow-token"] || "");
    const companyAuthRef = admin.firestore().collection("companies").doc(companyId);
    const companyAuthSnap = await companyAuthRef.get();
    if (!companyAuthSnap.exists) {
      res.status(404).json({ ok: false, error: "unknown_company" });
      return;
    }
    const { token: workspaceToken, data: wooSecretData } = await readIntegrationSecret(companyId, "woocommerce");
    // There was a second way in here: one platform-wide WOOCOMMERCE_WEBHOOK_SECRET
    // accepted as a plain query token against ANY companyId — a single string that
    // could forge orders into every workspace on the service. It never ran, because
    // the variable was never a defineSecret and so was never mounted into this
    // function, but it was one env var away from running. Deleted rather than
    // configured. Auth is the workspace's own token, and only that.
    // Optional second factor (settings report): WooCommerce signs every
    // delivery with the webhook's own secret when one is set in the Woo admin
    // (X-WC-Webhook-Signature = base64 HMAC-SHA256 of the raw body). If the
    // workspace has stored that secret, a present-but-wrong signature is
    // rejected even with a valid URL token — a wrong signature means either a
    // forgery or a misconfiguration, and both deserve a loud failure rather
    // than a quiet pass.
    const decision = wooWebhookAuthDecision({
      signatureSecret: String((wooSecretData || {}).signatureSecret || "").trim(),
      signatureHeader: String(req.headers["x-wc-webhook-signature"] || "").trim(),
      rawBody: req.rawBody,
      providedToken,
      workspaceToken
    });
    const authed = decision.authed;
    const authMethod = decision.method;
    if (!authed) {
      const reason = decision.reason;
      console.warn(`woocommerceOrderWebhook: rejected request — ${reason}.`);
      await recordIntegrationDelivery(companyId, "woocommerce", { ok: false, error: reason, source: integrationRequestSource(req) });
      res.status(401).json({ ok: false, error: "unauthorized" });
      return;
    }
    // A deliberate test press answers like the inbound endpoint: authenticated,
    // recorded as a test, no order created — so the green it paints is honest.
    if (req.body && (req.body.nivadeskTest === true || req.body.test === true)) {
      await recordIntegrationDelivery(companyId, "woocommerce", { ok: true, test: true, source: integrationRequestSource(req) });
      res.status(200).json({ ok: true, test: true, orderCreated: false });
      return;
    }
    // Recorded here rather than after the order is written: a verification ping
    // that carries no order is still a delivery that arrived and authenticated,
    // which is exactly what "is this connected?" is asking.
    await recordIntegrationDelivery(companyId, "woocommerce", { ok: true, source: integrationRequestSource(req), authMethod, orderId: cleanWooText(order?.id || order?.number) });

    const wooOrderId = cleanWooText(order?.id || order?.number);
    if (!wooOrderId) {
      // Acknowledge non-order payloads (e.g. WooCommerce's save-time test ping) with 200 so
      // WooCommerce does not count them as failed deliveries and auto-disable the webhook.
      res.status(200).json({ ok: true, ignored: "no_order_id" });
      return;
    }

    const docId = wooOrderDocId(companyId, wooOrderId);
    const ref = orderDocRef(docId);
    const existing = await ref.get();

    // Only create a NEW app order for WooCommerce orders whose payment has actually
    // been received: "processing" (paid, in progress) or "completed". Everything else
    // (pending, on-hold, failed, cancelled, refunded, trash, draft, checkout-draft) is
    // ignored on creation. Existing orders are still updated, so later status changes
    // (e.g. a real paid order moving to completed/refunded) are reflected in the app.
    const wooStatus = String(order?.status || "").trim().toLowerCase().replace(/^wc-/, "");
    const WOO_PAID_STATUSES = new Set(["processing", "completed"]);
    if (!existing.exists && !WOO_PAID_STATUSES.has(wooStatus)) {
      // Acknowledge with 200 so WooCommerce does not retry or auto-disable the webhook.
      res.status(200).json({ ok: true, ignored: "unpaid_status", status: wooStatus, orderId: docId });
      return;
    }

    // Installment combine. When this is a brand-new WooCommerce order (no app order
    // at its own docId), and the workspace takes repeat payments for one item as
    // separate WooCommerce orders, fold this payment into the customer's single open
    // WooCommerce order instead of creating a new one. A per-woo-order marker keeps
    // it idempotent (webhook retries / status updates won't double-count).
    if (!existing.exists) {
      const db = admin.firestore();
      const wooOrderNumber = cleanWooText(order?.number || wooOrderId);
      const mergeMarkerRef = db.collection("companies").doc(companyId).collection("wooMergedPayments").doc(wooSafeDocPart(wooOrderId));
      const mergeMarker = await mergeMarkerRef.get();
      if (mergeMarker.exists) {
        res.status(200).json({ ok: true, ignored: "already_merged", mergedInto: mergeMarker.data()?.mergedIntoOrderId || "" });
        return;
      }
      const settingsSnap = await companySettingsDocRef(companyId).get();
      const combineEnabled = settingsSnap.exists ? settingsSnap.data()?.wooCombineInstallments !== false : true;
      const customerEmail = String(order?.billing?.email || order?.shipping?.email || "").trim().toLowerCase();
      if (combineEnabled && customerEmail) {
        const windowMs = 60 * 24 * 60 * 60 * 1000;
        const candidate = await findWooMergeCandidate(db, companyId, customerEmail, windowMs, new Date(), docId);
        if (candidate) {
          const paymentAmount = wooNumber(order?.total, 0);
          const candidateData = candidate.data() || {};
          const payments = Array.isArray(candidateData.payments) ? candidateData.payments.slice() : [];
          payments.push({
            id: crypto.randomUUID(),
            amount: paymentAmount,
            date: new Date(),
            method: cleanWooText(order?.payment_method_title || order?.payment_method || "WooCommerce"),
            note: `WooCommerce installment (order #${wooOrderNumber})`,
            createdByUid: "",
            createdByEmail: ""
          });
          await candidate.ref.set({
            paidAmount: roundMoneyValue(candidateData.paidAmount) + roundMoneyValue(paymentAmount),
            remainingAmount: Math.max(0, roundMoneyValue(candidateData.remainingAmount) - roundMoneyValue(paymentAmount)),
            payments,
            // History Log entry so the merged installment is visible on the
            // order's History card, not only in the Payments ledger.
            historyLog: historyLogWithEntry(
              candidateData,
              "Payment received",
              `WooCommerce installment #${wooOrderNumber}`,
              amountHistoryValue(paymentAmount)
            ),
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
            source: candidateData.source || "woocommerce"
          }, { merge: true });
          await mergeMarkerRef.set({
            mergedIntoOrderId: candidate.id,
            wooOrderId: String(wooOrderId),
            amount: paymentAmount,
            mergedAt: admin.firestore.FieldValue.serverTimestamp()
          });
          await sendPushNotificationToCompany(companyId, {
            title: "WooCommerce payment received",
            body: `${cleanWooText(candidateData.customerName || "")}`.trim(),
            orderId: candidate.id,
            type: "woocommerce_payment"
          }).catch(() => {});
          res.status(200).json({ ok: true, merged: true, mergedInto: candidate.id, orderId: candidate.id });
          return;
        }
      }
    }

    const wooDefaultDeliveryTime = resolveDefaultDeliveryTime((await companySettingsDocRef(companyId).get()).data());
    const mappedOrder = mapWooCommerceOrderToSiparis(order, companyId, !existing.exists, wooDefaultDeliveryTime);
    await ref.set(integrationOrderUpdate(mappedOrder, !existing.exists), { merge: true });

    // Mirror the billing contact into the workspace's customer list (address,
    // phone, email). Best-effort: never block the order webhook on this.
    try {
      const billing = wooAddressParts(order?.billing);
      const rawShip = wooAddressParts(order?.shipping);
      const shipping = (rawShip.street || rawShip.city || rawShip.postalCode) ? rawShip : billing;
      await upsertIntegrationCustomer(companyId, {
        name: mappedOrder.customerName,
        externalCustomerId: order?.customer_id ? String(order.customer_id) : "",
        email: mappedOrder.emailAddress,
        phone: mappedOrder.whatsappNumber,
        address: formatAddressParts(billing),
        streetAddress: billing.street,
        city: billing.city,
        postalCode: billing.postalCode,
        country: billing.country,
        shippingAddress: formatAddressParts(shipping),
        shippingStreetAddress: shipping.street,
        shippingCity: shipping.city,
        shippingPostalCode: shipping.postalCode,
        shippingCountry: shipping.country,
        shippingPhone: shipping.phone || mappedOrder.whatsappNumber
      }, "woocommerce");
    } catch (error) {
      console.warn("WooCommerce customer upsert failed:", error?.message || error);
    }

    await sendPushNotificationToCompany(companyId, {
      title: "New WooCommerce order",
      body: `${mappedOrder.customerName}: ${mappedOrder.designName}`,
      orderId: docId,
      type: "woocommerce_order"
    });

    res.status(200).json({
      ok: true,
      created: !existing.exists,
      orderId: docId,
      companyId
    });
  } catch (error) {
    console.error("woocommerceOrderWebhook error:", error);
    res.status(500).json({ ok: false, error: error.message || String(error) });
  }
});


// ---------------------------------------------------------------------------
// Shopify webhook integration.
//
// Mirrors the WooCommerce flow exactly (per-workspace token → map → dedupe →
// write + push) but with a Shopify-shaped order mapper. It only REUSES the
// generic utilities (cleanWooText / wooNumber / wooDate / wooSafeDocPart /
// nvTimingSafeEqual / orderDocRef / sendPushNotificationToCompany); it does NOT
// touch any WooCommerce function, so the existing integration is unaffected.
// ---------------------------------------------------------------------------

function shopifyCompanyId(req, order) {
  const fromAttributes = Array.isArray(order?.note_attributes)
    ? order.note_attributes.find((attr) => /^company_?id$|studioflow_company_id/i.test(cleanWooText(attr?.name)))?.value
    : "";
  return cleanWooText(
    req.query?.companyId ||
    req.query?.company_id ||
    req.headers?.["x-studioflow-company-id"] ||
    fromAttributes
  );
}

function shopifyOrderDocId(companyId, shopifyOrderId) {
  return `shopify_${wooSafeDocPart(companyId)}_${wooSafeDocPart(shopifyOrderId)}`;
}

function shopifyLineItems(order) {
  return Array.isArray(order?.line_items) ? order.line_items : [];
}

function shopifyLineItemsSummary(order) {
  return shopifyLineItems(order)
    .map((item) => {
      const quantity = item?.quantity ? ` x${item.quantity}` : "";
      return `${cleanWooText(item?.title || item?.name) || "Product"}${quantity}`;
    })
    .filter(Boolean)
    .join(", ");
}

// Structured invoice line items from Shopify line_items. Shopify `price` is the unit price;
// any tax / shipping difference is captured by the reconciling line so the invoice foots to
// total_price. Schema matches every client's LineItem: { id, name, quantity, unitPrice, lineTotal }.
function shopifyStructuredLineItems(order) {
  return shopifyLineItems(order)
    .map((item) => {
      const quantity = Math.max(1, wooNumber(item?.quantity, 1));
      const unitPrice = roundLineMoney(wooNumber(item?.price, 0));
      return {
        id: crypto.randomUUID(),
        name: cleanWooText(item?.title || item?.name) || "Product",
        quantity,
        unitPrice,
        lineTotal: roundLineMoney(unitPrice * quantity)
      };
    })
    .filter((i) => i.name);
}

function shopifyCustomerName(order) {
  const customer = order?.customer || {};
  const customerName = [customer.first_name, customer.last_name].map(cleanWooText).filter(Boolean).join(" ");
  if (customerName) return customerName;
  const billing = order?.billing_address || {};
  const billingName = cleanWooText(billing.name)
    || [billing.first_name, billing.last_name].map(cleanWooText).filter(Boolean).join(" ");
  return billingName || cleanWooText(billing.company) || "Shopify Customer";
}

function shopifyPhone(order) {
  return sanitizePhone(
    order?.phone ||
    order?.customer?.phone ||
    order?.billing_address?.phone ||
    order?.shipping_address?.phone ||
    ""
  );
}

// Normalize a Shopify address object into the shared parts shape (address1/zip/province).
function shopifyAddressParts(addr) {
  const a = addr || {};
  const street = [cleanWooText(a.address1), cleanWooText(a.address2)].filter(Boolean).join(", ");
  const name = cleanWooText(a.name)
    || [cleanWooText(a.first_name), cleanWooText(a.last_name)].filter(Boolean).join(" ");
  return {
    name: name || cleanWooText(a.company),
    street,
    city: cleanWooText(a.city),
    state: cleanWooText(a.province),
    postalCode: cleanWooText(a.zip),
    country: cleanWooText(a.country),
    phone: sanitizePhone(a.phone)
  };
}

function shopifyPaymentMethod(order) {
  const gateways = Array.isArray(order?.payment_gateway_names)
    ? order.payment_gateway_names.map(cleanWooText).filter(Boolean)
    : [];
  // The actual gateway(s) the customer used; empty when none, rather than "Shopify".
  return cleanWooText(gateways.join(", ") || order?.gateway || "");
}

function shopifyShippingCost(order) {
  const fromSet = order?.total_shipping_price_set?.shop_money?.amount;
  if (fromSet !== undefined && fromSet !== null) return wooNumber(fromSet, 0);
  const lines = Array.isArray(order?.shipping_lines) ? order.shipping_lines : [];
  return lines.reduce((sum, line) => sum + wooNumber(line?.price, 0), 0);
}

function mapShopifyOrderToSiparis(order, companyId, isNew = true) {
  const now = new Date();
  const shopifyId = cleanWooText(order?.id || order?.order_number || crypto.randomUUID());
  const orderNumber = cleanWooText(order?.name || order?.order_number || order?.number || shopifyId);
  const financialStatus = cleanWooText(order?.financial_status || "new");
  const total = wooNumber(order?.total_price, 0);
  const createdAt = wooDate(order?.created_at || order?.processed_at, now);
  const lineSummary = shopifyLineItemsSummary(order);
  const firstItem = shopifyLineItems(order)[0] || {};
  // Structured invoice line items (real per-product prices), reconciled to total_price.
  const lineItems = reconcileLineItems(shopifyStructuredLineItems(order), total);
  const designName = cleanWooText(lineSummary || firstItem?.title || firstItem?.name || `Shopify ${orderNumber}`);
  const watchRef = cleanWooText(firstItem?.sku || "");
  const paymentMethod = shopifyPaymentMethod(order);
  const customerNote = cleanWooText(order?.note || "");
  const email = cleanWooText(order?.email || order?.customer?.email || order?.contact_email || "");
  const phone = shopifyPhone(order);

  // Billing goes to the customer record; shipping is per-order (can differ).
  // Shopify omits shipping_address for digital/no-ship orders, so fall back to billing.
  const billingParts = shopifyAddressParts(order?.billing_address);
  const rawShipping = shopifyAddressParts(order?.shipping_address);
  const shippingHasAddress = Boolean(rawShipping.street || rawShipping.city || rawShipping.postalCode);
  const shippingParts = shippingHasAddress ? rawShipping : billingParts;

  const customFields = {
    Source: "Shopify",
    "Shopify Order ID": shopifyId,
    "Shopify Order Number": orderNumber,
    "Shopify Status": financialStatus,
    "Shopify Payment Method": paymentMethod,
    "Shopify Currency": cleanWooText(order?.currency || ""),
    "Shopify Total": cleanWooText(order?.total_price || ""),
    "Shopify Created At": cleanWooText(order?.created_at || ""),
    "Shopify Products": lineSummary,
    // Billing address on the order so the invoice's Billing Address block is populated.
    communicationAddress: formatAddressParts(billingParts)
  };

  const mapped = {
    companyId,
    paymentMethod,
    customerName: shopifyCustomerName(order),
    paymentDate: createdAt,
    paidAmount: total,
    remainingAmount: 0,
    watchPurchasePrice: 0,
    watchRef,
    deliveryTime: 45,
    designName,
    lineItems,
    designLink: cleanWooText(order?.order_status_url || ""),
    communication: ["Shopify"],
    emailAddress: email,
    instagramUsername: "",
    whatsappNumber: phone,
    notes: customerNote,
    shippingName: shippingParts.name || shopifyCustomerName(order),
    shippingStreetAddress: shippingParts.street,
    shippingCity: shippingParts.city,
    shippingPostalCode: shippingParts.postalCode,
    shippingCountry: shippingParts.country,
    shippingPhone: shippingParts.phone || phone,
    designStatus: "Not Yet",
    status: "Not Yet",
    isDispatched: false,
    trackingNumber: "",
    courier: "Auto Detect",
    isDelivered: false,
    paymentFee: 0,
    deliveryCost: shopifyShippingCost(order),
    taxType: "",
    extraStatuses: {},
    taxRate: 0,
    invBool1: false,
    invBool2: false,
    invBool3: false,
    invBool4: false,
    invNotes: "",
    taxAmount: wooNumber(order?.total_tax, 0),
    priority: "Normal",
    risk: "None",
    riskReason: "-",
    customFields,
    customToggles: {},
    clientFiles: [],
    todoItems: [],
    workSessions: [],
    assignedToUid: "",
    assignedToEmail: ""
  };

  if (isNew) {
    mapped.historyLog = [{
      id: crypto.randomUUID(),
      createdAt: now,
      title: "Order created",
      oldValue: "Shopify",
      newValue: `${orderNumber}`
    }];
    const seededPayments = seedInitialPayment(total, createdAt, paymentMethod);
    if (seededPayments.length) mapped.payments = seededPayments;
  }

  return mapped;
}

function shopifyDeliveryUrl(companyId, token) {
  return "https://europe-west2-eggcraft-studio.cloudfunctions.net/shopifyOrderWebhook"
    + `?companyId=${encodeURIComponent(companyId)}&token=${encodeURIComponent(token)}`;
}

// Owner-only: returns this workspace's Shopify webhook token + full Delivery URL,
// minting a per-workspace token on first use (isolated, unguessable per workspace).
exports.getShopifyWebhookToken = onCall({ region: "europe-west2" }, async (request) => {
  const { companyId } = await requireWorkspaceForBilling(request, true);
  // The raw token is deliberately not returned any more: the delivery URL is the
  // only thing a client needs, and nothing ever read the bare token.
  let { token, data } = await readIntegrationSecret(companyId, "shopify");
  if (!token) {
    token = await mintIntegrationToken(companyId, "shopify");
    data = { createdAt: admin.firestore.Timestamp.now() };
  }
  return {
    ok: true,
    companyId,
    deliveryUrl: shopifyDeliveryUrl(companyId, token),
    ...integrationStatusPayload(data)
  };
});

exports.shopifyOrderWebhook = onRequest({ region: "europe-west2" }, async (req, res) => {
  try {
    if (req.method !== "POST") {
      res.status(200).json({
        ok: true,
        message: "Shopify webhook endpoint is alive. Use POST from Shopify.",
        requiredQuery: "companyId"
      });
      return;
    }

    const order = req.body || {};
    const companyId = shopifyCompanyId(req, order);
    if (!companyId) {
      res.status(400).json({
        ok: false,
        error: "Missing companyId. Add ?companyId=YOUR_COMPANY_ID to the webhook Delivery URL."
      });
      return;
    }

    // Authentication. Primary: a per-workspace token (shopifyWebhookToken on the company
    // doc, shown in the app's Shopify integration screen). Optional fallback: Shopify's
    // HMAC signature (X-Shopify-Hmac-Sha256) verified against a configured global secret.
    // Each workspace's token is isolated, so one workspace's URL cannot forge orders into
    // another. Backward compatible: if neither exists, the request is allowed with a warning.
    const providedToken = String(req.query?.token || req.headers["x-studioflow-token"] || "");
    const companyAuthRef = admin.firestore().collection("companies").doc(companyId);
    const companyAuthSnap = await companyAuthRef.get();
    if (!companyAuthSnap.exists) {
      res.status(404).json({ ok: false, error: "unknown_company" });
      return;
    }
    const { token: workspaceToken } = await readIntegrationSecret(companyId, "shopify");
    // Same dead platform-wide-secret branch as WooCommerce, deleted for the same
    // reason. The official Shopify app path (shopifyAppWebhook) does verify an
    // HMAC, against a real mounted secret — that one stays.
    let authed = false;
    if (workspaceToken && nvTimingSafeEqual(providedToken, workspaceToken)) {
      authed = true;
    }
    if (!authed) {
      const reason = workspaceToken ? "invalid token" : "no token in the delivery URL";
      console.warn(`shopifyOrderWebhook: rejected request — ${reason}.`);
      await recordIntegrationDelivery(companyId, "shopify", { ok: false, error: reason, source: integrationRequestSource(req) });
      res.status(401).json({ ok: false, error: "unauthorized" });
      return;
    }

    // Settings report: the app used to merely ADVISE against running the
    // official app and the manual webhook side by side; now the server
    // enforces it. While any official store connection is ACTIVE for this
    // workspace, manual deliveries are refused with an explanation instead of
    // silently double-importing the same orders. Pausing or removing the
    // official connection reopens this path.
    const officialSnap = await admin.firestore().collection("shopifyStores")
      .where("companyId", "==", companyId).limit(5).get();
    const activeOfficial = officialSnap.docs.find(doc => String((doc.data() || {}).status || "") === "active");
    if (activeOfficial) {
      const message = `The official Shopify app is connected for ${activeOfficial.id}; the manual webhook is disabled to prevent duplicate orders. Pause or remove the official connection to use it.`;
      await recordIntegrationDelivery(companyId, "shopify", { ok: false, error: "official_app_active", source: integrationRequestSource(req) });
      res.status(409).json({ ok: false, error: "official_app_active", message });
      return;
    }
    // A deliberate test press answers like the inbound endpoint: authenticated,
    // recorded as a test, no order created — so the green it paints is honest.
    if (req.body && (req.body.nivadeskTest === true || req.body.test === true)) {
      await recordIntegrationDelivery(companyId, "shopify", { ok: true, test: true, source: integrationRequestSource(req) });
      res.status(200).json({ ok: true, test: true, orderCreated: false });
      return;
    }
    // Recorded here rather than after the order is written: a verification ping
    // that carries no order is still a delivery that arrived and authenticated,
    // which is exactly what "is this connected?" is asking.
    await recordIntegrationDelivery(companyId, "shopify", { ok: true, source: integrationRequestSource(req), orderId: cleanWooText(order?.id || order?.order_number || order?.name) });

    const shopifyOrderId = cleanWooText(order?.id || order?.order_number || order?.name);
    if (!shopifyOrderId) {
      // Acknowledge non-order payloads (e.g. a webhook verification ping) with 200 so
      // Shopify does not count them as failed deliveries and remove the webhook.
      res.status(200).json({ ok: true, ignored: "no_order_id" });
      return;
    }

    const docId = shopifyOrderDocId(companyId, shopifyOrderId);
    const ref = orderDocRef(docId);
    const existing = await ref.get();

    // Only create a NEW app order for Shopify orders whose payment has actually been
    // received (financial_status paid / partially_paid / partially_refunded). Everything
    // else (pending, authorized, refunded, voided) is ignored on creation. Existing orders
    // are still updated, so later status changes are reflected in the app.
    const financialStatus = String(order?.financial_status || "").trim().toLowerCase();
    const SHOPIFY_PAID_STATUSES = new Set(["paid", "partially_paid", "partially_refunded"]);
    if (!existing.exists && !SHOPIFY_PAID_STATUSES.has(financialStatus)) {
      res.status(200).json({ ok: true, ignored: "unpaid_status", status: financialStatus, orderId: docId });
      return;
    }

    const mappedOrder = mapShopifyOrderToSiparis(order, companyId, !existing.exists);
    await ref.set(integrationOrderUpdate(mappedOrder, !existing.exists), { merge: true });

    // Mirror the billing contact into the workspace's customer list (address,
    // phone, email). Best-effort: never block the order webhook on this.
    try {
      const billing = shopifyAddressParts(order?.billing_address);
      const rawShip = shopifyAddressParts(order?.shipping_address);
      const shipping = (rawShip.street || rawShip.city || rawShip.postalCode) ? rawShip : billing;
      await upsertIntegrationCustomer(companyId, {
        name: mappedOrder.customerName,
        externalCustomerId: order?.customer?.id ? String(order.customer.id) : "",
        email: mappedOrder.emailAddress,
        phone: mappedOrder.whatsappNumber,
        address: formatAddressParts(billing),
        streetAddress: billing.street,
        city: billing.city,
        postalCode: billing.postalCode,
        country: billing.country,
        shippingAddress: formatAddressParts(shipping),
        shippingStreetAddress: shipping.street,
        shippingCity: shipping.city,
        shippingPostalCode: shipping.postalCode,
        shippingCountry: shipping.country,
        shippingPhone: shipping.phone || mappedOrder.whatsappNumber
      }, "shopify");
    } catch (error) {
      console.warn("Shopify customer upsert failed:", error?.message || error);
    }

    await sendPushNotificationToCompany(companyId, {
      title: "New Shopify order",
      body: `${mappedOrder.customerName}: ${mappedOrder.designName}`,
      orderId: docId,
      type: "shopify_order"
    });

    res.status(200).json({
      ok: true,
      created: !existing.exists,
      orderId: docId,
      companyId
    });
  } catch (error) {
    console.error("shopifyOrderWebhook error:", error);
    res.status(500).json({ ok: false, error: error.message || String(error) });
  }
});


// ---------------------------------------------------------------------------
// Generic inbound order webhook.
//
// A platform-agnostic endpoint that accepts a NORMALISED order JSON, so any
// store / site / automation tool (Zapier, Make, n8n, Wix, Squarespace, Etsy,
// BigCommerce, custom sites, ...) can push orders into the workspace without a
// platform-specific mapper. Same per-workspace token model as the WooCommerce /
// Shopify webhooks (token REQUIRED here — no legacy allow-if-unset branch). Reuses
// only the generic utilities; touches no existing function.
// ---------------------------------------------------------------------------

function inboundValue(payload, keys, fallback = "") {
  for (const key of keys) {
    const raw = payload?.[key];
    if (raw !== undefined && raw !== null && String(raw).trim() !== "") return raw;
  }
  return fallback;
}

function inboundCompanyId(req, payload) {
  return cleanWooText(
    req.query?.companyId ||
    req.query?.company_id ||
    req.headers?.["x-studioflow-company-id"] ||
    inboundValue(payload, ["companyId", "company_id", "studioflow_company_id"])
  );
}

function inboundOrderDocId(companyId, externalId) {
  return `inbound_${wooSafeDocPart(companyId)}_${wooSafeDocPart(externalId)}`;
}

function inboundProductsSummary(payload) {
  const products = inboundValue(payload, ["products", "items", "lineItems", "line_items", "productNames"]);
  if (Array.isArray(products)) {
    return products
      .map((item) => {
        if (typeof item === "string") return cleanWooText(item);
        const name = cleanWooText(item?.name || item?.title || item?.product || "");
        const qty = item?.quantity ? ` x${item.quantity}` : "";
        return name ? `${name}${qty}` : "";
      })
      .filter(Boolean)
      .join(", ");
  }
  return cleanWooText(products);
}

// Structured invoice line items from a generic inbound payload. Only builds items when the
// sender provided per-line prices; otherwise returns [] so the single designName line is used.
// Schema matches every client's LineItem: { id, name, quantity, unitPrice, lineTotal }.
function inboundStructuredLineItems(payload) {
  const products = inboundValue(payload, ["products", "items", "lineItems", "line_items"]);
  if (!Array.isArray(products)) return [];
  return products
    .map((item) => {
      if (!item || typeof item !== "object") return null;
      const name = cleanWooText(item.name || item.title || item.product || "");
      if (!name) return null;
      const quantity = Math.max(1, wooNumber(item.quantity ?? item.qty, 1));
      const unitRaw = item.unitPrice ?? item.price ?? item.unit_price;
      const totalRaw = item.total ?? item.lineTotal ?? item.amount;
      const lineTotal = totalRaw != null
        ? roundLineMoney(wooNumber(totalRaw, 0))
        : roundLineMoney(wooNumber(unitRaw, 0) * quantity);
      const unitPrice = unitRaw != null
        ? roundLineMoney(wooNumber(unitRaw, 0))
        : roundLineMoney(lineTotal / quantity);
      return { id: crypto.randomUUID(), name, quantity, unitPrice, lineTotal };
    })
    .filter(Boolean);
}

// Normalize a (possibly nested) address object from a generic inbound payload into the
// shared parts shape. Accepts many common key spellings since the sender is user-configured.
function inboundAddressParts(addr) {
  const a = addr && typeof addr === "object" ? addr : {};
  const street = [
    cleanWooText(a.street || a.address1 || a.address_1 || a.line1 || a.address),
    cleanWooText(a.street2 || a.address2 || a.address_2 || a.line2)
  ].filter(Boolean).join(", ");
  const name = cleanWooText(a.name)
    || [cleanWooText(a.firstName || a.first_name), cleanWooText(a.lastName || a.last_name)].filter(Boolean).join(" ");
  return {
    name: name || cleanWooText(a.company),
    street,
    city: cleanWooText(a.city || a.town),
    state: cleanWooText(a.state || a.province || a.region),
    postalCode: cleanWooText(a.postalCode || a.postcode || a.zip || a.zipCode || a.postal_code),
    country: cleanWooText(a.country || a.countryCode),
    phone: sanitizePhone(a.phone || a.telephone || a.mobile)
  };
}

function mapGenericInboundOrderToSiparis(payload, companyId, isNew = true) {
  const now = new Date();
  const externalId = cleanWooText(inboundValue(payload, ["orderId", "id", "order_id", "orderNumber", "number"]) || crypto.randomUUID());
  const orderNumber = cleanWooText(inboundValue(payload, ["orderNumber", "number", "order_number", "orderId", "id"]) || externalId);
  const rawTotal = inboundValue(payload, ["total", "amount", "total_price", "totalPrice", "grandTotal"]);
  const parsedTotal = inboundMoneyNumber(rawTotal);
  const total = parsedTotal ?? 0;
  const createdAt = wooDate(inboundValue(payload, ["createdAt", "created_at", "date", "orderDate"]), now);
  const productsSummary = inboundProductsSummary(payload);
  // Structured invoice line items — only when the sender supplied per-line prices; otherwise []
  // so the single designName line is used. Reconciled to the order total when present.
  const inboundItems = inboundStructuredLineItems(payload);
  const lineItems = inboundItems.some((i) => i.lineTotal > 0.005) ? reconcileLineItems(inboundItems, total) : [];
  const designName = cleanWooText(inboundValue(payload, ["designName", "design_name", "title"]) || productsSummary || `Order ${orderNumber}`);
  const customerName = cleanWooText(inboundValue(payload, ["customerName", "customer_name", "name", "fullName", "buyerName"]) || "Website Customer");
  const sourceLabel = cleanWooText(inboundValue(payload, ["source", "platform", "store"]) || "Website");
  // The actual payment method the customer used; empty when none, rather than the source name.
  const paymentMethod = cleanWooText(inboundValue(payload, ["paymentMethod", "payment_method", "gateway"]) || "");
  const email = cleanWooText(inboundValue(payload, ["email", "customerEmail", "buyerEmail"]));
  const phone = sanitizePhone(inboundValue(payload, ["phone", "telephone", "whatsapp", "mobile"]));
  const note = cleanWooText(inboundValue(payload, ["note", "notes", "customerNote", "message"]));
  const status = cleanWooText(inboundValue(payload, ["status", "financial_status", "paymentStatus"]));

  // Billing goes to the customer record; shipping is per-order (can differ). Address can
  // arrive as a nested object or as flat top-level fields, so support both shapes.
  const rawBilling = inboundValue(payload, ["billing", "billingAddress", "billing_address", "address"]);
  const billingParts = inboundAddressParts(rawBilling && typeof rawBilling === "object" ? rawBilling : payload);
  const rawShipping = inboundValue(payload, ["shipping", "shippingAddress", "shipping_address"]);
  const shippingPartsRaw = inboundAddressParts(rawShipping);
  const shippingHasAddress = Boolean(shippingPartsRaw.street || shippingPartsRaw.city || shippingPartsRaw.postalCode);
  const shippingParts = shippingHasAddress ? shippingPartsRaw : billingParts;

  const customFields = {
    Source: sourceLabel,
    "Order ID": externalId,
    "Order Number": orderNumber,
    "Status": status,
    "Payment Method": paymentMethod,
    "Currency": cleanWooText(inboundValue(payload, ["currency"])),
    "Total": String(total),
    "Products": productsSummary,
    // Billing address on the order so the invoice's Billing Address block is populated.
    communicationAddress: formatAddressParts(billingParts)
  };

  const mapped = {
    companyId,
    paymentMethod,
    customerName,
    paymentDate: createdAt,
    paidAmount: total,
    remainingAmount: 0,
    watchPurchasePrice: 0,
    watchRef: cleanWooText(inboundValue(payload, ["sku", "ref", "watchRef"])),
    deliveryTime: wooNumber(inboundValue(payload, ["deliveryTime", "delivery_days"]), 45),
    designName,
    lineItems,
    designLink: cleanWooText(inboundValue(payload, ["orderUrl", "url", "link", "permalink"])),
    communication: [sourceLabel],
    emailAddress: email,
    instagramUsername: cleanWooText(inboundValue(payload, ["instagram", "instagramUsername"])),
    whatsappNumber: phone,
    notes: note,
    shippingName: shippingParts.name || customerName,
    shippingStreetAddress: shippingParts.street,
    shippingCity: shippingParts.city,
    shippingPostalCode: shippingParts.postalCode,
    shippingCountry: shippingParts.country,
    shippingPhone: shippingParts.phone || phone,
    designStatus: "Not Yet",
    status: "Not Yet",
    isDispatched: false,
    trackingNumber: "",
    courier: "Auto Detect",
    isDelivered: false,
    paymentFee: 0,
    // "shipping" is also the shipping ADDRESS key, and it came first: a sender
    // that posts an address lost its shipping cost to Number({}) = NaN.
    deliveryCost: inboundMoneyNumber(inboundValue(payload, ["shippingCost", "shipping_total", "deliveryCost", "shipping"])) ?? 0,
    taxType: "",
    extraStatuses: {},
    taxRate: 0,
    invBool1: false,
    invBool2: false,
    invBool3: false,
    invBool4: false,
    invNotes: "",
    taxAmount: wooNumber(inboundValue(payload, ["tax", "total_tax", "taxAmount"]), 0),
    priority: "Normal",
    risk: "None",
    riskReason: "-",
    customFields,
    customToggles: {},
    clientFiles: [],
    todoItems: [],
    workSessions: [],
    assignedToUid: "",
    assignedToEmail: ""
  };

  if (isNew) {
    mapped.historyLog = [{
      id: crypto.randomUUID(),
      createdAt: now,
      title: "Order created",
      oldValue: sourceLabel,
      newValue: `${orderNumber}`
    }];
    const seededPayments = seedInitialPayment(total, createdAt, paymentMethod);
    if (seededPayments.length) mapped.payments = seededPayments;
  }

  return mapped;
}

function inboundDeliveryUrl(companyId, token) {
  return "https://europe-west2-eggcraft-studio.cloudfunctions.net/inboundOrderWebhook"
    + `?companyId=${encodeURIComponent(companyId)}&token=${encodeURIComponent(token)}`;
}

// Owner-only: returns this workspace's generic inbound webhook token + Delivery URL.
exports.getInboundWebhookToken = onCall({ region: "europe-west2" }, async (request) => {
  const { companyId } = await requireWorkspaceForBilling(request, true);
  // The raw token is deliberately not returned any more: the delivery URL is the
  // only thing a client needs, and nothing ever read the bare token.
  let { token, data } = await readIntegrationSecret(companyId, "inbound");
  if (!token) {
    token = await mintIntegrationToken(companyId, "inbound");
    data = { createdAt: admin.firestore.Timestamp.now() };
  }
  return {
    ok: true,
    companyId,
    deliveryUrl: inboundDeliveryUrl(companyId, token),
    ...integrationStatusPayload(data)
  };
});

exports.inboundOrderWebhook = onRequest({ region: "europe-west2" }, async (req, res) => {
  try {
    if (req.method !== "POST") {
      res.status(200).json({
        ok: true,
        message: "NivaDesk inbound order webhook is alive. POST a normalised order JSON with a valid token.",
        requiredQuery: "companyId, token",
        exampleBody: {
          orderId: "1001",
          orderNumber: "#1001",
          customerName: "Jane Doe",
          email: "jane@example.com",
          phone: "+44...",
          total: 120.5,
          currency: "GBP",
          status: "paid",
          products: "Custom dial x1",
          note: "Gift wrap",
          source: "Wix"
        }
      });
      return;
    }

    const payload = req.body && typeof req.body === "object" ? req.body : {};
    const companyId = inboundCompanyId(req, payload);
    if (!companyId) {
      res.status(400).json({ ok: false, error: "Missing companyId. Add ?companyId=YOUR_COMPANY_ID to the URL." });
      return;
    }

    // Token is REQUIRED here (unlike the legacy Woo/Shopify allow-if-unset branch).
    const providedToken = String(req.query?.token || req.headers["x-studioflow-token"] || "");
    const companyAuthRef = admin.firestore().collection("companies").doc(companyId);
    const companyAuthSnap = await companyAuthRef.get();
    if (!companyAuthSnap.exists) {
      res.status(404).json({ ok: false, error: "unknown_company" });
      return;
    }
    const { token: workspaceToken } = await readIntegrationSecret(companyId, "inbound");
    if (!workspaceToken || !nvTimingSafeEqual(providedToken, workspaceToken)) {
      await recordIntegrationDelivery(companyId, "inbound", {
        ok: false,
        error: workspaceToken ? "invalid token" : "no token in the delivery URL",
        source: integrationRequestSource(req)
      });
      console.warn("inboundOrderWebhook: rejected request with missing/invalid token.");
      res.status(401).json({ ok: false, error: "unauthorized" });
      return;
    }
    // A payload marked as a test proves the URL, the companyId, the token and the
    // round trip — and stops there. Placed AFTER the token check so the flag can
    // never be a way in, and BEFORE the order write so a test that happens to
    // carry an orderId still creates nothing.
    const isTestDelivery = payload?.nivadeskTest === true || payload?.test === true;
    if (isTestDelivery) {
      await recordIntegrationDelivery(companyId, "inbound", { ok: true, test: true, source: integrationRequestSource(req) });
      const preview = mapGenericInboundOrderToSiparis(payload, companyId, true);
      res.status(200).json({
        ok: true,
        test: true,
        orderCreated: false,
        schemaVersion: INBOUND_SCHEMA_VERSION,
        companyId,
        reads: {
          customerName: preview.customerName,
          designName: preview.designName,
          total: preview.paidAmount,
          lineItemCount: Array.isArray(preview.lineItems) ? preview.lineItems.length : 0,
          deliveryCost: preview.deliveryCost
        },
        warnings: inboundPayloadWarnings(payload)
      });
      return;
    }

    await recordIntegrationDelivery(companyId, "inbound", {
      ok: true,
      source: integrationRequestSource(req),
      orderId: cleanWooText(inboundValue(payload, ["orderId", "id", "order_id", "orderNumber", "number"]))
    });

    const externalId = cleanWooText(inboundValue(payload, ["orderId", "id", "order_id", "orderNumber", "number"]));
    if (!externalId) {
      // Woo and Shopify answer a verification ping with 200; this one used to 400,
      // so a sender testing its wiring saw a failure it could not act on.
      res.status(200).json({
        ok: true,
        ignored: "no_order_id",
        schemaVersion: INBOUND_SCHEMA_VERSION,
        message: "Reached the workspace and authenticated, but the payload carried no orderId so no order was created.",
        warnings: inboundPayloadWarnings(payload)
      });
      return;
    }

    const docId = inboundOrderDocId(companyId, externalId);
    const ref = orderDocRef(docId);
    const existing = await ref.get();

    // The source is user-configured (Zapier / their own site), so we trust what it
    // sends rather than gating on a specific paid status — we only skip orders that
    // are clearly cancelled/refunded on creation.
    const status = String(inboundValue(payload, ["status", "financial_status", "paymentStatus"]) || "").trim().toLowerCase();
    if (!existing.exists && REJECT_STATUSES.has(status)) {
      res.status(200).json({ ok: true, ignored: "rejected_status", status, orderId: docId });
      return;
    }

    const mappedOrder = mapGenericInboundOrderToSiparis(payload, companyId, !existing.exists);
    await ref.set(integrationOrderUpdate(mappedOrder, !existing.exists), { merge: true });

    // Mirror the billing contact into the workspace's customer list (best-effort).
    try {
      const rawBilling = inboundValue(payload, ["billing", "billingAddress", "billing_address", "address"]);
      const billing = inboundAddressParts(rawBilling && typeof rawBilling === "object" ? rawBilling : payload);
      const rawShipping = inboundValue(payload, ["shipping", "shippingAddress", "shipping_address"]);
      const shipParts = inboundAddressParts(rawShipping);
      const shipping = (shipParts.street || shipParts.city || shipParts.postalCode) ? shipParts : billing;
      const sourceTag = (cleanWooText(inboundValue(payload, ["source", "platform", "store"])) || "inbound").toLowerCase();
      await upsertIntegrationCustomer(companyId, {
        name: mappedOrder.customerName,
        externalCustomerId: cleanWooText(inboundValue(payload, ["customerId", "customer_id", "externalCustomerId"])),
        email: mappedOrder.emailAddress,
        phone: mappedOrder.whatsappNumber,
        address: formatAddressParts(billing),
        streetAddress: billing.street,
        city: billing.city,
        postalCode: billing.postalCode,
        country: billing.country,
        shippingAddress: formatAddressParts(shipping),
        shippingStreetAddress: shipping.street,
        shippingCity: shipping.city,
        shippingPostalCode: shipping.postalCode,
        shippingCountry: shipping.country,
        shippingPhone: shipping.phone || mappedOrder.whatsappNumber
      }, sourceTag);
    } catch (error) {
      console.warn("Inbound customer upsert failed:", error?.message || error);
    }

    await sendPushNotificationToCompany(companyId, {
      title: "New website order",
      body: `${mappedOrder.customerName}: ${mappedOrder.designName}`,
      orderId: docId,
      type: "inbound_order"
    });

    res.status(200).json({ ok: true, created: !existing.exists, orderId: docId, companyId });
  } catch (error) {
    console.error("inboundOrderWebhook error:", error);
    res.status(500).json({ ok: false, error: error.message || String(error) });
  }
});


exports.track17Webhook = onRequest({ region: "europe-west2" }, async (req, res) => {
  try {
    if (req.method !== "POST") {
      res.status(200).json({ ok: true, message: "Webhook endpoint is alive. Use POST for updates." });
      return;
    }

    // Authenticate with a shared token when configured. Backward compatible: if
    // TRACK17_WEBHOOK_TOKEN is unset the request is allowed (with a warning). Once set,
    // add ?token=<value> to the 17TRACK webhook URL; requests without it are rejected.
    const expectedToken = String(process.env.TRACK17_WEBHOOK_TOKEN || "").trim();
    if (expectedToken) {
      const provided = String(req.query?.token || req.headers["x-studioflow-token"] || "");
      if (!nvTimingSafeEqual(provided, expectedToken)) {
        console.warn("track17Webhook: rejected request with invalid token.");
        res.status(401).json({ ok: false, error: "invalid_token" });
        return;
      }
    } else {
      console.warn("track17Webhook: TRACK17_WEBHOOK_TOKEN not set — request not authenticated.");
    }

    const payload = req.body || {};
    const items = Array.isArray(payload?.data) ? payload.data : Array.isArray(payload) ? payload : [payload];

    let writeCount = 0;
    const deliveredToNotify = [];
    const batch = admin.firestore().batch();

    for (const item of items) {
      if (!item) continue;

      const eventData = item?.data || item;
      const trackingNumber = cleanTrackingNumber(
        eventData?.number ||
        eventData?.tracking_number ||
        eventData?.track_info?.tracking_number ||
        eventData?.track_info?.number ||
        eventData?.track?.number
      );

      if (!trackingNumber) continue;

      const lookupSnap = await lookupDocRef(trackingNumber).get();
      if (!lookupSnap.exists) continue;

      const { companyId, orderId } = lookupSnap.data();
      if (!companyId || !orderId) continue;

      const normalized = normalize17TrackPayload(eventData, {
        trackingNumber,
        carrierCode: eventData?.carrier
      });

      batch.set(providerDocRef(companyId, orderId), normalized, { merge: true });

      if (isDeliveredResult(normalized)) {
        batch.set(orderDocRef(orderId), {
          isDelivered: true,
          isDispatched: true,
          customFields: buildTrackingCustomFields(normalized)
        }, { merge: true });
        deliveredToNotify.push({ companyId, orderId, result: normalized, language: normalized.language || "English" });
      } else if (isMovingResult(normalized)) {
        batch.set(orderDocRef(orderId), {
          isDispatched: true,
          customFields: buildTrackingCustomFields(normalized)
        }, { merge: true });
      }

      writeCount += 1;
    }

    if (writeCount > 0) {
      await batch.commit();
    }

    for (const item of deliveredToNotify) {
      await writeDeliveryNotification(item.companyId, item.orderId, item.result, item.language);
    }

    res.status(200).json({
      ok: true,
      received: items.length,
      updated: writeCount
    });
  } catch (error) {
    console.error("track17Webhook error:", error);
    res.status(200).json({
      ok: false,
      error: error.message || String(error)
    });
  }
});


// MARK: - Workspace Messages

function messageThreadsRef(companyId) {
  return admin.firestore().collection("companies").doc(companyId).collection("messageThreads");
}

function cleanMessageText(value = "", maxLength = 5000) {
  return String(value || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim().slice(0, maxLength);
}

function messageMillis(value) {
  if (!value) return 0;
  if (typeof value.toMillis === "function") return value.toMillis();
  if (typeof value.toDate === "function") return value.toDate().getTime();
  const date = new Date(value);
  return Number.isFinite(date.getTime()) ? date.getTime() : 0;
}

function messageWorkspaceMemberEntries(companyData = {}) {
  const out = [];
  const seen = new Set();
  const add = (uid = "", email = "", name = "", photoURL = "") => {
    const cleanUid = String(uid || "").trim();
    const cleanEmail = String(email || "").trim().toLowerCase();
    const key = cleanUid || cleanEmail;
    if (!key || seen.has(key)) return;
    seen.add(key);
    out.push({
      uid: cleanUid,
      email: cleanEmail,
      name: cleanSupportText(name || email || uid || "Team member", 120),
      photoURL: cleanSupportPhotoURL(photoURL || "")
    });
  };

  add(companyData.ownerUid || companyData.companyId || "", companyData.ownerEmail || companyData.email || "", companyData.ownerDisplayName || companyData.ownerName || "Owner", companyData.ownerPhotoURL || "");

  const members = companyMembersMap(companyData);
  for (const [uid, entry] of Object.entries(members)) {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
      add(uid, "", "", "");
      continue;
    }
    add(
      uid,
      entry.email || entry.userEmail || "",
      entry.displayName || entry.name || entry.userName || "",
      entry.photoURL || entry.accountPhotoURL || entry.avatarURL || entry.profilePhotoURL || ""
    );
  }

  const memberRoles = companyMemberRolesMap(companyData);
  for (const uid of Object.keys(memberRoles)) add(uid, "", "", "");
  return out;
}

function messageThreadFromDoc(doc, currentUid = "") {
  const data = doc.data() || {};
  const readBy = data.readBy && typeof data.readBy === "object" && !Array.isArray(data.readBy) ? data.readBy : {};
  const lastMessageAt = messageMillis(data.lastMessageAt);
  const currentReadAt = messageMillis(readBy[currentUid]);
  const lastMessageByUid = String(data.lastMessageByUid || "");
  return {
    id: doc.id,
    companyId: String(data.companyId || ""),
    type: String(data.type || "team"),
    title: String(data.title || ""),
    memberUids: Array.isArray(data.memberUids) ? data.memberUids.map(String) : [],
    memberEmails: Array.isArray(data.memberEmails) ? data.memberEmails.map(String) : [],
    lastMessageText: String(data.lastMessageText || ""),
    lastMessageAtMillis: lastMessageAt,
    lastMessageByUid,
    lastMessageByName: String(data.lastMessageByName || ""),
    lastMessageByPhotoURL: String(data.lastMessageByPhotoURL || ""),
    readByMillis: Object.fromEntries(Object.entries(readBy).map(([uid, ts]) => [uid, messageMillis(ts)])),
    mutedUntilByMillis: Object.fromEntries(Object.entries(data.mutedUntilBy && typeof data.mutedUntilBy === "object" && !Array.isArray(data.mutedUntilBy) ? data.mutedUntilBy : {}).map(([uid, ts]) => [uid, messageMillis(ts)])),
    pinnedMessageIds: Array.isArray(data.pinnedMessageIds) ? data.pinnedMessageIds.map(String) : [],
    isUnread: Boolean(lastMessageAt > 0 && lastMessageAt > currentReadAt && lastMessageByUid !== currentUid)
  };
}

function messageFromDoc(doc, threadId = "") {
  const data = doc.data() || {};
  return {
    id: doc.id,
    threadId: String(data.threadId || threadId || ""),
    text: String(data.text || ""),
    senderUid: String(data.senderUid || ""),
    senderEmail: String(data.senderEmail || ""),
    senderName: String(data.senderName || ""),
    senderPhotoURL: String(data.senderPhotoURL || ""),
    createdAtMillis: messageMillis(data.createdAt),
    type: String(data.type || "text"),
    fileName: String(data.fileName || ""),
    fileURL: String(data.fileURL || ""),
    fileType: String(data.fileType || ""),
    fileSize: Number(data.fileSize || 0),
    deletedForEveryone: data.deletedForEveryone === true,
    deletedByUid: String(data.deletedByUid || ""),
    deletedAtMillis: messageMillis(data.deletedAt),
    pinned: data.pinned === true,
    pinnedByUid: String(data.pinnedByUid || ""),
    pinnedByName: String(data.pinnedByName || ""),
    pinnedAtMillis: messageMillis(data.pinnedAt),
    replyToMessageId: String(data.replyToMessageId || ""),
    replyToText: String(data.replyToText || ""),
    replyToSenderName: String(data.replyToSenderName || ""),
    replyToSenderUid: String(data.replyToSenderUid || ""),
    replyToFileName: String(data.replyToFileName || ""),
    replyToType: String(data.replyToType || ""),
    reactions: data.reactions && typeof data.reactions === "object" && !Array.isArray(data.reactions) ? data.reactions : {},
    mentionedUids: Array.isArray(data.mentionedUids) ? data.mentionedUids.map(String) : [],
    edited: data.edited === true,
    editedAtMillis: messageMillis(data.editedAt),
    editedByUid: String(data.editedByUid || "")
  };
}


const DEFAULT_MESSAGE_WORKSPACE_SETTINGS = Object.freeze({
  directMessagesEnabled: true,
  groupConversationsEnabled: true,
  attachmentsEnabled: true
});

function messageWorkspaceSettingsRef(companyId) {
  return admin.firestore().collection("companies").doc(companyId).collection("messageSettings").doc("general");
}

function cleanMessageWorkspaceSettings(value = {}) {
  const settings = { ...DEFAULT_MESSAGE_WORKSPACE_SETTINGS };
  if (!value || typeof value !== "object" || Array.isArray(value)) return settings;
  for (const key of Object.keys(settings)) {
    if (typeof value[key] === "boolean") settings[key] = value[key];
  }
  return settings;
}

async function loadMessageWorkspaceSettings(companyId) {
  try {
    const snap = await messageWorkspaceSettingsRef(companyId).get();
    return cleanMessageWorkspaceSettings(snap.data() || {});
  } catch (error) {
    console.warn("Could not read message workspace settings:", error?.message || error);
    return { ...DEFAULT_MESSAGE_WORKSPACE_SETTINGS };
  }
}

function canManageMessageWorkspaceSettings(companyData = {}, uid = "") {
  if (uidIsCompanyOwner(companyData, uid)) return true;
  const roleValue = workspaceMemberRoleValue(companyData, uid, "member");
  if (customRoleData(companyData, roleValue)) {
    return canFullyEditOrder(workspaceMemberRole(companyData, uid, "member"))
      && uidCanAccessWorkspaceArea(companyData, uid, "settingsMessageSettings");
  }
  return normalizeWorkspaceRole(workspaceMemberRole(companyData, uid, "member"), "member") === "admin";
}

exports.getMessageWorkspaceSettings = onCall({ region: "europe-west2" }, async (request) => {
  const uid = request.auth?.uid;
  if (!uid) throw new HttpsError("unauthenticated", "You must be signed in to read message settings.");
  const { companyId, companyData } = await requireWorkspaceForBilling(request, false);
  requireMessagesReadAccess(companyData, uid);
  const settings = await loadMessageWorkspaceSettings(companyId);
  return {
    ok: true,
    companyId,
    settings,
    canManage: canManageMessageWorkspaceSettings(companyData, uid)
  };
});

exports.setMessageWorkspaceSettings = onCall({ region: "europe-west2" }, async (request) => {
  const uid = request.auth?.uid;
  if (!uid) throw new HttpsError("unauthenticated", "You must be signed in to update message settings.");
  const { companyId, companyData } = await requireWorkspaceForBilling(request, false);
  requireMessagesWriteAccess(companyData, uid);
  if (!canManageMessageWorkspaceSettings(companyData, uid)) {
    throw new HttpsError("permission-denied", "Only the workspace owner or admins can update message settings.");
  }
  const settings = cleanMessageWorkspaceSettings(request.data || {});
  await messageWorkspaceSettingsRef(companyId).set({
    ...settings,
    companyId,
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedByUid: uid
  }, { merge: true });
  return { ok: true, companyId, settings };
});

async function ensureTeamMessageThread(companyId, companyData = {}) {
  const threadRef = messageThreadsRef(companyId).doc("team");
  const entries = messageWorkspaceMemberEntries(companyData);
  const memberUids = supportUniqueStrings(entries.map((item) => item.uid));
  const memberEmails = supportUniqueStrings(entries.map((item) => item.email)).map((item) => item.toLowerCase());

  await threadRef.set({
    companyId,
    type: "team",
    title: "Team Chat",
    memberUids,
    memberEmails,
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    createdAt: admin.firestore.FieldValue.serverTimestamp(),
    source: "messages",
    messageSchemaVersion: 1
  }, { merge: true });

  return threadRef;
}

async function requireMessageThreadAccess(companyId, threadId, uid, companyData = {}) {
  const threadRef = messageThreadsRef(companyId).doc(threadId);
  const threadSnap = await threadRef.get();
  if (!threadSnap.exists) {
    throw new HttpsError("not-found", "Message thread not found.");
  }

  const data = threadSnap.data() || {};
  const memberUids = Array.isArray(data.memberUids) ? data.memberUids.map(String) : [];
  if (!memberUids.includes(uid) && !uidIsCompanyOwner(companyData, uid)) {
    throw new HttpsError("permission-denied", "You do not have access to this conversation.");
  }
  return { threadRef, threadData: data };
}

async function messageSenderProfile(companyId, companyData, request) {
  const uid = request.auth?.uid || "";
  const email = supportUserEmail(request);
  const requestedPhotoURL = supportPhotoURLFromRequest(request);
  const photoURL = await supportPhotoURLForUser(companyId, companyData, uid, email, requestedPhotoURL);
  const name = cleanSupportText(request.auth?.token?.name || request.data?.userName || "", 120) ||
    supportNotificationSenderName({ createdByEmail: email, createdByName: "" }, "Team member");
  return { uid, email, name, photoURL };
}

exports.createMessageThread = onCall({ region: "europe-west2" }, async (request) => {
  const uid = request.auth?.uid;
  if (!uid) throw new HttpsError("unauthenticated", "You must be signed in to create a message thread.");

  const { companyId, companyData } = await requireWorkspaceForBilling(request, false);
  requireMessagesConversationCreateAccess(companyData, uid);
  const requestedType = String(request.data?.type || "team").trim().toLowerCase();
  const type = requestedType === "direct" || requestedType === "group" ? requestedType : "team";
  const messageSettings = await loadMessageWorkspaceSettings(companyId);

  if (type === "team") {
    await ensureTeamMessageThread(companyId, companyData);
    return { ok: true, threadId: "team" };
  }

  const sender = await messageSenderProfile(companyId, companyData, request);
  const members = messageWorkspaceMemberEntries(companyData);
  const memberByUid = new Map(members.map((entry) => [String(entry.uid || ""), entry]));

  if (type === "direct") {
    if (messageSettings.directMessagesEnabled !== true) {
      throw new HttpsError("failed-precondition", "Direct messages are disabled for this workspace.");
    }
    const otherUid = cleanSupportText(request.data?.memberUid || request.data?.otherUid || "", 160);
    if (!otherUid || otherUid === uid) throw new HttpsError("invalid-argument", "Please choose a team member.");
    if (!uidHasCompanyAccess(companyData, otherUid)) throw new HttpsError("permission-denied", "That user is not in this workspace.");

    const ids = [uid, otherUid].sort();
    const threadId = `direct_${ids[0]}_${ids[1]}`.replace(/[^A-Za-z0-9_-]/g, "_");
    const otherPhotoURL = await supportPhotoURLForUser(companyId, companyData, otherUid, "");
    const otherEntry = memberByUid.get(otherUid) || {};
    const otherEmail = cleanSupportText(otherEntry.email || "", 240).toLowerCase();
    const existingThreadRef = messageThreadsRef(companyId).doc(threadId);
    const existingThreadSnap = await existingThreadRef.get();
    if (existingThreadSnap.exists) return { ok: true, threadId };

    await existingThreadRef.set({
      companyId, type: "direct",
      title: cleanSupportText(otherEntry.name || otherEntry.email || "Direct message", 120),
      memberUids: ids,
      memberEmails: supportUniqueStrings([sender.email, otherEmail]).map((item) => item.toLowerCase()),
      participantPhotoURLs: { [uid]: sender.photoURL || "", [otherUid]: otherPhotoURL || otherEntry.photoURL || "" },
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      source: "messages", messageSchemaVersion: 1
    }, { merge: true });
    return { ok: true, threadId };
  }

  if (messageSettings.groupConversationsEnabled !== true) {
    throw new HttpsError("failed-precondition", "Group conversations are disabled for this workspace.");
  }
  const requestedMemberUids = Array.isArray(request.data?.memberUids)
    ? request.data.memberUids.map((item) => cleanSupportText(item, 160)).filter(Boolean) : [];
  const additionalUids = supportUniqueStrings(requestedMemberUids).filter((memberUid) => memberUid && memberUid !== uid);
  if (additionalUids.length === 0) throw new HttpsError("invalid-argument", "Please choose at least one team member.");
  for (const memberUid of additionalUids) {
    if (!uidHasCompanyAccess(companyData, memberUid)) throw new HttpsError("permission-denied", "Only workspace members can be added to a private group.");
  }
  const groupUids = supportUniqueStrings([uid, ...additionalUids]);
  const participantPhotoURLs = {};
  const groupEmails = [];
  for (const memberUid of groupUids) {
    const entry = memberByUid.get(memberUid) || {};
    const memberEmail = memberUid === uid ? sender.email : cleanSupportText(entry.email || "", 240).toLowerCase();
    if (memberEmail) groupEmails.push(memberEmail);
    participantPhotoURLs[memberUid] = memberUid === uid ? sender.photoURL || "" :
      await supportPhotoURLForUser(companyId, companyData, memberUid, memberEmail, entry.photoURL || "");
  }
  const groupTitle = cleanSupportText(request.data?.title || "Private group", 120) || "Private group";
  const threadRef = messageThreadsRef(companyId).doc();
  await threadRef.set({
    companyId, type: "group", title: groupTitle,
    memberUids: groupUids,
    memberEmails: supportUniqueStrings(groupEmails).map((item) => item.toLowerCase()),
    participantPhotoURLs,
    createdAt: admin.firestore.FieldValue.serverTimestamp(),
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    source: "messages", messageSchemaVersion: 1
  }, { merge: true });
  return { ok: true, threadId: threadRef.id };
});

