function nvMcpInitializeResult(requestedProtocolVersion) {
  const protocolVersion = NV_MCP_SUPPORTED_PROTOCOL_VERSIONS.includes(requestedProtocolVersion)
    ? requestedProtocolVersion
    : NV_MCP_DEFAULT_PROTOCOL_VERSION;
  return {
    protocolVersion,
    serverInfo: nvMcpServerInfo(),
    capabilities: {
      tools: {}
    },
    instructions: [
      "This MCP server connects ChatGPT to NivaDesk / StudioFlow workspace order and personal note actions.",
      "Always ask for confirmation before creating or changing important order data when user intent is ambiguous.",
      "Never reveal data from another workspace. Use the workspace selected during NivaDesk sign-in automatically; do not ask the user for companyId.",
      "Respect workspace roles: view-only and workflow-only users cannot create or update orders. Personal note tools only affect the connected user own Notes area; collaboration is not changed automatically."
    ].join("\n")
  };
}

function nvMcpProtectedResourceMetadata(req) {
  return nvOAuthProtectedResourceMetadata(req);
}

function nvMcpProtectedResourceMetadataUrl() {
  return `${NV_CHATGPT_PUBLIC_BASE_URL}/.well-known/oauth-protected-resource`;
}

function nvSendMcpOAuthChallenge(res, message = "Authentication required.") {
  const metadataUrl = nvMcpProtectedResourceMetadataUrl();
  res.set(
    "WWW-Authenticate",
    `Bearer resource_metadata="${metadataUrl}", scope="orders.read notes.read finance.read"`
  );
  res.status(401).json(nvMcpJsonRpcError(null, -32001, message));
}

async function nvHandleMcpToolCall(req, params = {}) {
  const toolName = nvCleanString(params.name || "", 120);
  const args = params.arguments && typeof params.arguments === "object" && !Array.isArray(params.arguments)
    ? params.arguments
    : {};
  const companyId = nvCleanString(args.companyId || "", 160);

  if (!toolName) {
    throw new HttpsError("invalid-argument", "Tool name is required.");
  }

  const context = await nvRequireChatGPTWorkspaceAccessWithOAuth(req, companyId);
  return nvChatGPTDispatchAction(context, toolName, args);
}

async function nvHandleMcpRequest(req, body = {}) {
  const id = body.id === undefined ? null : body.id;
  const method = String(body.method || "").trim();
  const params = body.params && typeof body.params === "object" && !Array.isArray(body.params) ? body.params : {};

  // JSON-RPC notifications (e.g. notifications/initialized) expect NO response —
  // the Streamable HTTP transport wants HTTP 202 with an empty body. Returning a
  // JSON-RPC error here breaks strict clients during the post-initialize handshake.
  if (method.startsWith("notifications/")) {
    return null;
  }

  switch (method) {
    case "initialize":
      return nvMcpJsonRpcResult(id, nvMcpInitializeResult(nvCleanString(params.protocolVersion || "", 20)));

    case "ping":
      return nvMcpJsonRpcResult(id, {});

    case "tools/list":
      return nvMcpJsonRpcResult(id, { tools: nvMcpToolsWithSecuritySchemes() });

    case "tools/call": {
      const requestedToolName = nvCleanString(params.name || "", 120);
      try {
        const result = await nvHandleMcpToolCall(req, params);
        console.info("NivaDesk MCP tool result", JSON.stringify({
          tool: requestedToolName,
          ok: true,
          action: String(result?.action || requestedToolName)
        }));
        return nvMcpJsonRpcResult(id, nvMcpToolResult(result));
      } catch (error) {
        console.warn("NivaDesk MCP tool error", JSON.stringify({
          tool: requestedToolName,
          error: String(error?.code || "internal"),
          message: String(error?.message || "Tool call failed.").slice(0, 240)
        }));
        return nvMcpJsonRpcResult(id, nvMcpToolErrorResult(error));
      }
    }

    default:
      return nvMcpJsonRpcError(id, -32601, `Method not found: ${method || "(empty)"}`);
  }
}

exports.chatgptMcp = onRequest({ region: "europe-west2", cors: true, minInstances: 1, memory: "512MiB", timeoutSeconds: 60 }, async (req, res) => {
  if (nvChatCors(req, res)) return;

  if (req.method === "GET") {
    // MCP Streamable HTTP: a GET with `Accept: text/event-stream` is the client
    // asking to open a server->client SSE stream. This server is stateless and offers
    // no server-initiated stream, so per spec it MUST answer 405 Method Not Allowed.
    // Returning 200/JSON here makes strict MCP clients (the OpenAI Apps platform)
    // treat the transport as broken -> "Connection failed". Plain GETs (browser /
    // discovery) still receive the lightweight JSON below.
    const acceptHeader = String(req.headers["accept"] || "");
    if (acceptHeader.includes("text/event-stream")) {
      res.set("Allow", "POST, OPTIONS");
      res.status(405).json(
        nvMcpJsonRpcError(null, -32000, "This MCP endpoint does not provide a server-initiated SSE stream.")
      );
      return;
    }
    res.status(200).json({
      ok: true,
      name: "NivaDesk",
      serverInfo: nvMcpServerInfo(),
      protectedResource: nvMcpProtectedResourceMetadata(req),
      tools: nvMcpToolsWithSecuritySchemes().map((tool) => ({
        name: tool.name,
        title: tool.title,
        description: tool.description,
        annotations: tool.annotations,
        securitySchemes: tool.securitySchemes
      }))
    });
    return;
  }

  if (req.method !== "POST") {
    res.status(405).json({ ok: false, error: "method-not-allowed", message: "Use POST." });
    return;
  }

  // Allow MCP initialize and tools/list so ChatGPT can discover the app.
  // Protected tools enforce OAuth individually and return mcp/www_authenticate when linking is required.
  try {
    const body = req.body && typeof req.body === "object" ? req.body : {};
    const response = await nvHandleMcpRequest(req, body);
    if (response === null) {
      // Notification acknowledged — no JSON-RPC response body.
      res.status(202).end();
      return;
    }
    res.status(200).json(response);
  } catch (error) {
    const code = nvMcpErrorCodeFromHttps(error);
    const status = nvMcpHttpStatusFromHttps(error);
    const message = error?.message || String(error);
    console.error("chatgptMcp failed:", error?.code || code, message);
    if (status === 401) {
      nvSendMcpOAuthChallenge(res, message);
      return;
    }
    res.status(status).json(nvMcpJsonRpcError(null, code, message));
  }
});


exports.chatgptWorkspaceAction = onRequest({ region: "europe-west2", cors: true }, async (req, res) => {
  if (nvChatCors(req, res)) return;

  if (req.method !== "POST") {
    res.status(405).json({ ok: false, error: "method-not-allowed", message: "Use POST." });
    return;
  }

  try {
    const body = req.body && typeof req.body === "object" ? req.body : {};
    const companyId = nvCleanString(body.companyId || "", 160);
    const action = nvCleanString(body.action || "", 120);
    const args = body.arguments && typeof body.arguments === "object" && !Array.isArray(body.arguments) ? body.arguments : {};
    const context = await nvRequireChatGPTWorkspaceAccess(req, companyId);
    const result = await nvChatGPTDispatchAction(context, action, args);
    res.status(200).json(result);
  } catch (error) {
    const code = error?.code || "internal";
    const message = error?.message || String(error);
    const httpStatus =
      code === "unauthenticated" ? 401 :
      code === "permission-denied" ? 403 :
      code === "not-found" ? 404 :
      code === "invalid-argument" ? 400 : 500;

    console.error("chatgptWorkspaceAction failed:", code, message);
    res.status(httpStatus).json({ ok: false, error: code, message });
  }
});

// ----------------------------------------------------------------------------
// NivaDesk short file links (clean, branded viewer URLs)
//
// nvCreateFileLink: maps a raw Firebase Storage download URL to a short id stored
// in /fileShares. nvViewSharedFile resolves that short id and returns a tiny HTML
// viewer; the file bytes are loaded directly by the browser from Firebase Storage
// (they never pass through our server), while the address bar stays on nivadesk.app.
// ----------------------------------------------------------------------------

const NV_FILE_IMAGE_EXTS = new Set(["jpg", "jpeg", "png", "gif", "webp", "bmp", "svg", "heic", "heif", "avif"]);
const NV_FILE_PDF_EXTS = new Set(["pdf"]);
const NV_FILE_VIDEO_EXTS = new Set(["mp4", "mov", "webm", "m4v"]);
const NV_FILE_AUDIO_EXTS = new Set(["mp3", "wav", "m4a", "aac", "ogg"]);

function nvEscapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function nvFileErrorHtml(message) {
  return `<!doctype html><html><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1"/><title>NivaDesk</title><style>html,body{height:100%;margin:0}body{display:flex;align-items:center;justify-content:center;background:#0b0b0c;color:#e6e6e6;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}div{text-align:center;padding:24px}h1{font-size:18px;margin:0 0 6px}p{color:#9a9a9a;margin:0;font-size:13px}</style></head><body><div><h1>NivaDesk</h1><p>${nvEscapeHtml(message)}</p></div></body></html>`;
}

function nvFileViewerHtml(firebaseUrl, fileName, showBrand = true) {
  const ext = (fileName.includes(".") ? fileName.split(".").pop() : "").toLowerCase();
  const safeUrl = nvEscapeHtml(firebaseUrl);
  const safeName = nvEscapeHtml(fileName);
  let body;
  if (NV_FILE_IMAGE_EXTS.has(ext)) {
    body = `<img src="${safeUrl}" alt="${safeName}" />`;
  } else if (NV_FILE_PDF_EXTS.has(ext)) {
    body = `<iframe src="${safeUrl}" title="${safeName}"></iframe>`;
  } else if (NV_FILE_VIDEO_EXTS.has(ext)) {
    body = `<video src="${safeUrl}" controls autoplay playsinline></video>`;
  } else if (NV_FILE_AUDIO_EXTS.has(ext)) {
    body = `<div class="generic"><div class="filecard"><p class="name">${safeName}</p><audio src="${safeUrl}" controls></audio></div></div>`;
  } else {
    body = `<div class="generic"><div class="filecard"><p class="name">${safeName}</p><a class="dl" href="?dl=1">Download file</a></div></div>`;
  }
  const hasFab = NV_FILE_IMAGE_EXTS.has(ext) || NV_FILE_VIDEO_EXTS.has(ext) || NV_FILE_PDF_EXTS.has(ext);
  const fab = hasFab
    ? `<a class="dl-fab" href="?dl=1">Download</a>` : "";
  // Blob download keeps firebasestorage out of the address bar (needs bucket CORS
  // for nivadesk.app). If blocked, it falls back to the direct link.
  const script = "";
  return `<!doctype html>
<html><head>
<meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${safeName}${showBrand ? " · NivaDesk" : ""}</title>
<style>
html,body{height:100%;margin:0;background:#0b0b0c}
body{display:flex;align-items:center;justify-content:center;overflow:hidden}
img,video{max-width:100vw;max-height:100vh;object-fit:contain;display:block}
iframe{border:0;width:100vw;height:100vh;background:#1b1b1f}
.generic{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.filecard{text-align:center;color:#e6e6e6;padding:28px 32px;background:#161618;border:1px solid #2a2a2e;border-radius:16px}
.filecard .name{margin:0 0 14px;font-weight:700;font-size:15px;word-break:break-all}
.filecard .dl{display:inline-block;padding:10px 18px;border-radius:10px;background:#16a34a;color:#fff;text-decoration:none;font-weight:700;font-size:14px}
.dl-fab{position:fixed;right:16px;bottom:16px;padding:9px 14px;border-radius:999px;background:rgba(22,163,74,.92);color:#fff;text-decoration:none;font:600 13px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;box-shadow:0 6px 18px rgba(0,0,0,.35)}
</style></head><body>${body}${fab}${script}</body></html>`;
}

function nvParseFirebaseStorageUrl(rawUrl) {
  const parsed = new URL(rawUrl);
  if (parsed.hostname !== "firebasestorage.googleapis.com") return null;
  const match = parsed.pathname.match(/^\/v0\/b\/([^/]+)\/o\/(.+)$/);
  if (!match) return null;
  const bucket = decodeURIComponent(match[1]);
  const storagePath = decodeURIComponent(match[2]);
  const token = parsed.searchParams.get("token") || "";
  if (!bucket || !storagePath || !token) return null;
  return { bucket, storagePath, token };
}

exports.nvCreateFileLink = onCall({ region: "europe-west2" }, async (request) => {
  const uid = request.auth && request.auth.uid;
  if (!uid) throw new HttpsError("unauthenticated", "Sign in required.");
  const rawUrl = String((request.data && request.data.url) || "").trim();
  let info;
  try { info = nvParseFirebaseStorageUrl(rawUrl); } catch (_) { info = null; }
  if (!info) throw new HttpsError("invalid-argument", "Unsupported file URL.");
  const fileName = info.storagePath.split("/").pop() || "file";
  const ext = fileName.includes(".") ? fileName.split(".").pop().toLowerCase() : "";
  const shortId = crypto.createHash("sha256").update(info.storagePath).digest("base64url").slice(0, 12);
  await admin.firestore().collection("fileShares").doc(shortId).set({
    bucket: info.bucket,
    path: info.storagePath,
    token: info.token,
    fileName,
    ext,
    createdByUid: uid,
    updatedAt: admin.firestore.FieldValue.serverTimestamp()
  }, { merge: true });
  return { id: shortId, ext };
});

exports.nvViewSharedFile = onRequest({ region: "europe-west2" }, async (req, res) => {
  res.set("cache-control", "no-store, no-cache, max-age=0, must-revalidate");
  res.set("x-robots-tag", "noindex, nofollow");
  res.set("content-type", "text/html; charset=utf-8");
  const id = String(req.query.id || "").trim();
  if (!/^[A-Za-z0-9_-]{6,40}$/.test(id)) {
    res.status(400).send(nvFileErrorHtml("This file link is invalid."));
    return;
  }
  try {
    const doc = await admin.firestore().collection("fileShares").doc(id).get();
    if (!doc.exists) {
      res.status(404).send(nvFileErrorHtml("This file link has expired or does not exist."));
      return;
    }
    const data = doc.data() || {};
    if (!data.bucket || !data.path || !data.token) {
      res.status(404).send(nvFileErrorHtml("This file link has expired or does not exist."));
      return;
    }
    if (String(req.query.meta || "") === "1") {
      // The web /f/ route streams downloads itself; this hands it the target.
      res.set("content-type", "application/json");
      res.status(200).send(JSON.stringify({ ok: true, bucket: String(data.bucket), path: String(data.path), token: String(data.token), fileName: String(data.fileName || "file") }));
      return;
    }
    const firebaseUrl = `https://firebasestorage.googleapis.com/v0/b/${encodeURIComponent(data.bucket)}/o/${encodeURIComponent(data.path)}?alt=media&token=${encodeURIComponent(data.token)}`;
    res.status(200).send(nvFileViewerHtml(firebaseUrl, String(data.fileName || "file"), String(req.query.brand || "") !== "0"));
  } catch (error) {
    console.error("nvViewSharedFile failed:", error);
    res.status(500).send(nvFileErrorHtml("Could not load this file right now."));
  }
});

// Assigns a unique, sequential invoice number (YYYY-NNNN) to an order using a
// per-company counter in a transaction, so numbers never collide across devices

// ---------------------------------------------------------------------------
// Estimate → Approval → Signature
//
// A repair grows: "£280" becomes "£340 once we replace that claw". The customer
// has to agree to the new number, and months later somebody may have to show
// what exactly was agreed and when. So an estimate is a legal record, not a
// field on the order:
//
//   siparisler/{orderId}.estimates[]                 small index, for the card
//   siparisler/{orderId}/estimateRecords/{id}        the record itself
//   estimateLinks/{sha256(token)}                    the customer's link
//
// Subcollections under siparisler fall to the deny-all catch-all in
// firestore.rules, so a record can only ever be touched by the Admin SDK here.
// A revision never overwrites: the old estimate becomes "superseded" and keeps
// its own frozen line items and totals.
//
// Times in the index array are epoch milliseconds, not Timestamps, on purpose:
// FirebaseManager.firestoreArray decodes a whole array with `try?`, so a single
// element it cannot read blanks the field on Mac and iPhone alike.
// ---------------------------------------------------------------------------

const ESTIMATE_LINK_TTL_MS = 30 * 24 * 60 * 60 * 1000;
const ESTIMATE_VIEW_PER_HOUR = 60;
const ESTIMATE_VIEW_TOKEN_PER_HOUR = 120;
const ESTIMATE_DECIDE_PER_HOUR = 10;
const ESTIMATE_DECIDE_TOKEN_PER_HOUR = 5;
const ESTIMATE_MAX_LINE_ITEMS = 60;
const ESTIMATE_SIGNATURE_MAX_BYTES = 300 * 1024;

// ---------------------------------------------------------------------------
// Customer portal
//
// A sessionless page the customer opens from a link the workspace sends them:
// where their item is, what was quoted, what is left to pay, and the photos the
// workspace chose to share. Same shape as the estimate link — the plaintext
// token is returned once and only its hash is stored, so a leaked database
// cannot be turned back into working links.
//
// What it must NEVER carry is as much of the design as what it does: internal
// notes, supplier names, cost prices, profit and team messages are not filtered
// out of a full order here, they are simply never read.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Messaging provider layer
//
// Nothing above this line knows what a Twilio is. Callers ask a provider to
// send a message and to explain a delivery callback; swapping to Bird or Telnyx
// means writing one more object down here, not touching a single call site.
//
// Deliberately built on the REST API rather than a vendor SDK: an SDK is a
// dependency that would leak vendor types into the layer meant to hide them.
// ---------------------------------------------------------------------------

const TWILIO_ACCOUNT_SID = defineSecret("TWILIO_ACCOUNT_SID");
const TWILIO_AUTH_TOKEN = defineSecret("TWILIO_AUTH_TOKEN");

// GSM-7 fits 160 characters in one segment, 153 per segment once concatenated.
// Anything outside the alphabet forces UCS-2: 70, then 67. Billing is per
// segment, so this is what a message actually costs, not its character count.
const GSM7_ALPHABET = new Set(
  ("@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !\"#¤%&'()*+,-./0123456789:;<=>?" +
   "¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà").split("")
);
const GSM7_EXTENDED = new Set("^{}\\[~]|€".split(""));

function smsSegmentCount(body = "") {
  const text = String(body || "");
  if (!text) return 0;
  let isGsm = true;
  let gsmLength = 0;
  for (const char of text) {
    if (GSM7_EXTENDED.has(char)) { gsmLength += 2; continue; }
    if (GSM7_ALPHABET.has(char)) { gsmLength += 1; continue; }
    isGsm = false;
    break;
  }
  if (isGsm) {
    if (gsmLength <= 160) return 1;
    return Math.ceil(gsmLength / 153);
  }
  const units = Array.from(text).length;
  if (units <= 70) return 1;
  return Math.ceil(units / 67);
}

// E.164 or nothing. A carrier will not tell you a number was malformed in a way
// worth acting on, so a bad number is refused here instead of billed.
function cleanE164Phone(value = "", defaultCallingCode = "44") {
  let raw = String(value || "").trim().replace(/[\s()\-.]/g, "");
  if (!raw) return "";
  if (raw.startsWith("00")) raw = `+${raw.slice(2)}`;
  if (raw.startsWith("0")) raw = `+${defaultCallingCode}${raw.slice(1)}`;
  if (!raw.startsWith("+")) raw = `+${raw}`;
  return /^\+[1-9]\d{7,14}$/.test(raw) ? raw : "";
}

const twilioMessagingProvider = {
  id: "twilio",
  displayName: "Twilio",

  isConfigured() {
    return Boolean(
      String(process.env.TWILIO_ACCOUNT_SID || "").trim() &&
      String(process.env.TWILIO_AUTH_TOKEN || "").trim()
    );
  },

  async sendSMS({ to, from, body, statusCallback }) {
    const sid = String(process.env.TWILIO_ACCOUNT_SID || "").trim();
    const token = String(process.env.TWILIO_AUTH_TOKEN || "").trim();
    if (!sid || !token) throw new Error("Twilio credentials are not configured.");

    const form = new URLSearchParams();
    form.set("To", to);
    form.set("From", from);
    form.set("Body", body);
    if (statusCallback) form.set("StatusCallback", statusCallback);

    const response = await fetch(
      `https://api.twilio.com/2010-04-01/Accounts/${encodeURIComponent(sid)}/Messages.json`,
      {
        method: "POST",
        headers: {
          Authorization: `Basic ${Buffer.from(`${sid}:${token}`).toString("base64")}`,
          "Content-Type": "application/x-www-form-urlencoded"
        },
        body: form.toString()
      }
    );
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      const detail = payload && payload.message ? String(payload.message) : `HTTP ${response.status}`;
      const error = new Error(detail);
      error.providerCode = payload && payload.code ? String(payload.code) : "";
      throw error;
    }
    return {
      providerId: String(payload.sid || ""),
      status: String(payload.status || "queued"),
      segments: Number(payload.num_segments) || smsSegmentCount(body),
      // Twilio returns price as null until the message is billed; the webhook
      // fills it in later rather than us guessing here.
      priceUsd: payload.price === null || payload.price === undefined ? null : Math.abs(Number(payload.price) || 0)
    };
  },

  // Twilio signs the callback with the full URL plus every POST parameter sorted
  // by key. An unsigned callback is an open endpoint anyone can use to mark
  // messages delivered, so this is not optional.
  verifyWebhook({ url, params, signature }) {
    const token = String(process.env.TWILIO_AUTH_TOKEN || "").trim();
    if (!token || !signature) return false;
    const sorted = Object.keys(params || {}).sort();
    let data = String(url || "");
    for (const key of sorted) data += key + String(params[key]);
    const expected = crypto.createHmac("sha1", token).update(Buffer.from(data, "utf-8")).digest("base64");
    const a = Buffer.from(expected);
    const b = Buffer.from(String(signature));
    return a.length === b.length && crypto.timingSafeEqual(a, b);
  },

  parseWebhook(params = {}) {
    const raw = String(params.MessageStatus || params.SmsStatus || "").toLowerCase();
    const status = ["queued", "sending", "sent", "delivered", "undelivered", "failed"].includes(raw)
      ? raw
      : "sent";
    return {
      providerId: String(params.MessageSid || params.SmsSid || ""),
      status,
      errorCode: String(params.ErrorCode || ""),
      priceUsd: params.Price === undefined || params.Price === null || params.Price === ""
        ? null
        : Math.abs(Number(params.Price) || 0)
    };
  }
};

const MESSAGING_PROVIDERS = { twilio: twilioMessagingProvider };

function activeMessagingProvider() {
  const wanted = String(process.env.NIVADESK_SMS_PROVIDER || "twilio").trim().toLowerCase();
  return MESSAGING_PROVIDERS[wanted] || twilioMessagingProvider;
}

function messageLogCollection() {
  return admin.firestore().collection("messageLog");
}

// Every message is written down before it is sent, so a crash between the two
// leaves a record that something was attempted rather than silence.
async function recordOutboundMessage(entry = {}) {
  const ref = messageLogCollection().doc();
  await ref.set({
    companyId: String(entry.companyId || ""),
    orderId: String(entry.orderId || ""),
    orderReference: String(entry.orderReference || ""),
    customerName: String(entry.customerName || ""),
    channel: "sms",
    trigger: String(entry.trigger || ""),
    toNumber: String(entry.toNumber || ""),
    senderId: String(entry.senderId || ""),
    body: String(entry.body || ""),
    provider: String(entry.provider || ""),
    providerId: String(entry.providerId || ""),
    status: String(entry.status || "queued"),
    errorCode: "",
    errorMessage: String(entry.errorMessage || ""),
    segments: Number(entry.segments) || 0,
    priceUsd: entry.priceUsd === null || entry.priceUsd === undefined ? null : Number(entry.priceUsd),
    createdAtMs: Date.now(),
    deliveredAtMs: 0
  });
  return ref;
}

// Rolled up per calendar month on the company document so a workspace can be
// shown what it has spent without reading every message it ever sent.
async function addSmsUsage(companyId, segments, priceUsd) {
  if (!companyId) return;
  const monthKey = new Date().toISOString().slice(0, 7);
  const ref = admin.firestore().collection("companies").doc(String(companyId));
  await admin.firestore().runTransaction(async (tx) => {
    const snap = await tx.get(ref);
    const data = snap.exists ? snap.data() || {} : {};
    const sameMonth = String(data.smsUsageMonth || "") === monthKey;
    tx.set(ref, {
      smsUsageMonth: monthKey,
      smsSegmentsThisMonth: (sameMonth ? Number(data.smsSegmentsThisMonth) || 0 : 0) + (Number(segments) || 0),
      smsSpendUsdThisMonth: (sameMonth ? Number(data.smsSpendUsdThisMonth) || 0 : 0) + (Number(priceUsd) || 0),
      smsMessagesThisMonth: (sameMonth ? Number(data.smsMessagesThisMonth) || 0 : 0) + 1
    }, { merge: true });
  }).catch(() => undefined);
}

function cleanSmsSenderId(value = "") {
  // Alphanumeric sender IDs are 11 characters, letters/digits/space only. The
  // carrier silently rejects anything else, so it is normalised here.
  return String(value || "").trim().replace(/[^A-Za-z0-9 ]/g, "").slice(0, 11).trim();
}

// Which events are worth a text is the workspace's call — a busy bench may want
// only "ready for collection", a quiet one may want all of them.
const SMS_TRIGGER_KEYS = ["estimateReady", "workStarted", "readyForCollection", "everyStatusChange"];

function cleanSmsTriggers(value) {
  const incoming = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const output = {};
  for (const key of SMS_TRIGGER_KEYS) {
    // The three milestones are on by default; telling a customer about every
    // internal step is a choice a business makes, not one made for them.
    const fallback = key !== "everyStatusChange";
    output[key] = typeof incoming[key] === "boolean" ? incoming[key] : fallback;
  }
  return output;
}

// One sender ID registered once, for the whole platform. A workspace can bring
// its own later — a customer trusts "EGGcraft" more than "NivaDesk" — but that
// needs its own aggregator registration, so until then everyone rides this one
// and the workspace's name goes in the body where the customer actually reads it.
const PLATFORM_SMS_SENDER_ID = String(process.env.NIVADESK_SMS_SENDER_ID || "NivaDesk").trim();

function workspaceSmsConfig(settings = {}) {
  const ownSenderId = cleanSmsSenderId(settings.smsSenderId);
  // Ofcom's July 2026 rules put KYC on the aggregator, and Twilio requires UK
  // sender-ID pre-registration. This mirrors that state; it is not a claim
  // NivaDesk makes on its own.
  const ownSenderStatus = ["unset", "pending", "verified"].includes(String(settings.smsSenderStatus || ""))
    ? String(settings.smsSenderStatus)
    : "unset";
  const usesOwnSender = Boolean(ownSenderId) && ownSenderStatus === "verified";
  return {
    senderId: usesOwnSender ? ownSenderId : PLATFORM_SMS_SENDER_ID,
    ownSenderId,
    usesOwnSender,
    senderStatus: ownSenderStatus,
    defaultCallingCode: String(settings.smsDefaultCallingCode || "44").replace(/\D/g, "") || "44",
    triggers: cleanSmsTriggers(settings.smsTriggers)
  };
}

// The one call site everything else uses. Refuses rather than half-sends: a
// message with no verified sender, no credentials or no plan is not attempted.
async function sendWorkspaceSMS({ companyData, settings, companyId, orderId, orderReference, customerName, toNumber, trigger, body }) {
  const provider = activeMessagingProvider();
  const entitlements = billingEntitlementsForCompany(companyData || {});
  if (entitlements.smsNotificationsEnabled !== true) {
    return { sent: false, reason: "plan" };
  }
  if (!provider.isConfigured()) return { sent: false, reason: "provider_not_configured" };

  const config = workspaceSmsConfig(settings || {});
  // Always resolves: an unregistered workspace falls back to the platform sender
  // rather than being refused, so SMS works on day one of a subscription.
  if (!config.senderId) return { sent: false, reason: "no_sender_id" };

  const to = cleanE164Phone(toNumber, config.defaultCallingCode);
  if (!to) return { sent: false, reason: "invalid_number" };

  const segments = smsSegmentCount(body);
  const logRef = await recordOutboundMessage({
    companyId, orderId, orderReference, customerName,
    trigger, toNumber: to, senderId: config.senderId, body,
    provider: provider.id, status: "queued", segments
  });

  try {
    const result = await provider.sendSMS({
      to,
      from: config.senderId,
      body,
      statusCallback: `https://europe-west2-eggcraft-studio.cloudfunctions.net/smsDeliveryWebhook`
    });
    await logRef.set({
      providerId: result.providerId,
      status: result.status,
      segments: result.segments || segments,
      priceUsd: result.priceUsd
    }, { merge: true });
    await addSmsUsage(companyId, result.segments || segments, result.priceUsd || 0);
    return { sent: true, providerId: result.providerId };
  } catch (error) {
    await logRef.set({
      status: "failed",
      errorMessage: String(error && error.message ? error.message : error),
      errorCode: String((error && error.providerCode) || "")
    }, { merge: true });
    return { sent: false, reason: "provider_error", error: String(error) };
  }
}

// Twilio posts here as a message moves. "Sent" is not "delivered": without this
// the log would claim success for messages a carrier silently dropped.
exports.smsDeliveryWebhook = onRequest(
  { region: "europe-west2", secrets: [TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN] },
  async (request, response) => {
    if (request.method !== "POST") {
      response.status(405).send("Method not allowed");
      return;
    }
    const provider = activeMessagingProvider();
    const params = request.body && typeof request.body === "object" ? request.body : {};
    const url = `https://${request.get("host")}${request.originalUrl}`;
    if (!provider.verifyWebhook({ url, params, signature: request.get("X-Twilio-Signature") })) {
      console.warn("smsDeliveryWebhook: rejected an unsigned or mis-signed callback");
      response.status(403).send("Invalid signature");
      return;
    }

    const update = provider.parseWebhook(params);
    if (!update.providerId) {
      response.status(200).send("");
      return;
    }
    const matches = await messageLogCollection()
      .where("providerId", "==", update.providerId)
      .limit(1)
      .get()
      .catch(() => null);
    if (matches && !matches.empty) {
      const doc = matches.docs[0];
      const patch = { status: update.status, errorCode: update.errorCode };
      if (update.status === "delivered") patch.deliveredAtMs = Date.now();
      if (update.priceUsd !== null) {
        patch.priceUsd = update.priceUsd;
        const already = Number((doc.data() || {}).priceUsd) || 0;
        const difference = update.priceUsd - already;
        if (Math.abs(difference) > 0.0000001) {
          await addSmsUsage(String((doc.data() || {}).companyId || ""), 0, difference);
        }
      }
      await doc.ref.set(patch, { merge: true });
    }
    response.status(200).send("");
  }
);

exports.getWorkspaceSmsSettings = onCall({ region: "europe-west2" }, async (request) => {
  const { companyId, companyData } = await requireWorkspaceForBilling(request, false);
  const settings = await portalWorkspaceSettings(companyId);
  const config = workspaceSmsConfig(settings);
  const entitlements = billingEntitlementsForCompany(companyData);
  const companySnap = await admin.firestore().collection("companies").doc(companyId).get();
  const company = companySnap.exists ? companySnap.data() || {} : {};
  const monthKey = new Date().toISOString().slice(0, 7);
  const sameMonth = String(company.smsUsageMonth || "") === monthKey;
  return {
    ok: true,
    senderId: config.senderId,
    senderStatus: config.senderStatus,
    defaultCallingCode: config.defaultCallingCode,
    triggers: config.triggers,
    available: entitlements.smsNotificationsEnabled === true,
    providerConfigured: activeMessagingProvider().isConfigured(),
    usage: {
      month: monthKey,
      messages: sameMonth ? Number(company.smsMessagesThisMonth) || 0 : 0,
      segments: sameMonth ? Number(company.smsSegmentsThisMonth) || 0 : 0,
      spendUsd: sameMonth ? Number(company.smsSpendUsdThisMonth) || 0 : 0
    }
  };
});

exports.saveWorkspaceSmsSettings = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyData } = await requireWorkspaceForBilling(request, false);
  if (!uidIsCompanyOwner(companyData, uid)) {
    throw new HttpsError("permission-denied", "Only the workspace owner can change SMS settings.");
  }
  const entitlements = billingEntitlementsForCompany(companyData);
  if (entitlements.smsNotificationsEnabled !== true) {
    throw new HttpsError("failed-precondition", "SMS notifications are available on NivaDesk Pro and above.");
  }

  const requestedSender = cleanSmsSenderId(request.data && request.data.senderId);
  const current = workspaceSmsConfig(await portalWorkspaceSettings(companyId));

  // A workspace cannot mark its own sender verified. Ofcom's July 2026 rules put
  // Know Your Customer on the aggregator, and Twilio requires UK sender IDs to
  // be pre-registered — so this state mirrors that process rather than asserting
  // anything itself. Changing the name drops it back to pending, because the
  // registration was for the old name.
  const senderStatus = requestedSender === current.senderId ? current.senderStatus : (requestedSender ? "pending" : "unset");

  const updates = {
    smsSenderId: requestedSender,
    smsSenderStatus: senderStatus,
    smsTriggers: cleanSmsTriggers(request.data && request.data.triggers),
    smsDefaultCallingCode: String((request.data && request.data.defaultCallingCode) || current.defaultCallingCode).replace(/\D/g, "").slice(0, 4) || "44",
    settingsUpdatedAt: admin.firestore.FieldValue.serverTimestamp()
  };
  updates.lastSettingsWriteByUid = uid;
  updates.lastSettingsWriteAtMs = Date.now();
  await companySettingsDocRef(companyId).set(updates, { merge: true });
  return { ok: true, senderId: requestedSender, senderStatus, triggers: updates.smsTriggers };
});

const PORTAL_VIEW_PER_HOUR = 240;
const PORTAL_VIEW_TOKEN_PER_HOUR = 120;

// The three moments worth a message. Anything else is noise to a customer who
// only wants to know whether to come in yet.
function portalStatusMessage(status = "", context = {}) {
  const raw = String(status || "").trim().toLowerCase();
  const item = context.itemName ? ` — ${context.itemName}` : "";
  if (/approval|approve|quote|estimate|teklif|onay/.test(raw)) {
    return {
      trigger: "estimateReady",
      subject: `Your estimate is ready${item}`,
      line: "Your estimate is ready. You can review and approve it from the link below.",
      sms: "Your repair estimate is ready."
    };
  }
  if (/ready|collect|pickup|pick up|complete|completed|hazır|hazir|teslim/.test(raw)) {
    return {
      trigger: "readyForCollection",
      subject: `Ready for collection${item}`,
      line: "Good news — your item is ready for collection.",
      // Plain ASCII on purpose: one em dash drops the whole message out of
      // GSM-7 into UCS-2, which halves the characters per segment and doubles
      // what the carrier charges for the same sentence.
      sms: "Good news, your item is ready for collection."
    };
  }
  if (/workshop|progress|working|repair|bench|atölye|atolye|üretim|uretim/.test(raw)) {
    return {
      trigger: "workStarted",
      subject: `We've started work${item}`,
      line: "We have started work on your item.",
      sms: "We have started work on your item."
    };
  }
  return null;
}

// Used only when a workspace has opted into hearing about every step rather than
// the three milestones. Plain and short on purpose: it shares one segment with
// the business name and the tracking link.
function portalGenericStatusMessage(status = "", context = {}) {
  const item = context.itemName ? ` \u2014 ${context.itemName}` : "";
  const clean = String(status || "").trim();
  return {
    trigger: "everyStatusChange",
    subject: `Update on your order${item}`,
    line: `Your order is now at this stage: ${clean}.`,
    sms: `Your order is now at this stage: ${clean}.`
  };
}

// Sent from the NivaDesk mailbox with the workspace as the visible sender name
// and its own address as reply-to, so a customer replying reaches the business
// and not us. Best effort: the order write must never fail because mail did.
async function sendPortalStatusEmail({ toEmail, businessName, replyTo, subject, line, portalUrl, footerNote }) {
  const password = String(process.env.NIVADESK_SMTP_PASSWORD || "").trim();
  if (!password) {
    console.warn("sendPortalStatusEmail: NIVADESK_SMTP_PASSWORD is not set; skipping.");
    return false;
  }
  const host = String(process.env.NIVADESK_SMTP_HOST || "smtp.hostinger.com").trim();
  const port = Number(process.env.NIVADESK_SMTP_PORT || 465);
  const user = String(process.env.NIVADESK_SMTP_USER || NIVADESK_SUPPORT_INBOX).trim();

  const transporter = nodemailer.createTransport({
    host,
    port,
    secure: port === 465,
    auth: { user, pass: password }
  });

  const safeBusiness = String(businessName || "NivaDesk");
  const linkBlock = portalUrl ? `\n\nTrack your order: ${portalUrl}` : "";
  const text = `${line}${linkBlock}\n\n${safeBusiness}${footerNote ? `\n${footerNote}` : ""}`;
  const html = `<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;font-size:14px;color:#1c1c1e;">
    <p>${escapeHtmlForEmail(line)}</p>
    ${portalUrl ? `<p><a href="${escapeHtmlForEmail(portalUrl)}" style="display:inline-block;padding:10px 16px;background:#2563eb;color:#fff;border-radius:8px;text-decoration:none;font-weight:600;">Track your order</a></p>` : ""}
    <p style="color:#6b7280;">${escapeHtmlForEmail(safeBusiness)}</p>
    ${footerNote ? `<p style="color:#9ca3af;font-size:12px;white-space:pre-wrap;">${escapeHtmlForEmail(footerNote)}</p>` : ""}
  </div>`;

  await transporter.sendMail({
    from: `"${safeBusiness}" <${user}>`,
    replyTo: replyTo || undefined,
    to: toEmail,
    subject,
    text,
    html
  });
  return true;
}

function escapeHtmlForEmail(value = "") {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function portalLinksCollection() {
  return admin.firestore().collection("portalLinks");
}

function cleanPortalVisibility(value) {
  const incoming = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const flag = (key, fallback = true) => (typeof incoming[key] === "boolean" ? incoming[key] : fallback);
  return {
    status: flag("status"),
    estimate: flag("estimate"),
    payments: flag("payments"),
    photos: flag("photos"),
    expectedDate: flag("expectedDate")
  };
}

function cleanPortalAutoUpdates(value) {
  const incoming = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const flag = (key, fallback) => (typeof incoming[key] === "boolean" ? incoming[key] : fallback);
  return {
    enabled: flag("enabled", true),
    email: flag("email", true),
    // No SMS provider is connected. The preference is stored so the choice
    // survives, but nothing sends until one exists — see sendPortalStatusEmail.
    sms: flag("sms", false)
  };
}

async function portalWorkspaceSettings(companyId) {
  const snap = await companySettingsDocRef(String(companyId)).get();
  return snap.exists ? snap.data() || {} : {};
}

// The stages shown to the customer are the workspace's own order statuses, not a
// jeweller's. A tailor's board reads the same way to their customer as a
// watchmaker's does to theirs.
function portalStatusStages(settings = {}, orderData = {}) {
  const configured = parseStringArrayJSON(settings.activeStatusesJSON, []);
  const stages = (Array.isArray(configured) ? configured : [])
    .map((item) => cleanOrderText(item, "", 60))
    .filter(Boolean)
    .filter((item) => !["cancelled", "canceled"].includes(item.toLowerCase()));
  const list = stages.length > 0 ? stages : ["New", "In Progress", "Done"];
  const current = cleanOrderText(orderData.status, "", 60);
  const currentIndex = list.findIndex((item) => item.toLowerCase() === current.toLowerCase());
  return list.map((title, index) => ({
    title,
    state: currentIndex < 0
      ? (index === 0 ? "current" : "upcoming")
      : index < currentIndex ? "done" : index === currentIndex ? "current" : "upcoming"
  }));
}

function portalExpectedDateMs(orderData = {}) {
  const due = orderData.deliveryDueDate;
  if (due) {
    const parsed = due && typeof due.toDate === "function" ? due.toDate() : new Date(String(due));
    if (!Number.isNaN(parsed.getTime())) return parsed.getTime();
  }
  const placed = orderData.paymentDate && typeof orderData.paymentDate.toDate === "function"
    ? orderData.paymentDate.toDate()
    : null;
  const days = Number(orderData.deliveryTime) || 0;
  if (placed && days > 0) return placed.getTime() + days * 86400000;
  return 0;
}

// Built field by field from the order, never by removing things from it: a field
// added to orders later cannot leak here by default.
// Rebrands a raw Firebase Storage URL as a RELATIVE /f/ viewer link. Relative
// on purpose: the portal page hands it to the browser as-is, so the address
// bar keeps whichever host served the page — track.customer.com stays
// track.customer.com, never firebasestorage.googleapis.com. Non-Storage or
// unparseable URLs pass through untouched.
function maskedPortalFileUrl(rawUrl) {
  try {
    const url = new URL(String(rawUrl || ""));
    if (url.hostname !== "firebasestorage.googleapis.com") return String(rawUrl || "");
    const match = url.pathname.match(/^\/v0\/b\/([^/]+)\/o\/(.+)$/);
    if (!match) return String(rawUrl || "");
    const bucket = decodeURIComponent(match[1]);
    const storagePath = decodeURIComponent(match[2]);
    const token = url.searchParams.get("token");
    if (!token) return String(rawUrl || "");
    const segments = storagePath.split("/").map(encodeURIComponent).join("/");
    return `/f/${segments}?b=${encodeURIComponent(bucket)}&t=${encodeURIComponent(token)}`;
  } catch {
    return String(rawUrl || "");
  }
}

function portalPublicView(orderData = {}, settings = {}, link = {}) {
  const visibility = cleanPortalVisibility(orderData.portalVisibility);
  const currency = cleanFinancialCurrency(settings.seciliParaBirimi, "£");
  const view = {
    reference: cleanOrderText(orderData.invoiceNumber, "", 60) || cleanOrderText(link.orderId, "", 60),
    itemName: cleanOrderText(orderData.designName, "", 160) || cleanOrderText(orderData.watchRef, "", 160),
    customerFirstName: (cleanOrderText(orderData.customerName, "", 160).split(" ")[0] || ""),
    businessName: String(settings.appSubtitle || "NivaDesk"),
    logoUrl: String(settings.appLogoUrl || ""),
    footerNote: String(settings.invoiceFooterNote || ""),
    accentColor: /^#[0-9a-f]{6}$/i.test(String(settings.portalAccentColor || "")) ? String(settings.portalAccentColor).toLowerCase() : "",
    showPoweredBy: settings.portalShowPoweredBy !== false,
    currency,
    shows: visibility,
    stages: [],
    currentStatus: "",
    expectedDateMs: 0,
    estimate: null,
    payments: null,
    photos: []
  };

  if (visibility.status) {
    view.stages = portalStatusStages(settings, orderData);
    view.currentStatus = cleanOrderText(orderData.status, "", 60);
  }

  if (visibility.expectedDate) {
    view.expectedDateMs = portalExpectedDateMs(orderData);
  }

  if (visibility.estimate) {
    const rows = Array.isArray(orderData.estimates) ? orderData.estimates : [];
    const current = rows.find((row) => row && row.status !== "superseded") || rows[0] || null;
    if (current) {
      view.estimate = {
        number: cleanOrderText(current.number, "", 60),
        total: Number(current.total) || 0,
        status: cleanOrderText(current.status, "", 40)
      };
    }
  }

  if (visibility.payments) {
    const paid = Number(orderData.paidAmount) || 0;
    const remaining = Number(orderData.remainingAmount) || 0;
    view.payments = { paid, remaining, total: roundLineMoney(paid + remaining) };
  }

  if (visibility.photos) {
    const files = Array.isArray(orderData.clientFiles) ? orderData.clientFiles : [];
    view.photos = files
      .filter((file) => file && String(file.contentType || "").toLowerCase().startsWith("image"))
      .map((file) => String(file.downloadURL || ""))
      .filter(Boolean)
      .slice(0, 12);
  }

  return view;
}

async function portalLinkForVisitor(token) {
  const raw = String(token || "").trim();
  if (!raw || raw.length > 200) throw new HttpsError("invalid-argument", "A portal link is required.");
  const linkRef = portalLinksCollection().doc(nvSha256(raw));
  const linkSnap = await linkRef.get();
  if (!linkSnap.exists) throw new HttpsError("not-found", "This link is no longer available.");
  const link = linkSnap.data() || {};
  if (Number(link.revokedAtMs || 0) > 0) {
    throw new HttpsError("failed-precondition", "This link has been turned off by the business.");
  }
  const orderRef = orderDocRef(String(link.orderId || ""));
  const orderSnap = await orderRef.get();
  if (!orderSnap.exists) throw new HttpsError("not-found", "This link is no longer available.");
  const orderData = orderSnap.data() || {};
  if (orderData.isDeleted === true) {
    throw new HttpsError("failed-precondition", "This link is no longer available.");
  }
  if (String(orderData.portalTokenId || "") !== linkSnap.id) {
    throw new HttpsError("failed-precondition", "This link has been replaced by a newer one.");
  }
  return { linkRef, link, orderRef, orderData };
}

async function requirePortalStaff(request) {
  const context = await requireWorkspaceForBilling(request, false);
  requireWorkspaceAreaAccess(context.companyData, context.uid, "orders");
  const role = workspaceOrderRole(context.companyData, context.uid);
  if (!canFullyEditOrder(role)) {
    throw new HttpsError("permission-denied", "Your workspace role cannot change the customer portal.");
  }
  return context;
}

// The branded base for customer links: the workspace's verified custom domain
// first, then its claimed nivadesk.app subdomain, then the default host. Every
// one of these serves the pages — this only decides which name is handed out.
function clientPortalBaseUrlFromCompany(companyData) {
  const custom = String((companyData || {}).clientPortalCustomHost || "").trim().toLowerCase();
  if (custom) return `https://${custom}`;
  const slug = String((companyData || {}).clientPortalSlug || "").trim().toLowerCase();
  if (slug) return `https://${slug}.nivadesk.app`;
  return "https://nivadesk.app";
}

async function clientPortalBaseUrl(companyId) {
  try {
    const snap = await admin.firestore().collection("companies").doc(String(companyId)).get();
    return clientPortalBaseUrlFromCompany(snap.exists ? snap.data() || {} : {});
  } catch {
    return "https://nivadesk.app";
  }
}

exports.createOrderPortalLink = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, email, companyId } = await requirePortalStaff(request);
  const orderId = cleanOrderText(request.data && request.data.orderId, "", 200);
  if (!orderId) throw new HttpsError("invalid-argument", "orderId is required.");
  await websiteChatCheckRate("portalMint", uid, 60);

  const orderRef = orderDocRef(orderId);
  const token = nvRandomToken(24);
  const tokenId = nvSha256(token);
  const now = Date.now();

  await admin.firestore().runTransaction(async (tx) => {
    const orderSnap = await tx.get(orderRef);
    if (!orderSnap.exists) throw new HttpsError("not-found", "Order not found.");
    const orderData = orderSnap.data() || {};
    if (orderCompanyId(orderData) !== companyId) {
      throw new HttpsError("permission-denied", "This order does not belong to the active workspace.");
    }

    // Minting a new link retires the old one, so a link handed to the wrong
    // person stops working the moment a replacement is made.
    const previousId = String(orderData.portalTokenId || "");
    if (previousId && previousId !== tokenId) {
      tx.set(portalLinksCollection().doc(previousId), { revokedAtMs: now }, { merge: true });
    }

    tx.set(portalLinksCollection().doc(tokenId), {
      orderId,
      companyId,
      createdAtMs: now,
      createdByUid: uid,
      revokedAtMs: 0,
      viewCount: 0
    });

    const history = Array.isArray(orderData.historyLog) ? orderData.historyLog : [];
    tx.update(orderRef, {
      portalTokenId: tokenId,
      // The plaintext lives here, on the order — a document only workspace
      // members can read — so Copy Link keeps working without minting a new
      // link every time. The public lookup collection holds the hash alone.
      portalToken: token,
      portalCreatedAtMs: now,
      portalRevokedAtMs: 0,
      portalVisibility: cleanPortalVisibility(orderData.portalVisibility),
      portalAutoUpdates: cleanPortalAutoUpdates(orderData.portalAutoUpdates),
      historyLog: [
        webHistoryEntry("Customer portal link created", "-", "active", uid, email),
        ...history
      ].slice(0, 120)
    });
  });

  return { ok: true, url: `${await clientPortalBaseUrl(companyId)}/track/${token}`, token };
});

exports.revokeOrderPortalLink = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, email, companyId } = await requirePortalStaff(request);
  const orderId = cleanOrderText(request.data && request.data.orderId, "", 200);
  if (!orderId) throw new HttpsError("invalid-argument", "orderId is required.");

  const orderRef = orderDocRef(orderId);
  const orderSnap = await orderRef.get();
  if (!orderSnap.exists) throw new HttpsError("not-found", "Order not found.");
  const orderData = orderSnap.data() || {};
  if (orderCompanyId(orderData) !== companyId) {
    throw new HttpsError("permission-denied", "This order does not belong to the active workspace.");
  }
  const now = Date.now();
  const tokenId = String(orderData.portalTokenId || "");
  if (tokenId) {
    await portalLinksCollection().doc(tokenId).set({ revokedAtMs: now }, { merge: true });
  }
  const history = Array.isArray(orderData.historyLog) ? orderData.historyLog : [];
  await orderRef.update({
    portalTokenId: "",
    portalToken: "",
    portalRevokedAtMs: now,
    historyLog: [
      webHistoryEntry("Customer portal link revoked", "active", "off", uid, email),
      ...history
    ].slice(0, 120)
  });
  return { ok: true };
});

exports.saveOrderPortalSettings = onCall({ region: "europe-west2" }, async (request) => {
  const { companyId } = await requirePortalStaff(request);
  const orderId = cleanOrderText(request.data && request.data.orderId, "", 200);
  if (!orderId) throw new HttpsError("invalid-argument", "orderId is required.");

  const orderRef = orderDocRef(orderId);
  const orderSnap = await orderRef.get();
  if (!orderSnap.exists) throw new HttpsError("not-found", "Order not found.");
  const orderData = orderSnap.data() || {};
  if (orderCompanyId(orderData) !== companyId) {
    throw new HttpsError("permission-denied", "This order does not belong to the active workspace.");
  }

  const visibility = cleanPortalVisibility(request.data && request.data.visibility);
  const autoUpdates = cleanPortalAutoUpdates(request.data && request.data.autoUpdates);
  await orderRef.update({ portalVisibility: visibility, portalAutoUpdates: autoUpdates });
  return { ok: true, visibility, autoUpdates };
});

// Client-domain spoof guard: a token page served on a REGISTERED client
// domain must belong to the workspace that owns that domain. Unregistered and
// primary hosts pass — the registry is the only authority worth consulting,
// and the pages must keep working before the custom-hostname serving
// infrastructure exists.
async function assertHostMayServeCompany(rawHost, companyId) {
  const servingHost = String(rawHost || "").trim().toLowerCase().split(":")[0].replace(/\.$/, "");
  if (!servingHost) return;
  if (["nivadesk.app", "www.nivadesk.app", "localhost", "127.0.0.1"].includes(servingHost)) return;
  const hostKey = servingHost.endsWith(".nivadesk.app")
    ? servingHost.slice(0, -".nivadesk.app".length)
    : servingHost;
  const domainSnap = await admin.firestore().collection("clientDomains").doc(hostKey).get().catch(() => null);
  if (!domainSnap || !domainSnap.exists) return;
  const domainRow = domainSnap.data() || {};
  if (String(domainRow.companyId || "") !== String(companyId || "")) {
    throw new HttpsError("permission-denied", "This link does not belong to this domain.");
  }
}

exports.getPortalForVisitor = onCall({ region: "europe-west2" }, async (request) => {
  const token = String(request.data && request.data.token || "").trim();
  await websiteChatCheckRate("portalView", websiteChatClientIp(request), PORTAL_VIEW_PER_HOUR);
  await websiteChatCheckRate("portalViewTok", token, PORTAL_VIEW_TOKEN_PER_HOUR);

  const { linkRef, link, orderData } = await portalLinkForVisitor(token);

  await assertHostMayServeCompany(request.data && request.data.host, link.companyId);

  await linkRef.set(
    { viewCount: Number(link.viewCount || 0) + 1, viewedAtMs: Date.now() },
    { merge: true }
  );
  const settings = await portalWorkspaceSettings(link.companyId);
  const portal = portalPublicView(orderData, settings, link);
  portal.files = (await portalLibraryFilesForOrder(
    String(link.companyId || orderCompanyId(orderData) || ""),
    String(link.orderId || "")
  ).catch(() => [])).map((file) => ({ ...file, url: maskedPortalFileUrl(file.url) }));
  return { ok: true, portal };
});

// Fires on the status the workspace already sets. Nothing new to remember: move
// the order to "Ready to Collect" and the customer hears about it.
exports.notifyCustomerOnStatusChange = onDocumentWritten(
  {
    document: "siparisler/{orderId}",
    region: "europe-west2",
    secrets: [NIVADESK_SMTP_PASSWORD, TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN]
  },
  async (event) => {
    const before = event.data?.before?.exists ? event.data.before.data() || {} : null;
    const after = event.data?.after?.exists ? event.data.after.data() || {} : null;
    if (!after || after.isDeleted === true) return;

    const status = cleanOrderText(after.status, "", 60);
    if (!status) return;
    if (before && cleanOrderText(before.status, "", 60) === status) return;

    const auto = cleanPortalAutoUpdates(after.portalAutoUpdates);
    if (!auto.enabled) return;
    if (!auto.email && !auto.sms) return;

    const toEmail = cleanOrderText(after.emailAddress, "", 240);
    const toPhone = cleanOrderText(after.whatsappNumber, "", 40);
    // Neither channel has anywhere to go.
    if ((!auto.email || !toEmail.includes("@")) && (!auto.sms || !toPhone)) return;
    // A repeated status (a correction, a sync echo) must not re-send.
    if (cleanOrderText(after.portalLastNotifiedStatus, "", 60).toLowerCase() === status.toLowerCase()) return;

    const orderId = String(event.params.orderId || "");
    const companyId = orderCompanyId(after);
    if (!companyId) return;

    const [settings, companySnap] = await Promise.all([
      portalWorkspaceSettings(companyId),
      admin.firestore().collection("companies").doc(companyId).get()
    ]);
    const companyData = companySnap.exists ? companySnap.data() || {} : {};
    const config = workspaceSmsConfig(settings);
    const itemName = cleanOrderText(after.designName, "", 160);
    const message = portalStatusMessage(status, { itemName })
      || (config.triggers.everyStatusChange ? portalGenericStatusMessage(status, { itemName }) : null);
    if (!message) {
      // Not a milestone worth a message, but remember it so the next real one is
      // still recognised as a change.
      await orderDocRef(orderId).update({ portalLastNotifiedStatus: status }).catch(() => undefined);
      return;
    }

    // The link only goes in the message when the workspace has actually made one.
    const portalToken = cleanOrderText(after.portalToken, "", 200);
    const portalUrl = portalToken && String(after.portalTokenId || "")
      ? `${clientPortalBaseUrlFromCompany(companyData)}/track/${portalToken}`
      : "";

    // Branded, one-way, and strictly a service message about an order this
    // customer already has with this business — never a promotion, which is what
    // keeps it out of direct-marketing rules.
    if (auto.sms && config.triggers[message.trigger] !== false) {
      // The customer sees "NivaDesk" as the sender, so the business has to name
      // itself in the text or the message is from a stranger. Once a workspace
      // has its own registered sender ID the prefix is redundant and dropped.
      // The name the business signed up under, not appSubtitle — that field is a
      // tagline whose stock value is "Bespoke Hand-Painted Dials", which would
      // introduce a jeweller's customer to a watch-dial studio and eat a fifth of
      // the segment doing it. Capped short: the name shares 160 characters with
      // the message and the tracking link.
      const workspaceName = cleanOrderText(
        companyData.name || companyData.companyName || settings.appSubtitle,
        "",
        32
      );
      const smsBody = [
        !config.usesOwnSender && workspaceName ? `${workspaceName}: ${message.sms}` : message.sms,
        portalUrl
      ].filter(Boolean).join(" ");
      await sendWorkspaceSMS({
        companyData,
        settings,
        companyId,
        orderId,
        orderReference: cleanOrderText(after.invoiceNumber, "", 60),
        customerName: cleanOrderText(after.customerName, "", 160),
        toNumber: cleanOrderText(after.whatsappNumber, "", 40),
        trigger: message.trigger,
        body: smsBody
      }).catch((error) => {
        console.warn("notifyCustomerOnStatusChange: sms failed", { orderId, error: String(error) });
      });
    }

    if (!auto.email || !toEmail.includes("@")) {
      await orderDocRef(orderId).update({ portalLastNotifiedStatus: status }).catch(() => undefined);
      return;
    }

    try {
      await sendPortalStatusEmail({
        toEmail,
        businessName: String(settings.appSubtitle || "NivaDesk"),
        // Replies reach the business, not us. Falls back to no reply-to rather
        // than pointing a customer at the NivaDesk support inbox.
        replyTo: cleanOrderText(settings.invoiceReplyToEmail, "", 240),
        subject: message.subject,
        line: message.line,
        portalUrl,
        footerNote: String(settings.invoiceFooterNote || "")
      });
    } catch (error) {
      console.warn("notifyCustomerOnStatusChange: mail failed", { orderId, error: String(error) });
    }

    const history = Array.isArray(after.historyLog) ? after.historyLog : [];
    await orderDocRef(orderId).update({
      portalLastNotifiedStatus: status,
      historyLog: [
        webHistoryEntry("Customer notified", "-", status, "", "automatic"),
        ...history
      ].slice(0, 120)
    }).catch(() => undefined);
  }
);

function estimateLinksCollection() {
  return admin.firestore().collection("estimateLinks");
}

function estimateRecordsCollection(orderId) {
  return orderDocRef(orderId).collection("estimateRecords");
}

// Money is recomputed here and frozen. Never trust a total from a client: the
// three platforms already disagree about whether custom receivables count, and
// a signed document must not inherit that.
function estimateTotals(lineItems, taxRate, taxType) {
  const rate = Number(taxRate) || 0;
  const isMargin = String(taxType || "") === "Profit";
  const gross = lineItems.reduce((sum, item) => sum + item.lineTotal, 0);
  const total = roundLineMoney(gross);
  const taxAmount = isMargin || rate <= 0.0001 ? 0 : roundLineMoney((total * rate) / (100 + rate));
  const subtotal = isMargin ? total : roundLineMoney(total - taxAmount);
  return { subtotal, taxAmount, total };
}

function estimateLineItemsFromInput(value) {
  const incoming = Array.isArray(value) ? value.slice(0, ESTIMATE_MAX_LINE_ITEMS) : [];
  return incoming
    .map((item) => {
      const quantity = Math.max(0, Number(item && item.quantity) || 0);
      const unitPrice = roundLineMoney(item && item.unitPrice);
      const lineTotal = item && item.lineTotal != null
        ? roundLineMoney(item.lineTotal)
        : roundLineMoney(quantity * unitPrice);
      return {
        id: cleanOrderText(item && item.id, "", 60) || crypto.randomUUID(),
        name: cleanOrderText(item && item.name, "", 200),
        quantity,
        unitPrice,
        lineTotal
      };
    })
    .filter((item) => item.name || Math.abs(item.lineTotal) > 0.005);
}

// Canonical JSON of everything the customer agreed to. Stored at creation and
// checked again at the moment of approval, so tampering in between is provable.
function estimateDocumentHash(record) {
  return nvSha256(JSON.stringify({
    number: record.number,
    version: record.version,
    lineItems: (record.lineItems || []).map((item) => [item.name, item.quantity, item.unitPrice, item.lineTotal]),
    subtotal: record.subtotal,
    taxRate: record.taxRate,
    taxType: record.taxType,
    taxAmount: record.taxAmount,
    total: record.total,
    terms: record.terms || "",
    validUntilMs: record.validUntilMs || 0
  }));
}

// The row the order carries for the card: small enough to sit beside historyLog
// without threatening the 1 MB document limit.
function estimateIndexEntry(record, linkState) {
  return {
    id: record.estimateId,
    number: record.number,
    version: record.version,
    status: record.status,
    total: record.total,
    subtotal: record.subtotal,
    taxAmount: record.taxAmount,
    taxRate: record.taxRate,
    taxType: record.taxType,
    itemCount: (record.lineItems || []).length,
    createdAtMs: record.createdAtMs || 0,
    sentAtMs: record.sentAtMs || 0,
    viewedAtMs: record.viewedAtMs || 0,
    decidedAtMs: record.approval ? record.approval.decidedAtMs : 0,
    decidedBy: record.approval ? record.approval.approvedByName : "",
    decisionMethod: record.approval ? record.approval.method : "",
    hasSignature: Boolean(record.approval && record.approval.signatureStoragePath),
    supersedesId: record.supersedesId || "",
    supersededById: record.supersededById || "",
    linkState: linkState || "none"
  };
}

function estimateIndexReplace(existing, entry) {
  const rows = Array.isArray(existing) ? existing.filter((row) => row && row.id !== entry.id) : [];
  return [entry, ...rows].slice(0, 40);
}

// What a signed-in member gets. Hand-built rather than the raw document for two
// reasons: the stored record holds a Firestore Timestamp that would reach four
// clients in four shapes, and it holds the approver's IP and user agent, which
// staff have no reason to read off a card. Numbers go out as numbers and times
// as epoch milliseconds, so Swift and Kotlin parse them the same way.
function estimateStaffView(record = {}) {
  const approval = record.approval && typeof record.approval === "object" ? record.approval : null;
  return {
    estimateId: String(record.estimateId || ""),
    number: String(record.number || ""),
    version: Number(record.version) || 1,
    status: String(record.status || "draft"),
    currency: String(record.currency || "GBP"),
    lineItems: (Array.isArray(record.lineItems) ? record.lineItems : []).map((item) => ({
      id: String(item.id || ""),
      name: String(item.name || ""),
      quantity: Number(item.quantity) || 0,
      unitPrice: Number(item.unitPrice) || 0,
      lineTotal: Number(item.lineTotal) || 0
    })),
    subtotal: Number(record.subtotal) || 0,
    taxRate: Number(record.taxRate) || 0,
    taxType: String(record.taxType || ""),
    taxAmount: Number(record.taxAmount) || 0,
    total: Number(record.total) || 0,
    terms: String(record.terms || ""),
    notes: String(record.notes || ""),
    validUntilMs: Number(record.validUntilMs) || 0,
    createdAtMs: Number(record.createdAtMs) || 0,
    sentAtMs: Number(record.sentAtMs) || 0,
    viewedAtMs: Number(record.viewedAtMs) || 0,
    replacesNumber: String(record.replacesNumber || ""),
    supersededById: String(record.supersededById || ""),
    customerNameSnapshot: String(record.customerNameSnapshot || ""),
    approval: approval
      ? {
          decision: String(approval.decision || ""),
          method: String(approval.method || ""),
          decidedAtMs: Number(approval.decidedAtMs) || 0,
          approvedByName: String(approval.approvedByName || ""),
          approvedByEmail: String(approval.approvedByEmail || ""),
          declineReason: String(approval.declineReason || ""),
          signatureDownloadUrl: String(approval.signatureDownloadUrl || "")
        }
      : null
  };
}

// Everything the visitor is allowed to see. Hand-built: never spread a document
// that also holds costs, margins, staff emails or the rest of the workspace.
function estimatePublicView(record, settings, link) {
  return {
    number: record.number,
    version: record.version,
    status: record.status,
    currency: record.currency || "GBP",
    lineItems: (record.lineItems || []).map((item) => ({
      name: item.name,
      quantity: item.quantity,
      unitPrice: item.unitPrice,
      lineTotal: item.lineTotal
    })),
    subtotal: record.subtotal,
    taxRate: record.taxRate,
    taxType: record.taxType,
    taxAmount: record.taxAmount,
    total: record.total,
    terms: record.terms || "",
    notes: record.notes || "",
    validUntilMs: record.validUntilMs || 0,
    createdAtMs: record.createdAtMs || 0,
    businessName: String(settings.appSubtitle || "NivaDesk"),
    logoUrl: String(settings.appLogoUrl || ""),
    footerNote: String(settings.invoiceFooterNote || ""),
    accentColor: /^#[0-9a-f]{6}$/i.test(String(settings.portalAccentColor || "")) ? String(settings.portalAccentColor).toLowerCase() : "",
    showPoweredBy: settings.portalShowPoweredBy !== false,
    customerFirstName: String(record.customerNameSnapshot || "").split(" ")[0] || "",
    replacesNumber: record.replacesNumber || "",
    alreadyDecided: Boolean(record.approval),
    decision: record.approval ? record.approval.decision : "",
    decidedAtMs: record.approval ? record.approval.decidedAtMs : 0,
    decidedByName: record.approval ? record.approval.approvedByName : "",
    expiresAtMs: Number(link && link.expiresAtMs) || 0
  };
}

// A drawn signature arrives as a data URL from a stranger. Trust the bytes, not
// the label: check the PNG magic number and the size before it reaches Storage.
function estimateSignatureBuffer(base64) {
  const raw = String(base64 || "").trim();
  if (!raw) return null;
  const payload = raw.includes(",") ? raw.slice(raw.indexOf(",") + 1) : raw;
  let buffer;
  try {
    buffer = Buffer.from(payload, "base64");
  } catch {
    throw new HttpsError("invalid-argument", "The signature could not be read.");
  }
  if (buffer.length < 200) throw new HttpsError("invalid-argument", "Please sign before approving.");
  if (buffer.length > ESTIMATE_SIGNATURE_MAX_BYTES) {
    throw new HttpsError("invalid-argument", "That signature is too large.");
  }
  const png = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  if (!buffer.subarray(0, 8).equals(png)) {
    throw new HttpsError("invalid-argument", "The signature must be a PNG image.");
  }
  return buffer;
}

// Lookup is by hashed token as the document id, so there is no comparison to
// get wrong and the plaintext is never stored anywhere.
async function estimateLinkForVisitor(token) {
  const raw = String(token || "").trim();
  if (!raw || raw.length > 200) throw new HttpsError("invalid-argument", "This link is not valid.");
  const linkRef = estimateLinksCollection().doc(nvSha256(raw));
  const linkSnap = await linkRef.get();
  if (!linkSnap.exists) throw new HttpsError("not-found", "This link is no longer available.");
  const link = linkSnap.data() || {};
  const now = Date.now();
  if (Number(link.revokedAtMs) > 0) throw new HttpsError("failed-precondition", "This estimate has been replaced by a newer one.");
  if (Number(link.expiresAtMs) > 0 && Number(link.expiresAtMs) <= now) {
    throw new HttpsError("failed-precondition", "This link has expired. Please ask for a new one.");
  }
  const orderRef = orderDocRef(String(link.orderId || ""));
  const recordRef = estimateRecordsCollection(String(link.orderId || "")).doc(String(link.estimateId || ""));
  const [orderSnap, recordSnap] = await Promise.all([orderRef.get(), recordRef.get()]);
  if (!orderSnap.exists || !recordSnap.exists) throw new HttpsError("not-found", "This estimate is no longer available.");
  // An order in the Trash should not still be taking approvals. Checked here
  // rather than by revoking the link on delete, because revoking is one-way and
  // restoring the order from the Trash would leave the customer's link dead.
  if ((orderSnap.data() || {}).isDeleted === true) {
    throw new HttpsError("failed-precondition", "This estimate is no longer available.");
  }
  return {
    linkRef,
    link,
    orderRef,
    orderData: orderSnap.data() || {},
    recordRef,
    record: recordSnap.data() || {}
  };
}

// Mirrors the bank-feed notifyCompany lambda, using the same two primitives.
// Money stays out of the text: companies/{cid}/notifications is readable by
// every workspace member, and only application code filters recipients.
async function notifyEstimateDecision(companyId, payload = {}) {
  const notificationId = `estimate_${payload.orderId || "order"}_${Date.now()}`;
  const ref = notificationCollectionRef(companyId).doc(notificationId);
  const approved = payload.decision === "approved";
  const data = {
    companyId,
    type: "estimate_decision",
    title: approved ? "Estimate approved" : "Estimate declined",
    message: `${payload.approvedByName || "The customer"} ${approved ? "approved" : "declined"} ${payload.number || "an estimate"}.`,
    route: "orders",
    orderId: String(payload.orderId || ""),
    createdAt: admin.firestore.FieldValue.serverTimestamp(),
    read: false,
    actioned: false,
    source: "estimate"
  };
  await ref.set(data, { merge: true });
  const pushResult = await sendPushNotificationToCompany(companyId, {
    ...data,
    notificationId,
    createdAt: new Date().toISOString()
  });
  await ref.set({ pushSent: pushResult.sent > 0, pushResult }, { merge: true });
}

async function estimateWorkspaceSettings(companyId) {
  // The customer-facing page is branded from companySettings — the same doc the
  // invoice renderers read. The company doc carries none of these fields.
  const snap = await companySettingsDocRef(String(companyId)).get();
  return snap.exists ? snap.data() || {} : {};
}


// estimateRecords sits under the deny-all rule, so these callables are the only
// access control there is. Membership alone is not enough: pricing a job and
// minting a link a customer can sign is a full-edit action.
async function requireEstimateStaff(request) {
  const context = await requireWorkspaceForBilling(request, false);
  requireWorkspaceAreaAccess(context.companyData, context.uid, "orders");
  const role = workspaceOrderRole(context.companyData, context.uid);
  if (!canFullyEditOrder(role)) {
    throw new HttpsError("permission-denied", "Your workspace role cannot create or send estimates.");
  }
  return { ...context, role };
}

// Staff: create a revision. Never edits an existing estimate — the previous one
// is marked superseded and keeps its own numbers, because that is the whole
// point of having a record.
exports.createOrderEstimate = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, email, companyId, companyRef } = await requireEstimateStaff(request);
  const orderId = cleanOrderText(request.data && request.data.orderId, "", 200);
  if (!orderId) throw new HttpsError("invalid-argument", "orderId is required.");

  const lineItems = estimateLineItemsFromInput(request.data && request.data.lineItems);
  if (lineItems.length === 0) throw new HttpsError("invalid-argument", "Add at least one line to the estimate.");

  const taxRate = cleanTaxRate(request.data && request.data.taxRate);
  const taxType = cleanOrderText(request.data && request.data.taxType, "", 40);
  const notes = cleanOrderText(request.data && request.data.notes, "", 2000);
  const terms = cleanOrderText(request.data && request.data.terms, "", 4000);
  const validUntilMs = Math.max(0, Number(request.data && request.data.validUntilMs) || 0);
  const supersedesId = cleanOrderText(request.data && request.data.supersedesId, "", 80);

  const orderRef = orderDocRef(orderId);
  const estimateId = crypto.randomUUID();
  const now = Date.now();

  const result = await admin.firestore().runTransaction(async (tx) => {
    // Branding and currency live in companySettings, not on the company doc —
    // reading the wrong one froze every estimate at an unbranded "GBP".
    const [companySnap, orderSnap, settingsSnap] = await Promise.all([
      tx.get(companyRef),
      tx.get(orderRef),
      tx.get(companySettingsDocRef(companyId))
    ]);
    if (!orderSnap.exists) throw new HttpsError("not-found", "Order not found.");
    const orderData = orderSnap.data() || {};
    if (orderCompanyId(orderData) !== companyId) {
      throw new HttpsError("permission-denied", "This order does not belong to the active workspace.");
    }

    let supersededRecord = null;
    let supersededRef = null;
    if (supersedesId) {
      supersededRef = estimateRecordsCollection(orderId).doc(supersedesId);
      const supersededSnap = await tx.get(supersededRef);
      if (supersededSnap.exists) supersededRecord = supersededSnap.data() || {};
    }

    // Estimates get their own counter. Borrowing assignInvoiceNumber would burn
    // a real invoice number on a quote that may never be accepted.
    const companyData = companySnap.exists ? companySnap.data() || {} : {};
    const year = new Date().getFullYear();
    let counter = Number(companyData.estimateCounter || 0);
    let counterYear = Number(companyData.estimateCounterYear || 0);
    if (counterYear !== year) { counter = 0; counterYear = year; }
    counter += 1;
    const number = `EST-${year}-${String(counter).padStart(4, "0")}`;

    const totals = estimateTotals(lineItems, taxRate, taxType);
    const settings = settingsSnap.exists ? settingsSnap.data() || {} : {};
    const record = {
      estimateId,
      orderId,
      companyId,
      number,
      version: supersededRecord ? Number(supersededRecord.version || 1) + 1 : 1,
      status: "draft",
      currency: cleanFinancialCurrency(settings.seciliParaBirimi, "£"),
      lineItems,
      subtotal: totals.subtotal,
      taxRate,
      taxType,
      taxAmount: totals.taxAmount,
      total: totals.total,
      terms,
      notes,
      validUntilMs,
      customerNameSnapshot: cleanOrderText(orderData.customerName, "", 240),
      customerEmailSnapshot: cleanOrderText(orderData.emailAddress, "", 240),
      workspaceNameSnapshot: String(settings.appSubtitle || ""),
      workspaceLogoUrlSnapshot: String(settings.appLogoUrl || ""),
      footerNoteSnapshot: String(settings.invoiceFooterNote || ""),
      replacesNumber: supersededRecord ? String(supersededRecord.number || "") : "",
      createdAtMs: now,
      createdByUid: uid,
      createdByEmail: email,
      sentAtMs: 0,
      viewedAtMs: 0,
      viewCount: 0,
      supersedesId: supersedesId || "",
      supersededById: "",
      supersededAtMs: 0,
      approval: null
    };
    record.documentSha256 = estimateDocumentHash(record);

    tx.set(estimateRecordsCollection(orderId).doc(estimateId), record);
    tx.set(companyRef, { estimateCounter: counter, estimateCounterYear: counterYear }, { merge: true });

    let index = estimateIndexReplace(orderData.estimates, estimateIndexEntry(record, "none"));
    const history = [webHistoryEntry("Estimate created", "-", `${number} · ${totals.total}`, uid, email)];

    if (supersededRecord && supersededRef) {
      tx.update(supersededRef, { status: "superseded", supersededById: estimateId, supersededAtMs: now });
      const supersededEntry = estimateIndexEntry(
        { ...supersededRecord, status: "superseded", supersededById: estimateId },
        "revoked"
      );
      index = estimateIndexReplace(index, supersededEntry);
      history.push(webHistoryEntry("Estimate superseded", String(supersededRecord.number || ""), number, uid, email));
      // The old price must stop being approvable the moment a new one exists.
      if (supersededRecord.linkTokenId) {
        tx.set(
          estimateLinksCollection().doc(String(supersededRecord.linkTokenId)),
          { revokedAtMs: now },
          { merge: true }
        );
      }
    }

    const existingHistory = Array.isArray(orderData.historyLog) ? orderData.historyLog : [];
    tx.update(orderRef, {
      estimates: index,
      estimateStatus: record.status,
      estimateTotal: record.total,
      estimateNumber: record.number,
      historyLog: [...history, ...existingHistory].slice(0, 120)
    });

    return { number, version: record.version, total: record.total };
  });

  console.log("createOrderEstimate", { companyId, orderId, estimateId, uid, number: result.number });
  return { ok: true, estimateId, ...result };
});

// Staff: mint the customer's link. The plaintext token is returned once and
// never stored — the document id is its hash.
exports.sendOrderEstimate = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, email, companyId } = await requireEstimateStaff(request);
  const orderId = cleanOrderText(request.data && request.data.orderId, "", 200);
  const estimateId = cleanOrderText(request.data && request.data.estimateId, "", 80);
  if (!orderId || !estimateId) throw new HttpsError("invalid-argument", "orderId and estimateId are required.");

  await websiteChatCheckRate("estimateMint", uid, 60);

  const orderRef = orderDocRef(orderId);
  const recordRef = estimateRecordsCollection(orderId).doc(estimateId);
  const token = nvRandomToken(32);
  const tokenId = nvSha256(token);
  const now = Date.now();

  const expiresAtMs = await admin.firestore().runTransaction(async (tx) => {
    const [orderSnap, recordSnap] = await Promise.all([tx.get(orderRef), tx.get(recordRef)]);
    if (!orderSnap.exists || !recordSnap.exists) throw new HttpsError("not-found", "Estimate not found.");
    const orderData = orderSnap.data() || {};
    if (orderCompanyId(orderData) !== companyId) {
      throw new HttpsError("permission-denied", "This order does not belong to the active workspace.");
    }
    const record = recordSnap.data() || {};
    if (record.approval) throw new HttpsError("failed-precondition", "This estimate has already been decided.");
    if (record.status === "superseded") throw new HttpsError("failed-precondition", "This estimate has been replaced.");

    const validUntil = Number(record.validUntilMs) || 0;
    const expires = validUntil > 0 ? Math.min(now + ESTIMATE_LINK_TTL_MS, validUntil) : now + ESTIMATE_LINK_TTL_MS;

    // A fresh link retires the previous one, so only one price is live.
    if (record.linkTokenId) {
      tx.set(estimateLinksCollection().doc(String(record.linkTokenId)), { revokedAtMs: now }, { merge: true });
    }

    tx.set(estimateLinksCollection().doc(tokenId), {
      companyId,
      orderId,
      estimateId,
      createdByUid: uid,
      createdAtMs: now,
      expiresAtMs: expires,
      viewedAtMs: 0,
      viewCount: 0,
      consumedAtMs: 0,
      revokedAtMs: 0
    });

    tx.update(recordRef, { status: "sent", sentAtMs: now, sentByUid: uid, linkTokenId: tokenId });

    const index = estimateIndexReplace(
      orderData.estimates,
      estimateIndexEntry({ ...record, status: "sent", sentAtMs: now }, "active")
    );
    const existingHistory = Array.isArray(orderData.historyLog) ? orderData.historyLog : [];
    tx.update(orderRef, {
      estimates: index,
      estimateStatus: "sent",
      historyLog: [webHistoryEntry("Estimate sent", "-", String(record.number || ""), uid, email), ...existingHistory].slice(0, 120)
    });

    return expires;
  });

  console.log("sendOrderEstimate", { companyId, orderId, estimateId, uid });
  return { ok: true, url: `${await clientPortalBaseUrl(companyId)}/e/${token}`, token, expiresAtMs };
});

exports.revokeOrderEstimateLink = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId } = await requireEstimateStaff(request);
  const orderId = cleanOrderText(request.data && request.data.orderId, "", 200);
  const estimateId = cleanOrderText(request.data && request.data.estimateId, "", 80);
  if (!orderId || !estimateId) throw new HttpsError("invalid-argument", "orderId and estimateId are required.");

  const orderRef = orderDocRef(orderId);
  const recordRef = estimateRecordsCollection(orderId).doc(estimateId);
  const [orderSnap, recordSnap] = await Promise.all([orderRef.get(), recordRef.get()]);
  if (!orderSnap.exists || !recordSnap.exists) throw new HttpsError("not-found", "Estimate not found.");
  const orderData = orderSnap.data() || {};
  if (orderCompanyId(orderData) !== companyId) {
    throw new HttpsError("permission-denied", "This order does not belong to the active workspace.");
  }
  const record = recordSnap.data() || {};
  if (record.linkTokenId) {
    await estimateLinksCollection().doc(String(record.linkTokenId)).set({ revokedAtMs: Date.now() }, { merge: true });
  }
  const index = estimateIndexReplace(orderData.estimates, estimateIndexEntry(record, "revoked"));
  await orderRef.update({ estimates: index });
  console.log("revokeOrderEstimateLink", { companyId, orderId, estimateId, uid });
  return { ok: true };
});

// Staff: the full record, for the PDF and the history sheet.
exports.getOrderEstimateRecord = onCall({ region: "europe-west2" }, async (request) => {
  const { companyId } = await requireWorkspaceForBilling(request, false);
  const orderId = cleanOrderText(request.data && request.data.orderId, "", 200);
  const estimateId = cleanOrderText(request.data && request.data.estimateId, "", 80);
  if (!orderId) throw new HttpsError("invalid-argument", "orderId is required.");

  const orderSnap = await orderDocRef(orderId).get();
  if (!orderSnap.exists) throw new HttpsError("not-found", "Order not found.");
  if (orderCompanyId(orderSnap.data() || {}) !== companyId) {
    throw new HttpsError("permission-denied", "This order does not belong to the active workspace.");
  }

  if (!estimateId) {
    const snap = await estimateRecordsCollection(orderId).orderBy("createdAtMs", "desc").limit(40).get();
    return { ok: true, records: snap.docs.map((doc) => estimateStaffView(doc.data())) };
  }
  const recordSnap = await estimateRecordsCollection(orderId).doc(estimateId).get();
  if (!recordSnap.exists) throw new HttpsError("not-found", "Estimate not found.");
  return { ok: true, record: estimateStaffView(recordSnap.data()) };
});


// Public: the customer opens their link. No sign-in, so nothing here trusts the
// request for anything but the token — companyId and orderId come off the link.
exports.getEstimateForVisitor = onCall({ region: "europe-west2" }, async (request) => {
  const token = String(request.data && request.data.token || "").trim();
  await websiteChatCheckRate("estimateView", websiteChatClientIp(request), ESTIMATE_VIEW_PER_HOUR);
  await websiteChatCheckRate("estimateViewTok", token, ESTIMATE_VIEW_TOKEN_PER_HOUR);

  const { linkRef, link, orderRef, orderData, recordRef, record } = await estimateLinkForVisitor(token);
  await assertHostMayServeCompany(request.data && request.data.host, link.companyId);
  if (record.status === "superseded") {
    throw new HttpsError("failed-precondition", "This estimate has been replaced by a newer one.");
  }

  // Viewing stays repeatable — people reopen and forward these links — but the
  // first open is worth recording, and only once.
  if (!record.approval && Number(record.viewedAtMs || 0) === 0) {
    const now = Date.now();
    const existingHistory = Array.isArray(orderData.historyLog) ? orderData.historyLog : [];
    const index = estimateIndexReplace(
      orderData.estimates,
      estimateIndexEntry({ ...record, status: "viewed", viewedAtMs: now }, "active")
    );
    await Promise.all([
      recordRef.update({ status: "viewed", viewedAtMs: now, viewCount: Number(record.viewCount || 0) + 1 }),
      linkRef.set({ viewedAtMs: now, viewCount: Number(link.viewCount || 0) + 1 }, { merge: true }),
      orderRef.update({
        estimates: index,
        estimateStatus: "viewed",
        historyLog: [
          webHistoryEntry("Estimate viewed", "-", String(record.number || ""), "", "customer"),
          ...existingHistory
        ].slice(0, 120)
      })
    ]);
    record.status = "viewed";
    record.viewedAtMs = now;
  } else {
    await linkRef.set({ viewCount: Number(link.viewCount || 0) + 1 }, { merge: true });
  }

  const settings = await estimateWorkspaceSettings(link.companyId);
  return { ok: true, estimate: estimatePublicView(record, settings, link) };
});

// Public: approve or decline. One decision, ever.
exports.postEstimateDecision = onCall({ region: "europe-west2" }, async (request) => {
  const data = request.data || {};
  const token = String(data.token || "").trim();
  await websiteChatCheckRate("estimateDecide", websiteChatClientIp(request), ESTIMATE_DECIDE_PER_HOUR);
  await websiteChatCheckRate("estimateDecideTok", token, ESTIMATE_DECIDE_TOKEN_PER_HOUR);

  const decision = String(data.decision || "").trim().toLowerCase() === "declined" ? "declined" : "approved";
  const approvedByName = cleanSupportText(data.approvedByName, 160);
  if (!approvedByName) throw new HttpsError("invalid-argument", "Please type your name.");
  const approvedByEmail = websiteChatVisitorEmail(data.approvedByEmail);
  const declineReason = cleanSupportText(data.declineReason, 1000);

  const context = await estimateLinkForVisitor(token);
  const { linkRef, link, orderRef, recordRef, record } = context;

  // Idempotent: a double tap on a flaky phone shows the confirmation again
  // rather than an error, and never rewrites the evidence already stored.
  if (record.approval) {
    return {
      ok: true,
      alreadyDecided: true,
      decision: record.approval.decision,
      decidedAtMs: record.approval.decidedAtMs,
      decidedByName: record.approval.approvedByName
    };
  }
  if (record.status !== "sent" && record.status !== "viewed") {
    throw new HttpsError("failed-precondition", "This estimate can no longer be decided.");
  }
  if (estimateDocumentHash(record) !== String(record.documentSha256 || "")) {
    throw new HttpsError("failed-precondition", "This estimate has changed. Please ask for a fresh link.");
  }

  // Signature first: a failed upload must not leave a decision half-written.
  let signatureStoragePath = "";
  let signatureSha256 = "";
  let signatureBytes = 0;
  let signatureDownloadUrl = "";
  if (decision === "approved") {
    const buffer = estimateSignatureBuffer(data.signaturePngBase64);
    if (!buffer) throw new HttpsError("invalid-argument", "Please sign before approving.");
    signatureStoragePath = `companies/${link.companyId}/signatures/${link.orderId}/${link.estimateId}.png`;
    signatureSha256 = nvSha256(buffer.toString("base64"));
    signatureBytes = buffer.length;
    // The Admin SDK bypasses Storage rules; a visitor never touches the bucket.
    // An object written this way has no download token of its own, and all three
    // PDF renderers need to fetch the image, so mint one here. That URL is an
    // unauthenticated link — it is kept in the record and handed only to signed-in
    // members through getOrderEstimateRecord, never to the public page.
    const downloadToken = crypto.randomUUID();
    const bucket = admin.storage().bucket();
    await bucket.file(signatureStoragePath).save(buffer, {
      contentType: "image/png",
      resumable: false,
      metadata: { metadata: { firebaseStorageDownloadTokens: downloadToken } }
    });
    signatureDownloadUrl = `https://firebasestorage.googleapis.com/v0/b/${bucket.name}/o/${encodeURIComponent(signatureStoragePath)}?alt=media&token=${downloadToken}`;
  }

  const now = Date.now();
  const rawRequest = request.rawRequest || {};
  const approval = {
    decision,
    method: "customer_portal",
    decidedAtMs: now,
    decidedAtServer: admin.firestore.Timestamp.now(),
    // Self-declared: the customer typed this, we did not verify it.
    approvedByName,
    approvedByEmail,
    declineReason: decision === "declined" ? declineReason : "",
    ip: websiteChatClientIp(request),
    userAgentTruncated: String(rawRequest.headers?.["user-agent"] || "").slice(0, 200),
    linkTokenId: linkRef.id,
    documentSha256AtDecision: String(record.documentSha256 || ""),
    signatureStoragePath,
    signatureSha256,
    signatureBytes,
    signatureDownloadUrl
  };

  const applied = await admin.firestore().runTransaction(async (tx) => {
    const [linkSnap, recordSnap, orderSnap] = await Promise.all([tx.get(linkRef), tx.get(recordRef), tx.get(orderRef)]);
    const linkNow = linkSnap.exists ? linkSnap.data() || {} : {};
    const recordNow = recordSnap.exists ? recordSnap.data() || {} : {};
    if (recordNow.approval) return { raced: true, approval: recordNow.approval };
    if (Number(linkNow.consumedAtMs) > 0) return { raced: true, approval: recordNow.approval || approval };
    if (Number(linkNow.revokedAtMs) > 0) {
      throw new HttpsError("failed-precondition", "This estimate has been replaced by a newer one.");
    }

    const orderData = orderSnap.exists ? orderSnap.data() || {} : {};
    const nextStatus = decision === "approved" ? "approved" : "declined";
    tx.update(recordRef, { status: nextStatus, approval });
    tx.set(linkRef, { consumedAtMs: now }, { merge: true });

    const index = estimateIndexReplace(
      orderData.estimates,
      estimateIndexEntry({ ...recordNow, status: nextStatus, approval }, "used")
    );
    const existingHistory = Array.isArray(orderData.historyLog) ? orderData.historyLog : [];
    tx.update(orderRef, {
      estimates: index,
      estimateStatus: nextStatus,
      historyLog: [
        webHistoryEntry(
          decision === "approved" ? "Estimate approved" : "Estimate declined",
          String(recordNow.number || record.number || ""),
          approvedByName,
          "",
          "customer"
        ),
        ...existingHistory
      ].slice(0, 120)
    });
    return { raced: false, approval };
  });

  if (applied.raced) {
    return {
      ok: true,
      alreadyDecided: true,
      decision: applied.approval.decision,
      decidedAtMs: applied.approval.decidedAtMs,
      decidedByName: applied.approval.approvedByName
    };
  }

  // Tell the workspace, without putting the money in a notification every
  // member can read.
  await safeSupportNotification("notifyEstimateDecision", () => notifyEstimateDecision(String(link.companyId), {
    orderId: String(link.orderId || ""),
    decision,
    approvedByName,
    number: String(record.number || "")
  }));

  console.log("postEstimateDecision", { companyId: link.companyId, orderId: link.orderId, estimateId: link.estimateId, decision });
  return { ok: true, alreadyDecided: false, decision, decidedAtMs: now, decidedByName: approvedByName };
});

// Links expire; the records they point at never do. This only ever deletes the
// link documents and the rate-limit windows behind them.
exports.purgeExpiredEstimateLinks = onSchedule(
  { schedule: "every 24 hours", region: "europe-west2", timeZone: "Europe/London" },
  async () => {
    const cutoff = Date.now();
    const snap = await estimateLinksCollection().where("expiresAtMs", "<=", cutoff).limit(400).get();
    if (snap.empty) return;
    const batch = admin.firestore().batch();
    snap.docs.forEach((doc) => batch.delete(doc.ref));
    await batch.commit();
    console.log("purgeExpiredEstimateLinks", { deleted: snap.size });
  }
);

// or platforms. Idempotent: returns the existing number if already assigned.
exports.assignInvoiceNumber = onCall({ region: "europe-west2" }, async (request) => {
  const { uid, companyId, companyRef } = await requireWorkspaceForBilling(request, false);
  const orderId = cleanOrderText(request.data && request.data.orderId, "", 200);
  if (!orderId) throw new HttpsError("invalid-argument", "orderId is required.");
  const orderRef = orderDocRef(orderId);
  const invoiceNumber = await admin.firestore().runTransaction(async (tx) => {
    const [companySnap, orderSnap] = await Promise.all([tx.get(companyRef), tx.get(orderRef)]);
    if (!orderSnap.exists) throw new HttpsError("not-found", "Order not found.");
    const orderData = orderSnap.data() || {};
    if (orderCompanyId(orderData) !== companyId) {
      throw new HttpsError("permission-denied", "This order does not belong to the active workspace.");
    }
    const existing = String(orderData.invoiceNumber || "").trim();
    if (existing) return existing;
    const companyData = companySnap.exists ? companySnap.data() || {} : {};
    const year = new Date().getFullYear();
    let counter = Number(companyData.invoiceCounter || 0);
    let counterYear = Number(companyData.invoiceCounterYear || 0);
    if (counterYear !== year) { counter = 0; counterYear = year; }
    counter += 1;
    const next = `${year}-${String(counter).padStart(4, "0")}`;
    tx.set(companyRef, { invoiceCounter: counter, invoiceCounterYear: counterYear }, { merge: true });
    tx.update(orderRef, { invoiceNumber: next });
    return next;
  });
  console.log("assignInvoiceNumber", { companyId, orderId, uid, invoiceNumber });
  return { ok: true, invoiceNumber };
});

// ---------------------------------------------------------------------------
// Public site visitor statistics
// Anonymous, aggregate-only counters: no cookies, no IPs, no user identifiers.
// Daily doc: siteStats/{YYYY-MM-DD} with increment maps. Written only by the
// beacon endpoint below; read only by support admins via getSiteStats.
// ---------------------------------------------------------------------------

const SITE_STATS_ALLOWED_ORIGINS = new Set([
  "https://nivadesk.app",
  "https://www.nivadesk.app"
]);

function siteStatsFieldKey(value, fallback = "other", maxLength = 60) {
  const cleaned = String(value || "")
    .trim()
    .toLowerCase()
    .slice(0, maxLength)
    .replace(/[.~/*\[\]]/g, "_");
  return cleaned || fallback;
}

function siteStatsDateKey(date = new Date()) {
  return new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/London" }).format(date);
}

// geoip-lite holds its database in memory (~100MB), so load it lazily and only
// inside recordSiteVisit instances — other functions never pay the cost.
let geoipModule = null;
function lookupCountryFromIp(req) {
  try {
    if (geoipModule === null) {
      geoipModule = require("geoip-lite");
    }
    const forwarded = String(req.headers["x-forwarded-for"] || "");
    const ip = (forwarded.split(",")[0] || "").trim() || req.ip || "";
    if (!ip) return "";
    const geo = geoipModule.lookup(ip);
    return String(geo?.country || "").toUpperCase();
  } catch (error) {
    console.warn("geoip lookup failed:", error?.message || error);
    return "";
  }
}

function sitePresenceSessionKey(value) {
  const cleaned = String(value || "").trim().toLowerCase().replace(/[^a-z0-9-]/g, "");
  return cleaned.length >= 8 && cleaned.length <= 64 ? cleaned : "";
}

exports.recordSiteVisit = onRequest({ region: "europe-west2", memory: "512MiB" }, async (req, res) => {
  const origin = String(req.headers.origin || "");
  if (SITE_STATS_ALLOWED_ORIGINS.has(origin)) {
    res.set("Access-Control-Allow-Origin", origin);
    res.set("Access-Control-Allow-Methods", "POST, OPTIONS");
    res.set("Access-Control-Allow-Headers", "Content-Type");
  }
  if (req.method === "OPTIONS") {
    res.status(204).send("");
    return;
  }

  try {
    if (req.method !== "POST") {
      res.status(200).json({ ok: true, message: "Site stats beacon. Use POST." });
      return;
    }

    const userAgent = String(req.headers["user-agent"] || "");
    if (/bot|crawl|spider|preview|lighthouse|headless/i.test(userAgent)) {
      res.status(200).json({ ok: true, skipped: "bot" });
      return;
    }

    const body = typeof req.body === "string" ? JSON.parse(req.body || "{}") : (req.body || {});

    // Heartbeat beacons keep the "on site now" presence list fresh. They write
    // a single per-session doc (random session id, reset every browser session)
    // and add nothing to the daily counters.
    if (body.kind === "heartbeat") {
      const sessionKey = sitePresenceSessionKey(body.sessionId);
      if (sessionKey) {
        // scope "app" = signed-in product usage (web app, Mac, iOS, Android);
        // default scope = anonymous public-site visitors.
        const isApp = body.scope === "app";
        const platform = ["web", "mac", "ios", "android"].includes(body.platform) ? body.platform : "web";
        await admin.firestore().collection(isApp ? "appPresence" : "sitePresence").doc(sessionKey).set({
          lastSeenAt: admin.firestore.FieldValue.serverTimestamp(),
          path: siteStatsFieldKey(body.path, "unknown"),
          ...(isApp ? { platform } : {})
        }, { merge: true });
      }
      res.status(200).json({ ok: true });
      return;
    }

    // Duration beacons (sent on page hide) only add watch-time seconds.
    if (body.kind === "duration") {
      const seconds = Math.min(Math.max(Math.round(Number(body.seconds) || 0), 0), 1800);
      if (seconds > 0) {
        await admin.firestore().collection("siteStats").doc(siteStatsDateKey()).set({
          durationSeconds: admin.firestore.FieldValue.increment(seconds),
          updatedAt: admin.firestore.FieldValue.serverTimestamp()
        }, { merge: true });
      }
      res.status(200).json({ ok: true });
      return;
    }

    // Custom Order landing-page events (/custom-order-management). Anonymous,
    // aggregate-only: one doc per day in customOrderLandingStats with simple
    // per-event counters (+ device/source maps on the view). No individual
    // event rows, no IP, no PII — same privacy model as the daily siteStats.
    if (body.kind === "landing") {
      const EVENT_FIELDS = {
        custom_order_landing_view: "views",
        custom_order_landing_cta_click: "ctaClicks",
        custom_order_landing_how_it_works_click: "howItWorksClicks",
        custom_order_landing_signup_visit: "signupVisits",
        custom_order_landing_signup_completed: "signupsCompleted",
        // Demo-video engagement: the ads landing page player and the homepage
        // hero modal report plays + watched-to-end through the same pipeline.
        custom_order_landing_demo_play: "demoPlays",
        custom_order_landing_demo_complete: "demoCompletes",
        homepage_demo_play: "homepageDemoPlays",
        homepage_demo_complete: "homepageDemoCompletes"
      };
      const landingField = EVENT_FIELDS[String(body.event || "")];
      if (landingField) {
        const landingInc = admin.firestore.FieldValue.increment(1);
        const landingUpdate = {
          [landingField]: landingInc,
          updatedAt: admin.firestore.FieldValue.serverTimestamp()
        };

        // Anonymous random visitor id → per-step de-dup maps. Stored only as an
        // opaque key so the read side can count UNIQUE visitors across the
        // window; these id maps are never returned to any browser. No email,
        // account, IP or fingerprint is involved.
        const landingVid = String(body.vid || "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 32);
        const VID_MAPS = {
          views: "viewVids",
          ctaClicks: "ctaVids",
          signupVisits: "signupVisitVids",
          signupsCompleted: "signupCompletedVids",
          demoPlays: "demoPlayVids",
          homepageDemoPlays: "homepageDemoPlayVids"
        };
        if (landingVid && VID_MAPS[landingField]) {
          landingUpdate[VID_MAPS[landingField]] = { [landingVid]: true };
        }

        // Campaign attribution (utm_source / utm_medium / utm_campaign) → a
        // per-campaign funnel counter map for the UTM breakdown table. Only
        // attribution labels are stored, never anything identifying a person.
        const landingCamp = body.campaign && typeof body.campaign === "object" ? body.campaign : null;
        const CAMP_FIELDS = {
          custom_order_landing_view: "views",
          custom_order_landing_cta_click: "ctaClicks",
          custom_order_landing_signup_visit: "signupVisits",
          custom_order_landing_signup_completed: "signupsCompleted"
        };
        const campField = CAMP_FIELDS[String(body.event || "")];
        if (landingCamp && campField) {
          const campSource = siteStatsFieldKey(String(landingCamp.source || "").toLowerCase(), "direct", 50);
          const campMedium = siteStatsFieldKey(String(landingCamp.medium || "").toLowerCase(), "none", 30);
          const campName = siteStatsFieldKey(String(landingCamp.campaign || "").toLowerCase(), "none", 60);
          const campKey = siteStatsFieldKey(`${campSource}_${campMedium}_${campName}`, "campaign", 120);
          landingUpdate.campaigns = {
            [campKey]: { source: campSource, medium: campMedium, campaign: campName, [campField]: landingInc }
          };
        }

        // Stricter signup metric: only when the visit immediately followed a CTA
        // click (the client flags ctaDriven within a short window).
        if (landingField === "signupVisits" && body.ctaDriven === true) {
          landingUpdate.ctaDrivenSignupVisits = landingInc;
        }

        // Device + source + utm term/content + referrer host describe the
        // visiting traffic — recorded on the view.
        if (landingField === "views") {
          const landingDevice = ["mobile", "tablet", "desktop"].includes(body.device) ? body.device : "desktop";
          const landingSource = siteStatsFieldKey(String(body.source || "").toLowerCase(), "direct", 40) || "direct";
          landingUpdate.devices = { [landingDevice]: landingInc };
          landingUpdate.sources = { [landingSource]: landingInc };
          if (landingCamp) {
            landingUpdate.utmTerms = { [siteStatsFieldKey(String(landingCamp.term || "").toLowerCase(), "none", 60)]: landingInc };
            landingUpdate.utmContents = { [siteStatsFieldKey(String(landingCamp.content || "").toLowerCase(), "none", 60)]: landingInc };
            landingUpdate.referrers = { [siteStatsFieldKey(String(landingCamp.referrerHost || "").toLowerCase(), "direct", 60)]: landingInc };
          }
        }

        await admin.firestore().collection("customOrderLandingStats").doc(siteStatsDateKey()).set(landingUpdate, { merge: true });
      }
      res.status(200).json({ ok: true });
      return;
    }

    const pageKey = siteStatsFieldKey(body.path, "unknown");
    const deviceKey = ["mobile", "tablet", "desktop"].includes(body.device) ? body.device : "desktop";
    // Browsers report either "tr" or "tr-TR" — keep only the base language so
    // the same language never splits into two rows.
    const languageKey = siteStatsFieldKey(String(body.language || "").split("-")[0].slice(0, 3), "unknown", 3);
    const newSession = body.newSession === true;
    const secondView = body.secondView === true;
    // Country comes from IP geolocation (the IP itself is never stored); the
    // browser-locale country is only a fallback when the lookup finds nothing.
    const localeCountryRaw = String(body.country || "").trim().toUpperCase();
    const geoCountry = lookupCountryFromIp(req);
    const countryRaw = geoCountry || localeCountryRaw;
    const countryKey = /^[A-Z]{2}$/.test(countryRaw) ? countryRaw : "";

    let referrerKey = "";
    if (newSession) {
      const rawReferrer = String(body.referrer || "").trim();
      if (!rawReferrer) {
        referrerKey = "direct";
      } else {
        try {
          const host = new URL(rawReferrer).hostname.replace(/^www\./, "");
          referrerKey = host.includes("nivadesk") ? "" : siteStatsFieldKey(host, "other", 60);
        } catch {
          referrerKey = "other";
        }
      }
    }

    const inc = admin.firestore.FieldValue.increment(1);
    const update = {
      total: inc,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      pages: { [pageKey]: inc },
      devices: { [deviceKey]: inc },
      languages: { [languageKey]: inc }
    };
    if (newSession) {
      update.sessions = inc;
      if (referrerKey) update.referrers = { [referrerKey]: inc };
      if (countryKey) update.countries = { [countryKey]: inc };
    }
    // A session's second page view marks it "engaged" (non-bounce). The client
    // sends this flag exactly once per session.
    if (secondView) {
      update.engagedSessions = inc;
    }

    await admin.firestore().collection("siteStats").doc(siteStatsDateKey()).set(update, { merge: true });

    // Page views also refresh presence so navigation shows up instantly.
    const presenceKey = sitePresenceSessionKey(body.sessionId);
    if (presenceKey) {
      await admin.firestore().collection("sitePresence").doc(presenceKey).set({
        lastSeenAt: admin.firestore.FieldValue.serverTimestamp(),
        path: pageKey
      }, { merge: true });
    }

    res.status(200).json({ ok: true });
  } catch (error) {
    console.error("recordSiteVisit error:", error?.message || error);
    res.status(200).json({ ok: false });
  }
});

// Admin-only aggregation for the /custom-order-management landing page. Reads
// the daily customOrderLandingStats counters and returns per-day rows + totals
// + device/source breakdowns. The dashboard derives CTR + conversion rates.
exports.getCustomOrderLandingStats = onCall({ region: "europe-west2" }, async (request) => {
  const email = String(request.auth?.token?.email || "").trim().toLowerCase();
  if (!request.auth || !SUPPORT_ADMIN_EMAILS.has(email)) {
    throw new HttpsError("permission-denied", "Landing-page statistics are restricted to NivaDesk admins.");
  }

  // Date selection: an explicit YYYY-MM-DD range, or a rolling N-day window
  // (mirrors getSiteStats so Today / Yesterday / 7 / 30 / custom all work).
  const MAX_SPAN_DAYS = 400;
  const dateKeys = [];
  const startRaw = String(request.data?.startDate || "").trim();
  const endRaw = String(request.data?.endDate || "").trim();
  const datePattern = /^\d{4}-\d{2}-\d{2}$/;
  if (datePattern.test(startRaw) && datePattern.test(endRaw)) {
    const startMs = Date.parse(`${startRaw}T12:00:00Z`);
    const endMs = Math.min(Date.parse(`${endRaw}T12:00:00Z`), Date.now());
    if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || startMs > endMs) {
      throw new HttpsError("invalid-argument", "Invalid date range.");
    }
    const span = Math.min(Math.round((endMs - startMs) / 86400000) + 1, MAX_SPAN_DAYS);
    for (let offset = span - 1; offset >= 0; offset -= 1) dateKeys.push(siteStatsDateKey(new Date(endMs - offset * 86400000)));
  } else {
    const days = Math.min(Math.max(Number(request.data?.days) || 30, 1), MAX_SPAN_DAYS);
    for (let offset = days - 1; offset >= 0; offset -= 1) dateKeys.push(siteStatsDateKey(new Date(Date.now() - offset * 86400000)));
  }

  // Soft reset: an admin can set a "report from" date so older (test) data is
  // hidden from the panel. No data is ever deleted — the days are just skipped.
  let reportFromDate = "";
  try {
    const cfgSnap = await admin.firestore().collection("customOrderLandingStats").doc("_config").get();
    reportFromDate = String((cfgSnap.exists ? cfgSnap.data() : {}).reportFromDate || "").trim();
  } catch {
    reportFromDate = "";
  }
  const effectiveKeys = datePattern.test(reportFromDate) ? dateKeys.filter((key) => key >= reportFromDate) : dateKeys;

  const refs = effectiveKeys.map((key) => admin.firestore().collection("customOrderLandingStats").doc(key));
  const snaps = refs.length ? await admin.firestore().getAll(...refs) : [];

  const num = (value) => (Number.isFinite(Number(value)) ? Number(value) : 0);
  const mergeInto = (target, source) => {
    for (const [key, value] of Object.entries(source || {})) target[key] = (target[key] || 0) + num(value);
  };

  const totals = { views: 0, ctaClicks: 0, howItWorksClicks: 0, signupVisits: 0, signupsCompleted: 0, ctaDrivenSignupVisits: 0, demoPlays: 0, demoCompletes: 0, homepageDemoPlays: 0, homepageDemoCompletes: 0 };
  const devices = {};
  const sources = {};
  const referrers = {};
  const utmTerms = {};
  const utmContents = {};
  // Window-unique counts: union of opaque visitor ids per funnel step. The ids
  // are used only here to size the Sets and are NEVER returned to the client.
  const uniqViews = new Set();
  const uniqCta = new Set();
  const uniqSignupVisit = new Set();
  const uniqSignupDone = new Set();
  const uniqDemoPlay = new Set();
  const uniqHomeDemoPlay = new Set();
  // Per-campaign funnel for the UTM breakdown table.
  const campaignAgg = {};

  const daysOut = snaps.map((snap, index) => {
    const data = snap.exists ? snap.data() : {};
    const viewVids = Object.keys(data.viewVids || {});
    const ctaVids = Object.keys(data.ctaVids || {});
    const svVids = Object.keys(data.signupVisitVids || {});
    const scVids = Object.keys(data.signupCompletedVids || {});
    const demoVids = Object.keys(data.demoPlayVids || {});
    const homeDemoVids = Object.keys(data.homepageDemoPlayVids || {});
    const day = {
      date: effectiveKeys[index],
      views: num(data.views),
      ctaClicks: num(data.ctaClicks),
      howItWorksClicks: num(data.howItWorksClicks),
      signupVisits: num(data.signupVisits),
      signupsCompleted: num(data.signupsCompleted),
      ctaDrivenSignupVisits: num(data.ctaDrivenSignupVisits),
      demoPlays: num(data.demoPlays),
      demoCompletes: num(data.demoCompletes),
      homepageDemoPlays: num(data.homepageDemoPlays),
      homepageDemoCompletes: num(data.homepageDemoCompletes),
      uniqueViews: viewVids.length,
      uniqueCtaClicks: ctaVids.length,
      uniqueSignupVisits: svVids.length,
      uniqueSignupsCompleted: scVids.length,
      uniqueDemoPlays: demoVids.length,
      uniqueHomepageDemoPlays: homeDemoVids.length
    };
    totals.views += day.views;
    totals.ctaClicks += day.ctaClicks;
    totals.howItWorksClicks += day.howItWorksClicks;
    totals.signupVisits += day.signupVisits;
    totals.signupsCompleted += day.signupsCompleted;
    totals.ctaDrivenSignupVisits += day.ctaDrivenSignupVisits;
    totals.demoPlays += day.demoPlays;
    totals.demoCompletes += day.demoCompletes;
    totals.homepageDemoPlays += day.homepageDemoPlays;
    totals.homepageDemoCompletes += day.homepageDemoCompletes;
    mergeInto(devices, data.devices);
    mergeInto(sources, data.sources);
    mergeInto(referrers, data.referrers);
    mergeInto(utmTerms, data.utmTerms);
    mergeInto(utmContents, data.utmContents);
    for (const v of viewVids) uniqViews.add(v);
    for (const v of ctaVids) uniqCta.add(v);
    for (const v of svVids) uniqSignupVisit.add(v);
    for (const v of scVids) uniqSignupDone.add(v);
    for (const v of demoVids) uniqDemoPlay.add(v);
    for (const v of homeDemoVids) uniqHomeDemoPlay.add(v);
    for (const [campKey, cv] of Object.entries(data.campaigns || {})) {
      const agg = campaignAgg[campKey] || (campaignAgg[campKey] = {
        source: String(cv.source || "direct"),
        medium: String(cv.medium || "none"),
        campaign: String(cv.campaign || "none"),
        views: 0, ctaClicks: 0, signupVisits: 0, signupsCompleted: 0
      });
      if (cv.source) agg.source = String(cv.source);
      if (cv.medium) agg.medium = String(cv.medium);
      if (cv.campaign) agg.campaign = String(cv.campaign);
      agg.views += num(cv.views);
      agg.ctaClicks += num(cv.ctaClicks);
      agg.signupVisits += num(cv.signupVisits);
      agg.signupsCompleted += num(cv.signupsCompleted);
    }
    return day; // raw visitor-id maps are intentionally not included
  });

  const unique = {
    views: uniqViews.size,
    ctaClicks: uniqCta.size,
    signupVisits: uniqSignupVisit.size,
    signupsCompleted: uniqSignupDone.size,
    demoPlays: uniqDemoPlay.size,
    homepageDemoPlays: uniqHomeDemoPlay.size
  };
  const campaigns = Object.values(campaignAgg).sort((a, b) => (b.views - a.views) || (b.ctaClicks - a.ctaClicks));

  return {
    ok: true,
    range: { start: effectiveKeys[0] || "", end: effectiveKeys[effectiveKeys.length - 1] || "" },
    reportFromDate,
    days: daysOut,
    totals,
    unique,
    devices,
    sources,
    referrers,
    utmTerms,
    utmContents,
    campaigns
  };
});

// Admin-only SOFT reset for the landing-page panel. Never deletes counters; it
// just sets (or clears) a "report from" date so the panel reports from that day
// onward — used to drop earlier test traffic. No email/identity is stored.
exports.resetCustomOrderLandingStats = onCall({ region: "europe-west2" }, async (request) => {
  const email = String(request.auth?.token?.email || "").trim().toLowerCase();
  if (!request.auth || !SUPPORT_ADMIN_EMAILS.has(email)) {
    throw new HttpsError("permission-denied", "Landing-page statistics are restricted to NivaDesk admins.");
  }
  const datePattern = /^\d{4}-\d{2}-\d{2}$/;
  const raw = String(request.data?.fromDate || "").trim().toLowerCase();
  let reportFromDate = "";
  if (raw && raw !== "clear") {
    reportFromDate = raw === "today" ? siteStatsDateKey() : raw;
    if (!datePattern.test(reportFromDate)) {
      throw new HttpsError("invalid-argument", "fromDate must be YYYY-MM-DD, 'today' or 'clear'.");
    }
  }
  await admin.firestore().collection("customOrderLandingStats").doc("_config").set({
    reportFromDate,
    reportFromUpdatedAt: admin.firestore.FieldValue.serverTimestamp()
  }, { merge: true });
  return { ok: true, reportFromDate };
});

exports.getSiteStats = onCall({ region: "europe-west2" }, async (request) => {
  const email = String(request.auth?.token?.email || "").trim().toLowerCase();
  if (!request.auth || !SUPPORT_ADMIN_EMAILS.has(email)) {
    throw new HttpsError("permission-denied", "Site statistics are restricted to NivaDesk admins.");
  }

  // Two request shapes:
  //  - { days: N }                  → last N days ending today
  //  - { startDate, endDate }       → explicit YYYY-MM-DD range (inclusive)
  // Either way the span is capped at 800 days to bound Firestore reads; a
  // client wanting trend comparison simply requests a window twice as long.
  const MAX_SPAN_DAYS = 800;
  const dateKeys = [];
  const startRaw = String(request.data?.startDate || "").trim();
  const endRaw = String(request.data?.endDate || "").trim();
  const datePattern = /^\d{4}-\d{2}-\d{2}$/;

  if (datePattern.test(startRaw) && datePattern.test(endRaw)) {
    const startMs = Date.parse(`${startRaw}T12:00:00Z`);
    const endMs = Math.min(Date.parse(`${endRaw}T12:00:00Z`), Date.now());
    if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || startMs > endMs) {
      throw new HttpsError("invalid-argument", "Invalid date range.");
    }
    const span = Math.min(Math.round((endMs - startMs) / 86400000) + 1, MAX_SPAN_DAYS);
    for (let offset = span - 1; offset >= 0; offset -= 1) {
      dateKeys.push(siteStatsDateKey(new Date(endMs - offset * 86400000)));
    }
  } else {
    const days = Math.min(Math.max(Number(request.data?.days) || 30, 1), MAX_SPAN_DAYS);
    for (let offset = days - 1; offset >= 0; offset -= 1) {
      dateKeys.push(siteStatsDateKey(new Date(Date.now() - offset * 86400000)));
    }
  }

  const refs = dateKeys.map((key) => admin.firestore().collection("siteStats").doc(key));
  const snaps = await admin.firestore().getAll(...refs);

  // Older docs stored full locale tags ("tr-tr"); fold them into the base
  // language ("tr") so the same language never shows as two rows.
  const normalizeLanguages = (languages = {}) => {
    const merged = {};
    for (const [key, value] of Object.entries(languages)) {
      const base = String(key).split(/[-_]/)[0].slice(0, 3) || "unknown";
      merged[base] = (merged[base] || 0) + Number(value || 0);
    }
    return merged;
  };

  const daysOut = snaps.map((snap, index) => {
    const data = snap.exists ? snap.data() : {};
    return {
      date: dateKeys[index],
      total: Number(data.total || 0),
      sessions: Number(data.sessions || 0),
      engagedSessions: Number(data.engagedSessions || 0),
      durationSeconds: Number(data.durationSeconds || 0),
      pages: data.pages || {},
      devices: data.devices || {},
      languages: normalizeLanguages(data.languages),
      referrers: data.referrers || {},
      countries: data.countries || {}
    };
  });

  return { ok: true, isSupportAdmin: true, days: daysOut };
});

exports.getSitePresence = onCall({ region: "europe-west2" }, async (request) => {
  const email = String(request.auth?.token?.email || "").trim().toLowerCase();
  if (!request.auth || !SUPPORT_ADMIN_EMAILS.has(email)) {
    throw new HttpsError("permission-denied", "Site statistics are restricted to NivaDesk admins.");
  }

  const now = Date.now();
  const activeCutoff = admin.firestore.Timestamp.fromMillis(now - 2 * 60 * 1000);
  const snap = await admin.firestore()
    .collection("sitePresence")
    .where("lastSeenAt", ">=", activeCutoff)
    .limit(500)
    .get();

  const pages = {};
  snap.docs.forEach((doc) => {
    const path = String(doc.data()?.path || "unknown");
    pages[path] = (pages[path] || 0) + 1;
  });

  // Opportunistic cleanup: drop sessions idle for more than 15 minutes.
  try {
    const staleCutoff = admin.firestore.Timestamp.fromMillis(now - 15 * 60 * 1000);
    const staleSnap = await admin.firestore()
      .collection("sitePresence")
      .where("lastSeenAt", "<", staleCutoff)
      .limit(100)
      .get();
    if (!staleSnap.empty) {
      const batch = admin.firestore().batch();
      staleSnap.docs.forEach((doc) => batch.delete(doc.ref));
      await batch.commit();
    }
  } catch (error) {
    console.warn("sitePresence cleanup failed:", error?.message || error);
  }

  // In-app presence (signed-in users across web app, Mac, iOS, Android).
  let appActive = 0;
  const appPlatforms = {};
  try {
    const appSnap = await admin.firestore()
      .collection("appPresence")
      .where("lastSeenAt", ">=", activeCutoff)
      .limit(500)
      .get();
    appActive = appSnap.size;
    appSnap.docs.forEach((doc) => {
      const platform = String(doc.data()?.platform || "web");
      appPlatforms[platform] = (appPlatforms[platform] || 0) + 1;
    });
    const staleCutoff = admin.firestore.Timestamp.fromMillis(now - 15 * 60 * 1000);
    const staleSnap = await admin.firestore()
      .collection("appPresence")
      .where("lastSeenAt", "<", staleCutoff)
      .limit(100)
      .get();
    if (!staleSnap.empty) {
      const batch = admin.firestore().batch();
      staleSnap.docs.forEach((doc) => batch.delete(doc.ref));
      await batch.commit();
    }
  } catch (error) {
    console.warn("appPresence failed:", error?.message || error);
  }

  return {
    ok: true,
    active: snap.size,
    pages: Object.entries(pages)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8)
      .map(([path, count]) => ({ path, count })),
    app: { active: appActive, platforms: appPlatforms }
  };
});

// ---------------------------------------------------------------------------
// Google Search Console — admin-only search-performance panel.
// Pulls real query-level data (impressions, clicks, CTR, average position) from
// the Search Analytics API for nivadesk.app, plus the change vs the previous
// equal-length period so admins can see how rankings shifted day over day.
// Uses the function's own runtime service account (ADC, webmasters.readonly
// scope); that service account must be added as a user on the Search Console
// property. Google strips search terms from referrers ("not provided"), so this
// API is the only source for "what people searched and where we ranked".
// ---------------------------------------------------------------------------

const NV_GSC_PROPERTY_DOMAIN = "nivadesk.app";

// Best-effort: read the function's own runtime service-account email from the
// GCP metadata server so the UI can tell the admin exactly which account to add
// in Search Console (needed before any access has been granted).
async function nvDetectRuntimeServiceAccountEmail() {
  try {
    const res = await fetch(
      "http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/email",
      { headers: { "Metadata-Flavor": "Google" } }
    );
    if (res.ok) return (await res.text()).trim();
  } catch (error) {
    console.warn("GSC: could not read runtime SA email:", error?.message || error);
  }
  return "";
}

// Pick the nivadesk.app property the service account can see. Prefer the Domain
// property (sc-domain:), then the https URL-prefix, then any matching entry.
function nvPickSearchConsoleProperty(siteEntries = []) {
  const urls = siteEntries.map((s) => String(s.siteUrl || "")).filter(Boolean);
  return (
    urls.find((u) => u === `sc-domain:${NV_GSC_PROPERTY_DOMAIN}`) ||
    urls.find((u) => u === `https://${NV_GSC_PROPERTY_DOMAIN}/`) ||
    urls.find((u) => u.includes(NV_GSC_PROPERTY_DOMAIN)) ||
    ""
  );
}

exports.getSearchConsoleStats = onCall({ region: "europe-west2", timeoutSeconds: 120 }, async (request) => {
  const email = String(request.auth?.token?.email || "").trim().toLowerCase();
  if (!request.auth || !SUPPORT_ADMIN_EMAILS.has(email)) {
    throw new HttpsError("permission-denied", "Search statistics are restricted to NivaDesk admins.");
  }

  const { google } = require("googleapis");
  const serviceAccountEmail = await nvDetectRuntimeServiceAccountEmail();

  // Auth + client.
  let searchconsole;
  try {
    const auth = new google.auth.GoogleAuth({
      scopes: ["https://www.googleapis.com/auth/webmasters.readonly"]
    });
    const authClient = await auth.getClient();
    searchconsole = google.searchconsole({ version: "v1", auth: authClient });
  } catch (error) {
    return { ok: false, needsAccess: true, serviceAccountEmail, message: `Auth init failed: ${error?.message || error}` };
  }

  // Resolve which property this service account can read. A clear "needsAccess"
  // response drives the setup card in the UI (enable API / add SA / verify).
  let property = "";
  let accessibleSites = [];
  try {
    const sitesRes = await searchconsole.sites.list();
    const entries = sitesRes.data?.siteEntry || [];
    accessibleSites = entries.map((s) => String(s.siteUrl || "")).filter(Boolean);
    property = nvPickSearchConsoleProperty(entries);
  } catch (error) {
    return {
      ok: false,
      needsAccess: true,
      serviceAccountEmail,
      accessibleSites,
      message: `Could not list Search Console sites: ${error?.errors?.[0]?.message || error?.message || error}`
    };
  }
  if (!property) {
    return {
      ok: false,
      needsAccess: true,
      serviceAccountEmail,
      accessibleSites,
      message: `The service account has no access to ${NV_GSC_PROPERTY_DOMAIN}. Add it as a user in Search Console.`
    };
  }

  // Date window: current = [startDate, endDate]; previous = equal-length window
  // immediately before. GSC data lags ~2-3 days, so default end = 3 days ago.
  const datePattern = /^\d{4}-\d{2}-\d{2}$/;
  let endRaw = String(request.data?.endDate || "").trim();
  let startRaw = String(request.data?.startDate || "").trim();
  if (!datePattern.test(endRaw)) {
    endRaw = new Date(Date.now() - 3 * 86400000).toISOString().slice(0, 10);
  }
  if (!datePattern.test(startRaw)) {
    startRaw = new Date(Date.parse(`${endRaw}T12:00:00Z`) - 27 * 86400000).toISOString().slice(0, 10);
  }
  const curStartMs = Date.parse(`${startRaw}T12:00:00Z`);
  const curEndMs = Date.parse(`${endRaw}T12:00:00Z`);
  if (!Number.isFinite(curStartMs) || !Number.isFinite(curEndMs) || curStartMs > curEndMs) {
    throw new HttpsError("invalid-argument", "Invalid date range.");
  }
  const spanDays = Math.round((curEndMs - curStartMs) / 86400000) + 1;
  const prevEndMs = curStartMs - 86400000;
  const prevStartMs = prevEndMs - (spanDays - 1) * 86400000;
  const fmt = (ms) => new Date(ms).toISOString().slice(0, 10);

  const queryPeriod = async (startDate, endDate, dimensions, rowLimit) => {
    const res = await searchconsole.searchanalytics.query({
      siteUrl: property,
      requestBody: { startDate, endDate, dimensions, rowLimit, dataState: "all" }
    });
    return res.data?.rows || [];
  };

  let curRows = [];
  let prevRows = [];
  let curTotalRows = [];
  let prevTotalRows = [];
  let dateRows = [];
  let pageRows = [];
  let countryRows = [];
  let deviceRows = [];
  try {
    [curRows, prevRows, curTotalRows, prevTotalRows, dateRows, pageRows, countryRows, deviceRows] = await Promise.all([
      queryPeriod(startRaw, endRaw, ["query"], 100),
      queryPeriod(fmt(prevStartMs), fmt(prevEndMs), ["query"], 1000),
      queryPeriod(startRaw, endRaw, [], 1),
      queryPeriod(fmt(prevStartMs), fmt(prevEndMs), [], 1),
      queryPeriod(startRaw, endRaw, ["date"], 1000),
      queryPeriod(startRaw, endRaw, ["page"], 50),
      queryPeriod(startRaw, endRaw, ["country"], 20),
      queryPeriod(startRaw, endRaw, ["device"], 5)
    ]);
  } catch (error) {
    return {
      ok: false,
      needsAccess: false,
      serviceAccountEmail,
      property,
      message: `Search Analytics query failed: ${error?.errors?.[0]?.message || error?.message || error}`
    };
  }

  const prevByQuery = new Map();
  prevRows.forEach((r) => prevByQuery.set(String(r.keys?.[0] || ""), r));

  const queries = curRows.map((r) => {
    const q = String(r.keys?.[0] || "");
    const prev = prevByQuery.get(q);
    const position = Number(r.position || 0);
    const prevPosition = prev ? Number(prev.position || 0) : null;
    return {
      query: q,
      clicks: Number(r.clicks || 0),
      impressions: Number(r.impressions || 0),
      ctr: Number(r.ctr || 0),
      position,
      prevPosition,
      // positionDelta > 0 means the average rank improved (moved toward #1),
      // since a smaller position number is better. The UI shows ▲ green for >0.
      positionDelta: prevPosition != null ? prevPosition - position : null,
      impressionsDelta: prev ? Number(r.impressions || 0) - Number(prev.impressions || 0) : null,
      isNew: !prev
    };
  });

  const totalsRow = (rows) => {
    const row = rows[0] || {};
    return {
      clicks: Number(row.clicks || 0),
      impressions: Number(row.impressions || 0),
      ctr: Number(row.ctr || 0),
      position: Number(row.position || 0)
    };
  };

  const byDate = (dateRows || [])
    .map((r) => ({
      date: String(r.keys?.[0] || ""),
      clicks: Number(r.clicks || 0),
      impressions: Number(r.impressions || 0),
      ctr: Number(r.ctr || 0),
      position: Number(r.position || 0)
    }))
    .sort((a, b) => a.date.localeCompare(b.date));

  const pages = (pageRows || []).map((r) => ({
    page: String(r.keys?.[0] || ""),
    clicks: Number(r.clicks || 0),
    impressions: Number(r.impressions || 0),
    ctr: Number(r.ctr || 0),
    position: Number(r.position || 0)
  }));

  // GSC returns ISO-3166-1 alpha-3 country codes (e.g. "gbr"); uppercase them.
  const countries = (countryRows || []).map((r) => ({
    country: String(r.keys?.[0] || "").toUpperCase(),
    clicks: Number(r.clicks || 0),
    impressions: Number(r.impressions || 0)
  }));

  const devices = (deviceRows || []).map((r) => ({
    device: String(r.keys?.[0] || ""), // DESKTOP | MOBILE | TABLET
    clicks: Number(r.clicks || 0),
    impressions: Number(r.impressions || 0)
  }));

  return {
    ok: true,
    property,
    serviceAccountEmail,
    range: { startDate: startRaw, endDate: endRaw },
    previousRange: { startDate: fmt(prevStartMs), endDate: fmt(prevEndMs) },
    totals: { current: totalsRow(curTotalRows), previous: totalsRow(prevTotalRows) },
    queries,
    byDate,
    pages,
    countries,
    devices
  };
});

// Daily snapshot: persist Search Console totals per day so we keep history
// beyond GSC's ~16-month window for long-term trends. Each run upserts the last
// ~10 days because GSC data keeps finalizing for ~3 days after the fact.
exports.snapshotSearchConsoleDaily = onSchedule(
  { schedule: "every 24 hours", timeZone: "Europe/London", region: "europe-west2" },
  async () => {
    const { google } = require("googleapis");
    let searchconsole;
    let property = "";
    try {
      const auth = new google.auth.GoogleAuth({
        scopes: ["https://www.googleapis.com/auth/webmasters.readonly"]
      });
      const authClient = await auth.getClient();
      searchconsole = google.searchconsole({ version: "v1", auth: authClient });
      const sitesRes = await searchconsole.sites.list();
      property = nvPickSearchConsoleProperty(sitesRes.data?.siteEntry || []);
    } catch (error) {
      console.warn("snapshotSearchConsoleDaily: GSC access not ready:", error?.message || error);
      return;
    }
    if (!property) {
      console.warn("snapshotSearchConsoleDaily: no nivadesk.app property accessible yet.");
      return;
    }

    const endMs = Date.now() - 3 * 86400000; // GSC ~3-day finalization lag
    const startMs = endMs - 9 * 86400000;
    const fmt = (ms) => new Date(ms).toISOString().slice(0, 10);
    let rows = [];
    try {
      const res = await searchconsole.searchanalytics.query({
        siteUrl: property,
        requestBody: { startDate: fmt(startMs), endDate: fmt(endMs), dimensions: ["date"], rowLimit: 1000, dataState: "all" }
      });
      rows = res.data?.rows || [];
    } catch (error) {
      console.warn("snapshotSearchConsoleDaily: query failed:", error?.message || error);
      return;
    }

    const batch = admin.firestore().batch();
    let written = 0;
    for (const r of rows) {
      const date = String(r.keys?.[0] || "");
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) continue;
      const ref = admin.firestore().collection("searchConsoleDaily").doc(date);
      batch.set(ref, {
        date,
        clicks: Number(r.clicks || 0),
        impressions: Number(r.impressions || 0),
        ctr: Number(r.ctr || 0),
        position: Number(r.position || 0),
        property,
        updatedAt: admin.firestore.FieldValue.serverTimestamp()
      }, { merge: true });
      written += 1;
    }
    if (written > 0) await batch.commit();
    console.log(`snapshotSearchConsoleDaily: stored ${written} day(s) for ${property}.`);
  }
);

// ---------------------------------------------------------------------------
// Admin Insights — cross-workspace overview for NivaDesk admins only.
// Aggregates real Firestore data (counts + company docs). Revenue figures are
// ESTIMATES derived from plan assignments; live billing is not connected.
// ---------------------------------------------------------------------------

const ADMIN_PLAN_MONTHLY_GBP = { lifetime_lite: 9, pro_monthly: 19, team_monthly: 49 };

exports.getAdminInsights = onCall({ region: "europe-west2", timeoutSeconds: 120 }, async (request) => {
  const email = String(request.auth?.token?.email || "").trim().toLowerCase();
  if (!request.auth || !SUPPORT_ADMIN_EMAILS.has(email)) {
    throw new HttpsError("permission-denied", "Admin insights are restricted to NivaDesk admins.");
  }

  const db = admin.firestore();
  const now = Date.now();
  const days30Ago = admin.firestore.Timestamp.fromMillis(now - 30 * 86400000);
  const monthStart = new Date();
  monthStart.setDate(1);
  monthStart.setHours(0, 0, 0, 0);
  const monthStartTs = admin.firestore.Timestamp.fromDate(monthStart);

  // --- Workspaces: read company docs once (small collection) and aggregate.
  const companiesSnap = await db.collection("companies").limit(3000).get();
  const planCounts = { demo: 0, lifetime_lite: 0, pro_monthly: 0, team_monthly: 0 };
  let newWorkspaces30d = 0;
  const newestWorkspaces = [];
  companiesSnap.docs.forEach((doc) => {
    const data = doc.data() || {};
    const plan = normalizeBillingPlan(data.billingPlan, "demo");
    planCounts[plan] = (planCounts[plan] || 0) + 1;
    const createdMs = data.createdAt && typeof data.createdAt.toMillis === "function" ? data.createdAt.toMillis() : 0;
    if (createdMs >= now - 30 * 86400000) newWorkspaces30d += 1;
    newestWorkspaces.push({
      id: doc.id,
      name: String(data.name || data.companyName || doc.id).slice(0, 60),
      plan,
      createdAtMs: createdMs
    });
  });
  newestWorkspaces.sort((a, b) => b.createdAtMs - a.createdAtMs);

  const paidWorkspaces = planCounts.lifetime_lite + planCounts.pro_monthly + planCounts.team_monthly;
  const estimatedMrr =
    planCounts.lifetime_lite * ADMIN_PLAN_MONTHLY_GBP.lifetime_lite +
    planCounts.pro_monthly * ADMIN_PLAN_MONTHLY_GBP.pro_monthly +
    planCounts.team_monthly * ADMIN_PLAN_MONTHLY_GBP.team_monthly;

  // --- Users (Firebase Auth, paginated; fine at current scale).
  let totalUsers = 0;
  let newUsers30d = 0;
  try {
    let pageToken = undefined;
    let pages = 0;
    do {
      const page = await admin.auth().listUsers(1000, pageToken);
      totalUsers += page.users.length;
      page.users.forEach((user) => {
        const created = Date.parse(user.metadata?.creationTime || "");
        if (Number.isFinite(created) && created >= now - 30 * 86400000) newUsers30d += 1;
      });
      pageToken = page.pageToken;
      pages += 1;
    } while (pageToken && pages < 20);
  } catch (error) {
    console.warn("getAdminInsights listUsers failed:", error?.message || error);
  }

  // --- Usage totals via Firestore count() aggregations (cheap).
  const countOf = async (query) => {
    try {
      const snap = await query.count().get();
      return Number(snap.data().count || 0);
    } catch (error) {
      console.warn("getAdminInsights count failed:", error?.message || error);
      return null;
    }
  };

  const [
    ordersTotal,
    ordersThisMonth,
    customersTotal,
    notesTotal,
    remindersTotal,
    messagesTotal,
    workspaceTicketsTotal,
    supportOpen,
    supportInProgress,
    supportTotal
  ] = await Promise.all([
    countOf(db.collection("siparisler")),
    countOf(db.collection("siparisler").where("createdAt", ">=", monthStartTs)),
    countOf(db.collection("musteriler")),
    // Real notes live at companies/{c}/personal_notes/{u}/notes — a root
    // "notes" query counted an empty collection and always reported 0.
    countOf(db.collectionGroup("notes")),
    countOf(db.collectionGroup("notes").where("reminderDate", ">", admin.firestore.Timestamp.fromMillis(0))),
    countOf(db.collection("messages")),
    countOf(db.collection("workspaceTickets")),
    countOf(db.collection("supportTickets").where("status", "==", "open")),
    countOf(db.collection("supportTickets").where("status", "==", "inProgress")),
    countOf(db.collection("supportTickets"))
  ]);

  // --- Active workspaces (any order created in the last 30 days) and paid
  // workspaces with no recent activity (attention list).
  let activeWorkspaces30d = 0;
  let inactivePaidWorkspaces = [];
  try {
    const recentOrdersSnap = await db.collection("siparisler")
      .where("createdAt", ">=", days30Ago)
      .select("companyId")
      .limit(5000)
      .get();
    const activeIds = new Set();
    recentOrdersSnap.docs.forEach((doc) => {
      const id = String(doc.data()?.companyId || "");
      if (id) activeIds.add(id);
    });
    activeWorkspaces30d = activeIds.size;
    inactivePaidWorkspaces = newestWorkspaces
      .filter((workspace) => workspace.plan !== "demo" && !activeIds.has(workspace.id))
      .slice(0, 8)
      .map(({ id, name, plan }) => ({ id, name, plan }));
  } catch (error) {
    console.warn("getAdminInsights active workspaces failed:", error?.message || error);
  }

  // --- Service heartbeat: timestamps of the most recent real activity.
  const latestTimestamp = async (query, field) => {
    try {
      const snap = await query.limit(1).get();
      const value = snap.docs[0]?.data()?.[field];
      return value && typeof value.toMillis === "function" ? value.toMillis() : null;
    } catch (error) {
      console.warn("getAdminInsights heartbeat failed:", error?.message || error);
      return null;
    }
  };
  const [lastOrderAtMs, lastSupportAtMs, lastSiteBeaconAtMs] = await Promise.all([
    latestTimestamp(db.collection("siparisler").orderBy("createdAt", "desc"), "createdAt"),
    latestTimestamp(db.collection("supportTickets").orderBy("createdAt", "desc"), "createdAt"),
    db.collection("siteStats").doc(siteStatsDateKey()).get().then((snap) => {
      const value = snap.exists ? snap.data()?.updatedAt : null;
      return value && typeof value.toMillis === "function" ? value.toMillis() : null;
    }).catch(() => null)
  ]);

  // --- ChatGPT app: distinct workspaces with a non-revoked OAuth token.
  let chatgptConnectedWorkspaces = 0;
  let chatgptActiveTokens = 0;
  let chatgptTokens30d = 0;
  try {
    const tokensSnap = await db.collection("chatgptOAuthTokens").limit(2000).get();
    const connected = new Set();
    tokensSnap.docs.forEach((doc) => {
      const data = doc.data() || {};
      if (Number(data.createdAtMs || 0) >= now - 30 * 86400000) chatgptTokens30d += 1;
      if (Number(data.revokedAtMs || 0) > 0) return;
      chatgptActiveTokens += 1;
      if (data.companyId) connected.add(String(data.companyId));
    });
    chatgptConnectedWorkspaces = connected.size;
  } catch (error) {
    console.warn("getAdminInsights chatgpt tokens failed:", error?.message || error);
  }

  // --- Public site pulse (today) + live presence.
  let siteToday = { total: 0, sessions: 0 };
  try {
    const todaySnap = await db.collection("siteStats").doc(siteStatsDateKey()).get();
    const data = todaySnap.exists ? todaySnap.data() : {};
    siteToday = { total: Number(data.total || 0), sessions: Number(data.sessions || 0) };
  } catch (error) {
    console.warn("getAdminInsights siteStats failed:", error?.message || error);
  }
  let liveVisitors = 0;
  let appNow = 0;
  const appPlatforms = {};
  try {
    const cutoff = admin.firestore.Timestamp.fromMillis(now - 2 * 60 * 1000);
    const presenceSnap = await db.collection("sitePresence").where("lastSeenAt", ">=", cutoff).limit(500).get();
    liveVisitors = presenceSnap.size;
    const appSnap = await db.collection("appPresence").where("lastSeenAt", ">=", cutoff).limit(500).get();
    appNow = appSnap.size;
    appSnap.docs.forEach((doc) => {
      const platform = String(doc.data()?.platform || "web");
      appPlatforms[platform] = (appPlatforms[platform] || 0) + 1;
    });
  } catch (error) {
    console.warn("getAdminInsights presence failed:", error?.message || error);
  }

  return {
    ok: true,
    generatedAtMs: now,
    users: { total: totalUsers, new30d: newUsers30d },
    workspaces: {
      total: companiesSnap.size,
      new30d: newWorkspaces30d,
      active30d: activeWorkspaces30d,
      paid: paidWorkspaces,
      planCounts,
      newest: newestWorkspaces.slice(0, 6).map(({ id, name, plan, createdAtMs }) => ({ id, name, plan, createdAtMs }))
    },
    revenue: {
      estimated: true,
      currency: "GBP",
      mrr: estimatedMrr,
      arr: estimatedMrr * 12,
      note: "Estimated from plan assignments; live billing is not connected."
    },
    usage: {
      ordersTotal,
      ordersThisMonth,
      customersTotal,
      notesTotal,
      remindersTotal,
      messagesTotal,
      workspaceTicketsTotal
    },
    support: {
      open: supportOpen,
      inProgress: supportInProgress,
      total: supportTotal
    },
    chatgpt: {
      connectedWorkspaces: chatgptConnectedWorkspaces,
      activeTokens: chatgptActiveTokens,
      tokens30d: chatgptTokens30d
    },
    attention: {
      inactivePaidWorkspaces
    },
    heartbeat: {
      lastOrderAtMs,
      lastSupportAtMs,
      lastSiteBeaconAtMs
    },
    site: {
      today: siteToday,
      liveVisitors,
      appNow,
      appPlatforms
    }
  };
});

// ---------------------------------------------------------------------------
// Admin Insights detail: Users & Workspaces
// ---------------------------------------------------------------------------

exports.getAdminUsersWorkspacesDetail = onCall({ region: "europe-west2", timeoutSeconds: 120 }, async (request) => {
  const email = String(request.auth?.token?.email || "").trim().toLowerCase();
  if (!request.auth || !SUPPORT_ADMIN_EMAILS.has(email)) {
    throw new HttpsError("permission-denied", "Admin insights are restricted to NivaDesk admins.");
  }

  const db = admin.firestore();
  const now = Date.now();
  const dayMs = 86400000;
  const windowDays = 60;
  const windowStartMs = now - (windowDays - 1) * dayMs;
  const londonDateKey = (ms) => new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/London" }).format(new Date(ms));

  // --- Firebase Auth scan: totals, activity and daily signup buckets.
  let totalUsers = 0;
  let new7d = 0;
  let new30d = 0;
  let active7d = 0;
  let active30d = 0;
  let neverLoggedIn = 0;
  let createdBeforeWindow = 0;
  const signupsByDay = {};
  const recentUsersAll = [];
  try {
    let pageToken = undefined;
    let pages = 0;
    do {
      const page = await admin.auth().listUsers(1000, pageToken);
      totalUsers += page.users.length;
      page.users.forEach((user) => {
        const created = Date.parse(user.metadata?.creationTime || "");
        const lastSignIn = Date.parse(user.metadata?.lastSignInTime || "");
        if (Number.isFinite(created)) {
          if (created >= now - 7 * dayMs) new7d += 1;
          if (created >= now - 30 * dayMs) new30d += 1;
          if (created >= windowStartMs) {
            const key = londonDateKey(created);
            signupsByDay[key] = (signupsByDay[key] || 0) + 1;
          } else {
            createdBeforeWindow += 1;
          }
        }
        if (Number.isFinite(lastSignIn)) {
          if (lastSignIn >= now - 7 * dayMs) active7d += 1;
          if (lastSignIn >= now - 30 * dayMs) active30d += 1;
        } else {
          neverLoggedIn += 1;
        }
        recentUsersAll.push({
          uid: user.uid,
          email: user.email || "",
          displayName: user.displayName || "",
          createdAtMs: Number.isFinite(created) ? created : 0,
          lastSignInMs: Number.isFinite(lastSignIn) ? lastSignIn : 0
        });
      });
      pageToken = page.pageToken;
      pages += 1;
    } while (pageToken && pages < 20);
  } catch (error) {
    console.warn("usersDetail listUsers failed:", error?.message || error);
  }

  const growth = [];
  let cumulative = createdBeforeWindow;
  for (let offset = windowDays - 1; offset >= 0; offset -= 1) {
    const key = londonDateKey(now - offset * dayMs);
    const signups = signupsByDay[key] || 0;
    cumulative += signups;
    growth.push({ date: key, signups, cumulative });
  }

  // --- Companies (single read) for names, plans and owners.
  const companiesSnap = await db.collection("companies").limit(3000).get();
  const companyInfo = new Map();
  const planCounts = { demo: 0, lifetime_lite: 0, pro_monthly: 0, team_monthly: 0 };
  companiesSnap.docs.forEach((doc) => {
    const data = doc.data() || {};
    const plan = normalizeBillingPlan(data.billingPlan, "demo");
    planCounts[plan] = (planCounts[plan] || 0) + 1;
    companyInfo.set(doc.id, {
      name: String(data.name || data.companyName || doc.id).slice(0, 60),
      ownerEmail: String(data.ownerEmail || data.email || "").slice(0, 80),
      plan
    });
  });

  // --- Orders in the last 30 days: active workspaces, top list and heatmap.
  const heatmap = Array.from({ length: 7 }, () => Array(24).fill(0));
  const ordersByCompany = new Map();
  const lastOrderByCompany = new Map();
  try {
    const recentSnap = await db.collection("siparisler")
      .where("createdAt", ">=", admin.firestore.Timestamp.fromMillis(now - 30 * dayMs))
      .select("companyId", "createdAt")
      .limit(8000)
      .get();
    const hourFmt = new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/London", hour: "2-digit", hour12: false });
    const weekdayFmt = new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/London", weekday: "short" });
    const weekdayIndex = { Mon: 0, Tue: 1, Wed: 2, Thu: 3, Fri: 4, Sat: 5, Sun: 6 };
    recentSnap.docs.forEach((doc) => {
      const data = doc.data() || {};
      const companyId = String(data.companyId || "");
      const createdMs = data.createdAt && typeof data.createdAt.toMillis === "function" ? data.createdAt.toMillis() : 0;
      if (companyId) {
        ordersByCompany.set(companyId, (ordersByCompany.get(companyId) || 0) + 1);
        if (createdMs > (lastOrderByCompany.get(companyId) || 0)) lastOrderByCompany.set(companyId, createdMs);
      }
      if (createdMs > 0) {
        const date = new Date(createdMs);
        const day = weekdayIndex[weekdayFmt.format(date)] ?? 0;
        const hour = Math.min(Math.max(parseInt(hourFmt.format(date), 10) || 0, 0), 23);
        heatmap[day][hour] += 1;
      }
    });
  } catch (error) {
    console.warn("usersDetail recent orders failed:", error?.message || error);
  }

  const activeWorkspaces = ordersByCompany.size;

  // --- Top workspaces by recent activity, enriched with totals and members.
  const topIds = Array.from(ordersByCompany.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, 8)
    .map(([id]) => id);
  const topWorkspaces = await Promise.all(topIds.map(async (id) => {
    const info = companyInfo.get(id) || { name: id, ownerEmail: "", plan: "demo" };
    let ordersTotal = null;
    let members = null;
    try {
      const snap = await db.collection("siparisler").where("companyId", "==", id).count().get();
      ordersTotal = Number(snap.data().count || 0);
    } catch (error) {
      console.warn("usersDetail orders count failed:", error?.message || error);
    }
    try {
      const snap = await db.collection("companies").doc(id).collection("users").count().get();
      members = Number(snap.data().count || 0);
    } catch (error) {
      console.warn("usersDetail members count failed:", error?.message || error);
    }
    return {
      id,
      name: info.name,
      ownerEmail: info.ownerEmail,
      plan: info.plan,
      members,
      orders30d: ordersByCompany.get(id) || 0,
      ordersTotal,
      lastOrderAtMs: lastOrderByCompany.get(id) || 0
    };
  }));

  // --- Multi-workspace users via the workspaceAccess subcollections.
  let usersWithMultipleWorkspaces = 0;
  try {
    const accessSnap = await db.collectionGroup("workspaceAccess").select().limit(10000).get();
    const perUser = new Map();
    accessSnap.docs.forEach((doc) => {
      const uid = doc.ref.parent.parent?.id || "";
      if (uid) perUser.set(uid, (perUser.get(uid) || 0) + 1);
    });
    perUser.forEach((count) => {
      if (count > 1) usersWithMultipleWorkspaces += 1;
    });
  } catch (error) {
    console.warn("usersDetail workspaceAccess failed:", error?.message || error);
  }

  // Best plan per owner email (for showing each user's plan in the list).
  const planRank = { demo: 0, lifetime_lite: 1, pro_monthly: 2, team_monthly: 3 };
  const planByOwnerEmail = new Map();
  companyInfo.forEach((info) => {
    const owner = String(info.ownerEmail || "").trim().toLowerCase();
    if (!owner) return;
    const existing = planByOwnerEmail.get(owner);
    if (!existing || (planRank[info.plan] ?? 0) > (planRank[existing] ?? 0)) {
      planByOwnerEmail.set(owner, info.plan);
    }
  });

  const recentUsers = recentUsersAll
    .sort((a, b) => b.createdAtMs - a.createdAtMs)
    .slice(0, 500)
    .map((u) => ({
      ...u,
      plan: planByOwnerEmail.get(String(u.email || "").trim().toLowerCase()) || "demo"
    }));

  return {
    ok: true,
    generatedAtMs: now,
    users: { total: totalUsers, new7d, new30d, active7d, active30d, neverLoggedIn },
    recentUsers,
    growth,
    workspaces: {
      total: companiesSnap.size,
      active30d: activeWorkspaces,
      inactive: Math.max(companiesSnap.size - activeWorkspaces, 0),
      planCounts
    },
    quick: {
      avgWorkspacesPerUser: totalUsers > 0 ? Math.round((companiesSnap.size / totalUsers) * 100) / 100 : 0,
      usersWithMultipleWorkspaces
    },
    topWorkspaces,
    heatmap
  };
});

