exports.getAdminSubscriptionsDetail = onCall({ region: "europe-west2", timeoutSeconds: 60 }, async (request) => {
  const email = String(request.auth?.token?.email || "").trim().toLowerCase();
  if (!request.auth || !SUPPORT_ADMIN_EMAILS.has(email)) {
    throw new HttpsError("permission-denied", "Admin insights are restricted to NivaDesk admins.");
  }

  const now = Date.now();
  const companiesSnap = await admin.firestore().collection("companies").limit(3000).get();

  const planCounts = { demo: 0, lifetime_lite: 0, pro_monthly: 0, team_monthly: 0 };
  const sourceCounts = {};
  let paidNew30d = 0;
  const paidWorkspaces = [];

  companiesSnap.docs.forEach((doc) => {
    const data = doc.data() || {};
    const plan = normalizeBillingPlan(data.billingPlan, "demo");
    planCounts[plan] = (planCounts[plan] || 0) + 1;
    const source = String(data.billingPlanSource || "legacy_default").slice(0, 40);
    const createdMs = data.createdAt && typeof data.createdAt.toMillis === "function" ? data.createdAt.toMillis() : 0;

    if (plan !== "demo") {
      sourceCounts[source] = (sourceCounts[source] || 0) + 1;
      if (createdMs >= now - 30 * 86400000) paidNew30d += 1;
      paidWorkspaces.push({
        id: doc.id,
        name: String(data.name || data.companyName || doc.id).slice(0, 60),
        ownerEmail: String(data.ownerEmail || data.email || "").slice(0, 80),
        plan,
        monthlyGbp: ADMIN_PLAN_MONTHLY_GBP[plan] || 0,
        createdAtMs: createdMs
      });
    }
  });

  paidWorkspaces.sort((a, b) => b.createdAtMs - a.createdAtMs);

  const paidTotal = paidWorkspaces.length;
  const mrrByPlan = {
    lifetime_lite: planCounts.lifetime_lite * ADMIN_PLAN_MONTHLY_GBP.lifetime_lite,
    pro_monthly: planCounts.pro_monthly * ADMIN_PLAN_MONTHLY_GBP.pro_monthly,
    team_monthly: planCounts.team_monthly * ADMIN_PLAN_MONTHLY_GBP.team_monthly
  };
  const mrr = mrrByPlan.lifetime_lite + mrrByPlan.pro_monthly + mrrByPlan.team_monthly;

  return {
    ok: true,
    generatedAtMs: now,
    estimated: true,
    note: "Plan assignments only — live billing (trials, cancellations, payments) is not connected yet.",
    subscriptions: {
      paidTotal,
      paidNew30d,
      planCounts,
      freeDemo: planCounts.demo
    },
    revenue: {
      currency: "GBP",
      mrr,
      arr: mrr * 12,
      arpu: paidTotal > 0 ? Math.round((mrr / paidTotal) * 100) / 100 : 0,
      mrrByPlan
    },
    sources: Object.entries(sourceCounts)
      .sort((a, b) => b[1] - a[1])
      .map(([source, count]) => ({ source, count })),
    recent: paidWorkspaces.slice(0, 10)
  };
});

// ---------------------------------------------------------------------------
// Admin Insights detail: Revenue (estimated — live billing not connected)
// ---------------------------------------------------------------------------

function adminStorageAddonMonthlyGbp(companyData = {}) {
  const mb = activeStorageAddonMB(companyData);
  if (mb >= 200000) return 15;
  if (mb >= 100000) return 9;
  return 0;
}

exports.getAdminRevenueDetail = onCall({ region: "europe-west2", timeoutSeconds: 60 }, async (request) => {
  const email = String(request.auth?.token?.email || "").trim().toLowerCase();
  if (!request.auth || !SUPPORT_ADMIN_EMAILS.has(email)) {
    throw new HttpsError("permission-denied", "Admin insights are restricted to NivaDesk admins.");
  }

  const companiesSnap = await admin.firestore().collection("companies").limit(3000).get();

  let baseMrr = 0;
  let seatsMrr = 0;
  let storageMrr = 0;
  let paidTotal = 0;
  let seatCount = 0;
  let storageAddonCount = 0;
  const mrrByPlan = { lifetime_lite: 0, pro_monthly: 0, team_monthly: 0 };
  const workspaces = [];
  const seatWorkspaces = [];
  const storageWorkspaces = [];
  let storageAddon100 = 0;
  let storageAddon200 = 0;

  companiesSnap.docs.forEach((doc) => {
    const data = doc.data() || {};
    const plan = normalizeBillingPlan(data.billingPlan, "demo");
    if (plan === "demo") return;

    const base = ADMIN_PLAN_MONTHLY_GBP[plan] || 0;
    const seats = plan === "team_monthly" ? activeAdditionalTeamSeats(data) : 0;
    const seatGbp = seats * 5;
    const storageGbp = adminStorageAddonMonthlyGbp(data);

    paidTotal += 1;
    baseMrr += base;
    seatsMrr += seatGbp;
    storageMrr += storageGbp;
    seatCount += seats;
    if (storageGbp > 0) storageAddonCount += 1;

    const workspaceName = String(data.name || data.companyName || doc.id).slice(0, 60);
    const ownerEmail = String(data.ownerEmail || data.email || "").slice(0, 80);
    if (seats > 0) {
      seatWorkspaces.push({ id: doc.id, name: workspaceName, ownerEmail, seats, monthlyGbp: seatGbp });
    }
    if (storageGbp > 0) {
      const addonMB = activeStorageAddonMB(data);
      if (addonMB >= 200000) storageAddon200 += 1; else storageAddon100 += 1;
      storageWorkspaces.push({
        id: doc.id,
        name: workspaceName,
        ownerEmail,
        addonGB: addonMB >= 200000 ? 200 : 100,
        monthlyGbp: storageGbp
      });
    }
    mrrByPlan[plan] = (mrrByPlan[plan] || 0) + base + (plan === "team_monthly" ? seatGbp : 0);

    workspaces.push({
      id: doc.id,
      name: String(data.name || data.companyName || doc.id).slice(0, 60),
      ownerEmail: String(data.ownerEmail || data.email || "").slice(0, 80),
      plan,
      baseGbp: base,
      seatGbp,
      storageGbp,
      totalGbp: base + seatGbp + storageGbp
    });
  });

  workspaces.sort((a, b) => b.totalGbp - a.totalGbp);
  const totalMrr = baseMrr + seatsMrr + storageMrr;

  return {
    ok: true,
    generatedAtMs: Date.now(),
    estimated: true,
    note: "Estimated from plan and add-on assignments at list prices; live billing (payments, refunds, currencies) is not connected yet.",
    revenue: {
      currency: "GBP",
      mrr: totalMrr,
      arr: totalMrr * 12,
      arpu: paidTotal > 0 ? Math.round((totalMrr / paidTotal) * 100) / 100 : 0,
      baseMrr,
      seatsMrr,
      storageMrr,
      mrrByPlan,
      paidTotal,
      seatCount,
      storageAddonCount
    },
    topPaying: workspaces.slice(0, 8),
    addons: {
      seatWorkspaces: seatWorkspaces.sort((a, b) => b.seats - a.seats).slice(0, 10),
      storageWorkspaces: storageWorkspaces.sort((a, b) => b.monthlyGbp - a.monthlyGbp).slice(0, 10),
      storageAddon100,
      storageAddon200
    }
  };
});

